(379443,42161,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn alle so gut zielen würden wie er, ... Recycling viel einfacher.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn alle so gut zielen würden wie er, wäre Recycling viel einfacher.'::text),
