(403727,44859,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il promet qu''il nous ... une photo de chaque étape de son tour du monde.'::text,'enverra'::text,'sera en train d''envoyer'::text,'envoie'::text,'Il promet qu''il nous enverra une photo de chaque étape de son tour du monde.'::text),
(403730,44859,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dünya turunun her durağından bize bir fotoğraf ... söz veriyor.'::text,'göndereceğine'::text,'gönderiyor olacağına'::text,'gönderdiğine'::text,'Dünya turunun her durağından bize bir fotoğraf göndereceğine söz veriyor.'::text),
(403731,44859,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígéri, hogy a világ körüli útja minden állomásáról ... nekünk egy fotót.'::text,'küld'::text,'küldözget majd'::text,'éppen küld'::text,'Megígéri, hogy a világ körüli útja minden állomásáról küld nekünk egy fotót.'::text),
(403743,44861,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Weltreise mit nur einem Rucksack ist leicht ambitioniert, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Eine Weltreise mit nur einem Rucksack ist leicht ambitioniert, oder?'::text),
(403747,44861,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Навколосвітня подорож лише з одним рюкзаком трохи амбітна, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Навколосвітня подорож лише з одним рюкзаком трохи амбітна, правда?'::text),
(403746,44861,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un viaje por el mundo con una sola mochila es un pelín ambicioso, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Un viaje por el mundo con una sola mochila es un pelín ambicioso, ¿verdad?'::text),
(403745,44861,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un tour du monde avec un seul sac à dos, c''est légèrement ambitieux, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Un tour du monde avec un seul sac à dos, c''est légèrement ambitieux, n''est-ce pas ?'::text),
(403748,44861,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tek bir sırt çantasıyla dünya turu biraz iddialı, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Tek bir sırt çantasıyla dünya turu biraz iddialı, değil mi?'::text),
(403749,44861,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy világ körüli út egyetlen hátizsákkal kicsit ambiciózus, ...?'::text,'nem igaz'::text,'nem igaz'::text,'nem igaz'::text,'Egy világ körüli út egyetlen hátizsákkal kicsit ambiciózus, nem igaz?'::text),
(403752,44862,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er liebt seine Weltreise, und die Pinguine ..., offensichtlich.'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Er liebt seine Weltreise, und die Pinguine auch, offensichtlich.'::text),
(403756,44862,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він обожнює свою навколосвітню подорож, і пінгвіни ..., очевидно.'::text,'теж'::text,'теж'::text,'теж ні'::text,'Він обожнює свою навколосвітню подорож, і пінгвіни теж, очевидно.'::text),
(403755,44862,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le encanta su viaje por el mundo, y a los pingüinos ..., obviamente.'::text,'también'::text,'también'::text,'tampoco'::text,'Le encanta su viaje por el mundo, y a los pingüinos también, obviamente.'::text),
(403754,44862,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il adore son tour du monde, et les pingouins ..., évidemment.'::text,'aussi'::text,'aussi'::text,'non plus'::text,'Il adore son tour du monde, et les pingouins aussi, évidemment.'::text),
(403757,44862,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dünya turunu çok seviyor, penguenler de ..., belli ki.'::text,'öyle'::text,'öyle'::text,'öyle değil'::text,'Dünya turunu çok seviyor, penguenler de öyle, belli ki.'::text),
(403758,44862,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Imádja a világ körüli útját, és a pingvinek ..., nyilván.'::text,'is'::text,'is'::text,'sem'::text,'Imádja a világ körüli útját, és a pingvinek is, nyilván.'::text),
(403761,44863,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis nächsten Sommer ... der Typ auf seiner Weltreise jeden Kontinent besucht haben, kein Witz.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis nächsten Sommer wird der Typ auf seiner Weltreise jeden Kontinent besucht haben, kein Witz.'::text),
(403765,44863,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наступного літа бро ... кожен континент у своїй навколосвітній подорожі, без жартів.'::text,'відвідає'::text,'відвідає'::text,'відвідуватиме'::text,'До наступного літа бро відвідає кожен континент у своїй навколосвітній подорожі, без жартів.'::text),
(403764,44863,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el verano que viene, el tío ... todos los continentes en su viaje por el mundo, te lo juro.'::text,'habrá visitado'::text,'visitará'::text,'estará visitando'::text,'Para el verano que viene, el tío habrá visitado todos los continentes en su viaje por el mundo, te lo juro.'::text),
(403763,44863,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici l''été prochain, le frérot ... tous les continents pendant son tour du monde, sans mentir.'::text,'aura visité'::text,'visitera'::text,'sera en train de visiter'::text,'D''ici l''été prochain, le frérot aura visité tous les continents pendant son tour du monde, sans mentir.'::text),
(403766,44863,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önümüzdeki yaza kadar kanka dünya turunda her kıtayı ..., yemin ederim.'::text,'gezmiş olacak'::text,'gezecek'::text,'geziyor olacak'::text,'Önümüzdeki yaza kadar kanka dünya turunda her kıtayı gezmiş olacak, yemin ederim.'::text),
(403767,44863,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő nyárig a tesó a világ körüli útján minden kontinenst ..., nem viccelek.'::text,'bejár'::text,'bejár'::text,'járja majd'::text,'Jövő nyárig a tesó a világ körüli útján minden kontinenst bejár, nem viccelek.'::text),
(403779,44865,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat seinem Vorgesetzten versprochen, die Weltreise innerhalb von 90 Tagen ...'::text,'abzuschließen'::text,'abschließend'::text,'abschließen'::text,'Er hat seinem Vorgesetzten versprochen, die Weltreise innerhalb von 90 Tagen abzuschließen.'::text),
(403783,44865,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він пообіцяв своєму керівникові ... навколосвітню подорож протягом 90 днів.'::text,'завершити'::text,'завершуючи'::text,'завершить'::text,'Він пообіцяв своєму керівникові завершити навколосвітню подорож протягом 90 днів.'::text),
(403782,44865,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prometió a su supervisor ... el viaje por el mundo en un plazo de 90 días.'::text,'completar'::text,'completando'::text,'complete'::text,'Prometió a su supervisor completar el viaje por el mundo en un plazo de 90 días.'::text),
(403781,44865,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a promis à son supérieur de ... le tour du monde sous 90 jours.'::text,'terminer'::text,'terminant'::text,'termine'::text,'Il a promis à son supérieur de terminer le tour du monde sous 90 jours.'::text),
(403784,44865,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amirine dünya turunu 90 gün içinde ... söz verdi.'::text,'tamamlamaya'::text,'tamamlamayı'::text,'tamamla'::text,'Amirine dünya turunu 90 gün içinde tamamlamaya söz verdi.'::text),
(403785,44865,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígérte a felettesének, hogy 90 napon belül ... a világ körüli utat.'::text,'befejezi'::text,'befejezve'::text,'befejez'::text,'Megígérte a felettesének, hogy 90 napon belül befejezi a világ körüli utat.'::text),
(403788,44866,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist mit Pinguinen im Schnee, also war seine Weltreise ... sehr billig.'::text,'sicher nicht'::text,'sicher'::text,'besser nicht'::text,'Er ist mit Pinguinen im Schnee, also war seine Weltreise sicher nicht sehr billig.'::text),
(403792,44866,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він у снігу з пінгвінами, тож його навколосвітня подорож ... дуже дешевою.'::text,'не могла бути'::text,'мабуть, була'::text,'не мала бути'::text,'Він у снігу з пінгвінами, тож його навколосвітня подорож не могла бути дуже дешевою.'::text),
(403791,44866,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está en la nieve con pingüinos, así que su viaje por el mundo ... muy barato.'::text,'no puede haber sido'::text,'debe de haber sido'::text,'no debería haber sido'::text,'Está en la nieve con pingüinos, así que su viaje por el mundo no puede haber sido muy barato.'::text),
(403790,44866,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est dans la neige avec des pingouins, donc son tour du monde ... très bon marché.'::text,'n''a pas pu être'::text,'a dû être'::text,'n''aurait pas dû être'::text,'Il est dans la neige avec des pingouins, donc son tour du monde n''a pas pu être très bon marché.'::text),
(403793,44866,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Penguenlerle karda, yani dünya turu pek ucuz ...'::text,'olmuş olamaz'::text,'olmuş olmalı'::text,'olmamalıydı'::text,'Penguenlerle karda, yani dünya turu pek ucuz olmuş olamaz.'::text),
(403794,44866,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pingvinekkel van a hóban, szóval a világ körüli útja ... nagyon olcsó.'::text,'nem lehetett'::text,'biztosan volt'::text,'nem kellett volna, hogy legyen'::text,'Pingvinekkel van a hóban, szóval a világ körüli útja nem lehetett nagyon olcsó.'::text),
(403797,44867,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Subjekt ließ seine Route für diese Weltreise offenbar im Voraus ...'::text,'planen'::text,'planen'::text,'zu planen'::text,'Das Subjekt ließ seine Route für diese Weltreise offenbar im Voraus planen.'::text),
(403801,44867,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єкт, очевидно, доручив ... свій маршрут для цієї навколосвітньої подорожі заздалегідь.'::text,'спланувати'::text,'спланувати'::text,'планувати'::text,'Суб''єкт, очевидно, доручив спланувати свій маршрут для цієї навколосвітньої подорожі заздалегідь.'::text),
(403800,44867,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evidentemente, el sujeto se hizo ... la ruta de antemano para este viaje por el mundo.'::text,'planificar'::text,'planificar'::text,'planificar'::text,'Evidentemente, el sujeto se hizo planificar la ruta de antemano para este viaje por el mundo.'::text),
(403799,44867,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet a manifestement fait ... son itinéraire à l''avance pour ce tour du monde.'::text,'planifier'::text,'planifier'::text,'planifier'::text,'Le sujet a manifestement fait planifier son itinéraire à l''avance pour ce tour du monde.'::text),
(403802,44867,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görünüşe göre denek bu dünya yolculuğu için rotasını önceden ...'::text,'planlatmıştı'::text,'planlatmıştı'::text,'planlatmıştı'::text,'Görünüşe göre denek bu dünya yolculuğu için rotasını önceden planlatmıştı.'::text),
(403803,44867,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany láthatóan előre ... az útvonalát erre a világ körüli útra.'::text,'megterveztette'::text,'megterveztette'::text,'terveztette'::text,'Az alany láthatóan előre megterveztette az útvonalát erre a világ körüli útra.'::text),
(403806,44868,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, dass seine Weltreise ewig ...! Nach Hause zu gehen wäre ein totaler Albtraum!'::text,'dauern würde'::text,'dauern wird'::text,'dauert'::text,'Er wünscht sich, dass seine Weltreise ewig dauern würde! Nach Hause zu gehen wäre ein totaler Albtraum!'::text),
(403810,44868,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хоче, щоб його навколосвітня подорож ... вічно! Повернутися додому було б суцільним жахіттям!'::text,'тривала'::text,'триватиме'::text,'триває'::text,'Він хоче, щоб його навколосвітня подорож тривала вічно! Повернутися додому було б суцільним жахіттям!'::text),
(403809,44868,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desea que su viaje por el mundo ... para siempre! ¡Volver a casa sería una pesadilla total!'::text,'durara'::text,'durará'::text,'dura'::text,'¡Desea que su viaje por el mundo durara para siempre! ¡Volver a casa sería una pesadilla total!'::text),
(403808,44868,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait que son tour du monde ... pour toujours ! Rentrer à la maison serait un cauchemar total !'::text,'dure'::text,'durera'::text,'dure'::text,'Il aimerait que son tour du monde dure pour toujours ! Rentrer à la maison serait un cauchemar total !'::text),
(403811,44868,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke dünya turu sonsuza kadar ...! Eve dönmek tam bir kâbus olurdu!'::text,'sürse'::text,'sürecek'::text,'sürüyor'::text,'Keşke dünya turu sonsuza kadar sürse! Eve dönmek tam bir kâbus olurdu!'::text),
(403812,44868,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak a világ körüli útja örökké ...! Hazamenni totális rémálom lenne!'::text,'tartana'::text,'tart majd'::text,'tart'::text,'Azt kívánja, bárcsak a világ körüli útja örökké tartana! Hazamenni totális rémálom lenne!'::text),
(346071,38453,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die beiden Delegationen haben die Papiere unterschrieben, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Die beiden Delegationen haben die Papiere unterschrieben, oder?'::text),
(346075,38453,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обидві делегації підписали документи, ...?'::text,'так'::text,'так'::text,'так'::text,'Обидві делегації підписали документи, так?'::text),
(346074,38453,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las dos delegaciones firmaron los papeles, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Las dos delegaciones firmaron los papeles, ¿verdad?'::text),
(346073,38453,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux délégations ont signé les papiers, ... ?'::text,'non'::text,'non'::text,'non'::text,'Les deux délégations ont signé les papiers, non ?'::text),
(346076,38453,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki heyet de belgeleri imzaladı, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'İki heyet de belgeleri imzaladı, değil mi?'::text),
(346077,38453,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két delegáció aláírta a papírokat, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A két delegáció aláírta a papírokat, ugye?'::text),
(346080,38454,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die türkise Delegation hat unterschrieben, weil sie unterschreiben wollte, und die orangefarbene ...'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Die türkise Delegation hat unterschrieben, weil sie unterschreiben wollte, und die orangefarbene auch.'::text),
(346084,38454,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бірюзова делегація підписала, бо хотіла підписати, і помаранчева ...'::text,'теж'::text,'теж'::text,'теж ні'::text,'Бірюзова делегація підписала, бо хотіла підписати, і помаранчева теж.'::text),
(346083,38454,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La delegación turquesa firmó porque quería firmar, y la naranja ...'::text,'también'::text,'también'::text,'tampoco'::text,'La delegación turquesa firmó porque quería firmar, y la naranja también.'::text),
(346082,38454,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La délégation turquoise a signé parce qu''elle voulait signer, et l''orange ...'::text,'aussi'::text,'aussi'::text,'non plus'::text,'La délégation turquoise a signé parce qu''elle voulait signer, et l''orange aussi.'::text),
(346085,38454,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Turkuaz heyet imzalamak istediği için imzaladı, turuncu olan da ...'::text,'öyle yaptı'::text,'öyle yaptı'::text,'yapmadı'::text,'Turkuaz heyet imzalamak istediği için imzaladı, turuncu olan da öyle yaptı.'::text),
(346086,38454,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A türkiz delegáció aláírt, mert alá akart írni, és a narancssárga ...'::text,'is'::text,'is'::text,'sem'::text,'A türkiz delegáció aláírt, mert alá akart írni, és a narancssárga is.'::text),
(346089,38455,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vermutlich ... die beiden Delegationen wochenlang verhandelt, bevor diese Unterzeichnung stattfand.'::text,'hatten'::text,'haben'::text,'verhandelten'::text,'Vermutlich hatten die beiden Delegationen wochenlang verhandelt, bevor diese Unterzeichnung stattfand.'::text),
(346093,38455,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Імовірно, обидві делегації ... тижнями, перш ніж відбулося це підписання.'::text,'вели переговори'::text,'ведуть переговори'::text,'вели переговори'::text,'Імовірно, обидві делегації вели переговори тижнями, перш ніж відбулося це підписання.'::text),
(346092,38455,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presumiblemente, las dos delegaciones ... durante semanas antes de que se produjera esta firma.'::text,'habían estado negociando'::text,'han estado negociando'::text,'estaban negociando'::text,'Presumiblemente, las dos delegaciones habían estado negociando durante semanas antes de que se produjera esta firma.'::text),
(346091,38455,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vraisemblablement, les deux délégations ... depuis des semaines avant que cette signature n''ait lieu.'::text,'négociaient'::text,'négocient'::text,'étaient en train de négocier'::text,'Vraisemblablement, les deux délégations négociaient depuis des semaines avant que cette signature n''ait lieu.'::text),
(346094,38455,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muhtemelen iki heyet bu imza gerçekleşmeden önce haftalardır ...'::text,'müzakere ediyordu'::text,'müzakere ediyor'::text,'müzakere ediyordu'::text,'Muhtemelen iki heyet bu imza gerçekleşmeden önce haftalardır müzakere ediyordu.'::text),
(346095,38455,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Feltehetően a két delegáció hetek óta ..., mielőtt ez az aláírás megtörtént.'::text,'tárgyalt'::text,'tárgyal'::text,'éppen tárgyalt'::text,'Feltehetően a két delegáció hetek óta tárgyalt, mielőtt ez az aláírás megtörtént.'::text),
(346107,38457,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang ... die Delegationen zehn Stunden an diesem Tisch gesessen haben. Ein absoluter Albtraum!'::text,'werden'::text,'werden'::text,'werden'::text,'Bis Sonnenuntergang werden die Delegationen zehn Stunden an diesem Tisch gesessen haben. Ein absoluter Albtraum!'::text),
(346111,38457,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця делегації ... за цим столом десять годин. Абсолютне жахіття!'::text,'просидять'::text,'сидітимуть'::text,'посидять'::text,'До заходу сонця делегації просидять за цим столом десять годин. Абсолютне жахіття!'::text),
(346110,38457,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, las delegaciones ... diez horas sentadas en esta mesa. ¡Una pesadilla absoluta!'::text,'habrán estado'::text,'estarán'::text,'se sentarán'::text,'Para el atardecer, las delegaciones habrán estado diez horas sentadas en esta mesa. ¡Una pesadilla absoluta!'::text),
(346109,38457,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, les délégations ... dix heures à cette table. Un cauchemar absolu !'::text,'auront passé'::text,'passeront'::text,'passeront'::text,'D''ici le coucher du soleil, les délégations auront passé dix heures à cette table. Un cauchemar absolu !'::text),
(346112,38457,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar heyetler bu masada on saattir ..., tam bir kâbus!'::text,'oturuyor olacak'::text,'oturuyor olacak'::text,'oturacak'::text,'Gün batımına kadar heyetler bu masada on saattir oturuyor olacak, tam bir kâbus!'::text),
(346113,38457,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtáig a delegációk már tíz órája ... ennél az asztalnál. Abszolút rémálom!'::text,'ülnek majd'::text,'ülnek majd'::text,'fognak leülni'::text,'Napnyugtáig a delegációk már tíz órája ülnek majd ennél az asztalnál. Abszolút rémálom!'::text),
(346116,38458,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die orangefarbene Delegation gegangen wäre, ... der ganze Deal in einer totalen Katastrophe geendet!'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn die orangefarbene Delegation gegangen wäre, hätte der ganze Deal in einer totalen Katastrophe geendet!'::text),
(346120,38458,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби помаранчева делегація пішла, вся угода ... повною катастрофою!'::text,'закінчилася б'::text,'закінчиться'::text,'закінчилася'::text,'Якби помаранчева делегація пішла, вся угода закінчилася б повною катастрофою!'::text),
(346119,38458,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si la delegación naranja se hubiera ido, todo el acuerdo ... en un desastre total!'::text,'habría acabado'::text,'acabará'::text,'acabó'::text,'¡Si la delegación naranja se hubiera ido, todo el acuerdo habría acabado en un desastre total!'::text),
(346118,38458,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la délégation orange était partie, tout l''accord ... en désastre total !'::text,'aurait fini'::text,'finira'::text,'a fini'::text,'Si la délégation orange était partie, tout l''accord aurait fini en désastre total !'::text),
(346121,38458,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Turuncu heyet çekip gitseydi, bütün anlaşma tam bir felaketle ...!'::text,'biterdi'::text,'bitecek'::text,'bitti'::text,'Turuncu heyet çekip gitseydi, bütün anlaşma tam bir felaketle biterdi!'::text),
(346122,38458,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a narancssárga delegáció kivonult volna, az egész üzlet teljes katasztrófával ...!'::text,'végződött volna'::text,'végződik majd'::text,'végződött'::text,'Ha a narancssárga delegáció kivonult volna, az egész üzlet teljes katasztrófával végződött volna!'::text),
(346125,38459,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sich die Delegationen gestern nicht geeinigt hätten, ... sie jetzt immer noch an diesem Tisch.'::text,'säßen'::text,'hätten gesessen'::text,'werden sitzen'::text,'Wenn sich die Delegationen gestern nicht geeinigt hätten, säßen sie jetzt immer noch an diesem Tisch.'::text),
(346129,38459,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби делегації вчора не домовилися, вони ... й досі за цим столом.'::text,'сиділи б'::text,'сиділи б'::text,'сидітимуть'::text,'Якби делегації вчора не домовилися, вони сиділи б й досі за цим столом.'::text),
(346128,38459,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si las delegaciones no se hubieran puesto de acuerdo ayer, ahora ... todavía sentadas en esta mesa.'::text,'estarían'::text,'habrían estado'::text,'estarán'::text,'Si las delegaciones no se hubieran puesto de acuerdo ayer, ahora estarían todavía sentadas en esta mesa.'::text),
(346127,38459,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les délégations ne s''étaient pas mises d''accord hier, elles ... encore assises à cette table maintenant.'::text,'seraient'::text,'auraient été'::text,'seront'::text,'Si les délégations ne s''étaient pas mises d''accord hier, elles seraient encore assises à cette table maintenant.'::text),
(346130,38459,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heyetler dün anlaşmasaydı, şimdi hâlâ bu masada ...'::text,'oturuyor olurlardı'::text,'oturmuş olurlardı'::text,'oturuyor olacaklar'::text,'Heyetler dün anlaşmasaydı, şimdi hâlâ bu masada oturuyor olurlardı.'::text),
(346131,38459,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a delegációk tegnap nem egyeztek volna meg, most is még ennél az asztalnál ...'::text,'ülnének'::text,'ültek volna'::text,'fognak ülni'::text,'Ha a delegációk tegnap nem egyeztek volna meg, most is még ennél az asztalnál ülnének.'::text),
(346134,38460,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Deal soll nach langen Gesprächen von beiden Delegationen ...'::text,'vereinbart worden sein'::text,'vereinbaren'::text,'vereinbarend'::text,'Der Deal soll nach langen Gesprächen von beiden Delegationen vereinbart worden sein.'::text),
(346138,38460,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, угоду ... обома делегаціями після довгих переговорів.'::text,'було узгоджено'::text,'узгодити'::text,'узгодження'::text,'Кажуть, угоду було узгоджено обома делегаціями після довгих переговорів.'::text),
(346137,38460,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que el acuerdo ... por ambas delegaciones tras largas conversaciones.'::text,'fue acordado'::text,'acordar'::text,'acordando'::text,'Se dice que el acuerdo fue acordado por ambas delegaciones tras largas conversaciones.'::text),
(346136,38460,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que l''accord ... par les deux délégations après de longues discussions.'::text,'a été conclu'::text,'conclure'::text,'concluant'::text,'On dit que l''accord a été conclu par les deux délégations après de longues discussions.'::text),
(346139,38460,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anlaşmanın uzun görüşmelerden sonra iki heyet tarafından ... söyleniyor.'::text,'kabul edildiği'::text,'kabul etmek'::text,'kabul ederek'::text,'Anlaşmanın uzun görüşmelerden sonra iki heyet tarafından kabul edildiği söyleniyor.'::text),
(346140,38460,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag a megállapodást hosszú tárgyalások után mindkét delegáció ...'::text,'elfogadta'::text,'elfogadni'::text,'elfogadva'::text,'Állítólag a megállapodást hosszú tárgyalások után mindkét delegáció elfogadta.'::text),
(346143,38461,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann im grauen Anzug weigerte sich, ..., bis seine Delegation jede Seite gelesen hatte.'::text,'zu unterschreiben'::text,'unterschreibend'::text,'unterschrieben zu haben'::text,'Der Mann im grauen Anzug weigerte sich, zu unterschreiben, bis seine Delegation jede Seite gelesen hatte.'::text),
(346147,38461,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік у сірому костюмі відмовився ..., доки його делегація не прочитала кожну сторінку.'::text,'підписувати'::text,'підписання'::text,'підписавши'::text,'Чоловік у сірому костюмі відмовився підписувати, доки його делегація не прочитала кожну сторінку.'::text),
(346146,38461,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre del traje gris se negó a ... hasta que su delegación hubiera leído todas las páginas.'::text,'firmar'::text,'firmando'::text,'haber firmado'::text,'El hombre del traje gris se negó a firmar hasta que su delegación hubiera leído todas las páginas.'::text),
(346145,38461,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme au costume gris a refusé de ... tant que sa délégation n''avait pas lu chaque page.'::text,'signer'::text,'signant'::text,'avoir signé'::text,'L''homme au costume gris a refusé de signer tant que sa délégation n''avait pas lu chaque page.'::text),
(346148,38461,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gri takım elbiseli adam, heyeti her sayfayı okuyana kadar ... reddetti.'::text,'imzalamayı'::text,'imzalayarak'::text,'imzalamış olmayı'::text,'Gri takım elbiseli adam, heyeti her sayfayı okuyana kadar imzalamayı reddetti.'::text),
(346149,38461,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szürke öltönyös férfi nem volt hajlandó ..., amíg a delegációja el nem olvasott minden oldalt.'::text,'aláírni'::text,'aláírás'::text,'aláírva'::text,'A szürke öltönyös férfi nem volt hajlandó aláírni, amíg a delegációja el nem olvasott minden oldalt.'::text),
(346152,38462,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die beiden Delegationen ... jede Seite vor der Unterschrift gelesen haben, also ging nichts schief.'::text,'müssen'::text,'sollten'::text,'können nicht'::text,'Die beiden Delegationen müssen jede Seite vor der Unterschrift gelesen haben, also ging nichts schief.'::text),
(346156,38462,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обидві делегації ... кожну сторінку перед підписанням, тож усе пройшло гладко.'::text,'напевно, прочитали'::text,'мали б прочитати'::text,'не могли прочитати'::text,'Обидві делегації напевно, прочитали кожну сторінку перед підписанням, тож усе пройшло гладко.'::text),
(346155,38462,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las dos delegaciones ... cada página antes de firmar, así que nada salió mal.'::text,'deben de haber leído'::text,'deberían haber leído'::text,'no pueden haber leído'::text,'Las dos delegaciones deben de haber leído cada página antes de firmar, así que nada salió mal.'::text),
(346154,38462,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux délégations ... chaque page avant de signer, donc rien n''a mal tourné.'::text,'ont dû lire'::text,'auraient dû lire'::text,'n''ont pas pu lire'::text,'Les deux délégations ont dû lire chaque page avant de signer, donc rien n''a mal tourné.'::text),
(346157,38462,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki heyet de imzalamadan önce her sayfayı ..., yani hiçbir şey ters gitmedi.'::text,'okumuş olmalı'::text,'okumalıydı'::text,'okumuş olamaz'::text,'İki heyet de imzalamadan önce her sayfayı okumuş olmalı, yani hiçbir şey ters gitmedi.'::text),
(346158,38462,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két delegáció aláírás előtt ... minden oldalt, így semmi sem ment félre.'::text,'biztosan elolvasta'::text,'el kellett volna olvasnia'::text,'nem olvashatta el'::text,'A két delegáció aláírás előtt biztosan elolvasta minden oldalt, így semmi sem ment félre.'::text),
(384411,42713,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den versiegelten Umschlag, als sie lachte, also war das Siegel auch in ihrer Hand.'::text,'hielt gerade'::text,'hielt'::text,'hat gehalten'::text,'Sie hielt gerade den versiegelten Umschlag, als sie lachte, also war das Siegel auch in ihrer Hand.'::text),
(384415,42713,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... запечатаний конверт, коли засміялася, тож печатка теж була в її руці.'::text,'тримала'::text,'потримала'::text,'потримала'::text,'Вона тримала запечатаний конверт, коли засміялася, тож печатка теж була в її руці.'::text),
(384414,42713,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... el sobre sellado cuando se rio, así que el sello también estaba en su mano.'::text,'estaba sosteniendo'::text,'sostuvo'::text,'ha sostenido'::text,'Ella estaba sosteniendo el sobre sellado cuando se rio, así que el sello también estaba en su mano.'::text),
(384413,42713,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... l''enveloppe scellée quand elle a ri, donc le sceau était aussi dans sa main.'::text,'tenait'::text,'a tenu'::text,'a tenu'::text,'Elle tenait l''enveloppe scellée quand elle a ri, donc le sceau était aussi dans sa main.'::text),
(384416,42713,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güldüğünde mühürlü zarfı ..., yani mühür de elindeydi.'::text,'tutuyordu'::text,'tuttu'::text,'tuttu'::text,'Güldüğünde mühürlü zarfı tutuyordu, yani mühür de elindeydi.'::text),
(384417,42713,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a lepecsételt borítékot, amikor felnevetett, így a pecsét is a kezében volt.'::text,'Épp fogta'::text,'Megfogta'::text,'Fogta'::text,'Épp fogta a lepecsételt borítékot, amikor felnevetett, így a pecsét is a kezében volt.'::text),
(384420,42714,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vermutlich ... das Wachssiegel die Ergebnisse seit etwa einer Woche geheim.'::text,'hält'::text,'hält gerade'::text,'hält'::text,'Vermutlich hält das Wachssiegel die Ergebnisse seit etwa einer Woche geheim.'::text),
(384424,42714,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Імовірно, воскова печатка ... результати в таємниці приблизно тиждень.'::text,'тримає'::text,'тримає'::text,'тримає'::text,'Імовірно, воскова печатка тримає результати в таємниці приблизно тиждень.'::text),
(384423,42714,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presumiblemente, el sello de cera ... los resultados en secreto durante aproximadamente una semana.'::text,'ha estado manteniendo'::text,'está manteniendo'::text,'mantiene'::text,'Presumiblemente, el sello de cera ha estado manteniendo los resultados en secreto durante aproximadamente una semana.'::text),
(384422,42714,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vraisemblablement, le sceau de cire ... les résultats secrets depuis environ une semaine.'::text,'garde'::text,'est en train de garder'::text,'garde'::text,'Vraisemblablement, le sceau de cire garde les résultats secrets depuis environ une semaine.'::text),
(384425,42714,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muhtemelen mum mühür sonuçları yaklaşık bir haftadır gizli ...'::text,'tutuyor'::text,'tutuyor'::text,'tutar'::text,'Muhtemelen mum mühür sonuçları yaklaşık bir haftadır gizli tutuyor.'::text),
(384426,42714,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Feltehetően a viaszpecsét körülbelül egy hete ... titokban az eredményeket.'::text,'tartja'::text,'tartja éppen'::text,'tartja'::text,'Feltehetően a viaszpecsét körülbelül egy hete tartja titokban az eredményeket.'::text),
(384438,42716,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ..., seit sie ihm dieses rote Siegel gezeigt hat. Totale Panik!'::text,'zittert'::text,'hat gezittert'::text,'zittert gerade'::text,'Er zittert, seit sie ihm dieses rote Siegel gezeigt hat. Totale Panik!'::text),
(384442,42716,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... відтоді, як вона показала йому ту червону печатку. Суцільна паніка!'::text,'тремтить'::text,'тремтів'::text,'тремтить'::text,'Він тремтить відтоді, як вона показала йому ту червону печатку. Суцільна паніка!'::text),
(384441,42716,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... desde que ella le enseñó ese sello rojo. ¡Pánico total!'::text,'lleva temblando'::text,'ha temblado'::text,'está temblando'::text,'Él lleva temblando desde que ella le enseñó ese sello rojo. ¡Pánico total!'::text),
(384440,42716,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... depuis qu''elle lui a montré ce sceau rouge. Panique totale !'::text,'tremble'::text,'a tremblé'::text,'est en train de trembler'::text,'Il tremble depuis qu''elle lui a montré ce sceau rouge. Panique totale !'::text),
(384443,42716,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kız ona o kırmızı mührü gösterdiğinden beri ..., tam bir panik!'::text,'titriyor'::text,'titredi'::text,'titriyor'::text,'Kız ona o kırmızı mührü gösterdiğinden beri titriyor, tam bir panik!'::text),
(384444,42716,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azóta ..., hogy a lány megmutatta neki azt a piros pecsétet. Teljes pánik!'::text,'remeg'::text,'remegett'::text,'remeg éppen'::text,'Azóta remeg, hogy a lány megmutatta neki azt a piros pecsétet. Teljes pánik!'::text),
(384447,42717,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie das Siegel brach, ..., wie man atmet. Totale Panik!'::text,'hatte er schon vergessen'::text,'hat er schon vergessen'::text,'vergaß er schon'::text,'Als sie das Siegel brach, hatte er schon vergessen, wie man atmet. Totale Panik!'::text),
(384451,42717,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона зламала печатку, він уже ..., як дихати. Повна паніка!'::text,'забув'::text,'забув'::text,'забув'::text,'Поки вона зламала печатку, він уже забув, як дихати. Повна паніка!'::text),
(384450,42717,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando ella rompió el sello, él ya ... cómo respirar. ¡Pánico total!'::text,'había olvidado'::text,'ha olvidado'::text,'olvidó'::text,'Para cuando ella rompió el sello, él ya había olvidado cómo respirar. ¡Pánico total!'::text),
(384449,42717,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où elle a brisé le sceau, il ... comment respirer. Panique totale !'::text,'avait oublié'::text,'a oublié'::text,'oublia'::text,'Au moment où elle a brisé le sceau, il avait oublié comment respirer. Panique totale !'::text),
(384452,42717,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kız mührü kırdığında o çoktan nasıl nefes alınacağını ..., tam bir panik!'::text,'unutmuştu'::text,'unuttu'::text,'unuttu'::text,'Kız mührü kırdığında o çoktan nasıl nefes alınacağını unutmuştu, tam bir panik!'::text),
(384453,42717,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire feltörte a pecsétet, ő már ..., hogyan kell lélegezni. Totális pánik!'::text,'elfelejtette'::text,'elfelejtette'::text,'elfelejtette'::text,'Mire feltörte a pecsétet, ő már elfelejtette, hogyan kell lélegezni. Totális pánik!'::text),
(384456,42718,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Siegel gebrochen wäre, ... alle die Ergebnisse schon.'::text,'wüssten'::text,'werden wissen'::text,'wissen'::text,'Wenn das Siegel gebrochen wäre, wüssten alle die Ergebnisse schon.'::text),
(384460,42718,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби печатку зламали, всі вже ... результати.'::text,'знали б'::text,'знатимуть'::text,'знають'::text,'Якби печатку зламали, всі вже знали б результати.'::text),
(384459,42718,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el sello estuviera roto, todos ya ... los resultados.'::text,'sabrían'::text,'sabrán'::text,'saben'::text,'Si el sello estuviera roto, todos ya sabrían los resultados.'::text),
(384458,42718,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le sceau était brisé, tout le monde ... déjà les résultats.'::text,'connaîtrait'::text,'connaîtra'::text,'connaît'::text,'Si le sceau était brisé, tout le monde connaîtrait déjà les résultats.'::text),
(384461,42718,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mühür kırık olsaydı, herkes sonuçları çoktan ...'::text,'bilirdi'::text,'bilecek'::text,'biliyor'::text,'Mühür kırık olsaydı, herkes sonuçları çoktan bilirdi.'::text),
(384462,42718,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a pecsét fel lenne törve, már mindenki ... az eredményeket.'::text,'tudná'::text,'tudni fogja'::text,'tudja'::text,'Ha a pecsét fel lenne törve, már mindenki tudná az eredményeket.'::text),
(384465,42719,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stell dir vor: Es heißt, dass der Umschlag vom Direktor mit einem echten Wachssiegel ...'::text,'verschlossen wurde'::text,'verschloss'::text,'gerade verschloss'::text,'Stell dir vor: Es heißt, dass der Umschlag vom Direktor mit einem echten Wachssiegel verschlossen wurde.'::text),
(384469,42719,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви: конверт ... справжньою восковою печаткою директором, кажуть.'::text,'було закрито'::text,'закрив'::text,'закривав'::text,'Уяви: конверт було закрито справжньою восковою печаткою директором, кажуть.'::text),
(384468,42719,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Flipa: el sobre ... con un sello de cera de verdad por el director, al parecer.'::text,'fue cerrado'::text,'cerró'::text,'estaba cerrando'::text,'Flipa: el sobre fue cerrado con un sello de cera de verdad por el director, al parecer.'::text),
(384467,42719,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute ça : l''enveloppe ... avec un vrai sceau de cire par le directeur, apparemment.'::text,'a été fermée'::text,'a fermé'::text,'fermait'::text,'Écoute ça : l''enveloppe a été fermée avec un vrai sceau de cire par le directeur, apparemment.'::text),
(384470,42719,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şuna bak: zarf, müdür tarafından gerçek bir mum mühürle ..., öyle diyorlar.'::text,'kapatılmış'::text,'kapatmış'::text,'kapatıyormuş'::text,'Şuna bak: zarf, müdür tarafından gerçek bir mum mühürle kapatılmış, öyle diyorlar.'::text),
(384471,42719,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj: a borítékot állítólag maga az igazgató ... le egy igazi viaszpecséttel.'::text,'zárta'::text,'zárták'::text,'zárta éppen'::text,'Figyelj: a borítékot állítólag maga az igazgató zárta le egy igazi viaszpecséttel.'::text),
(384474,42720,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Umschlag, ... rotes Siegel noch verschlossen war, enthielt die Namen der Gewinner.'::text,'dessen'::text,'der'::text,'das'::text,'Der Umschlag, dessen rotes Siegel noch verschlossen war, enthielt die Namen der Gewinner.'::text),
(384478,42720,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Конверт, ... червона печатка була ще закрита, містив імена переможців.'::text,'чия'::text,'який'::text,'що'::text,'Конверт, чия червона печатка була ще закрита, містив імена переможців.'::text),
(384477,42720,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sobre, ... sello rojo seguía cerrado, contenía los nombres de los ganadores.'::text,'cuyo'::text,'el cual'::text,'que'::text,'El sobre, cuyo sello rojo seguía cerrado, contenía los nombres de los ganadores.'::text),
(384476,42720,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''enveloppe, ... le sceau rouge était encore fermé, contenait les noms des gagnants.'::text,'dont'::text,'laquelle'::text,'que'::text,'L''enveloppe, dont le sceau rouge était encore fermé, contenait les noms des gagnants.'::text),
(384479,42720,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırmızı mührü hâlâ kapalı olan ... zarf, kazananların isimlerini içeriyordu.'::text,''::text,NULL::text,NULL::text,'Kırmızı mührü hâlâ kapalı olan zarf, kazananların isimlerini içeriyordu.'::text),
(384480,42720,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A boríték, ... piros pecsétje még mindig zárva volt, a győztesek nevét rejtette.'::text,'amelynek'::text,'amely'::text,'ami'::text,'A boríték, amelynek piros pecsétje még mindig zárva volt, a győztesek nevét rejtette.'::text),
(384492,42722,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gruppe fing an zu feiern, ... das Siegel gebrochen und das Ergebnis vorgelesen war.'::text,'sobald'::text,'falls'::text,'außer wenn'::text,'Die Gruppe fing an zu feiern, sobald das Siegel gebrochen und das Ergebnis vorgelesen war.'::text),
(384496,42722,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Компанія почала святкувати, ... печатку зламали й результат зачитали.'::text,'щойно'::text,'на випадок, якщо'::text,'хіба що'::text,'Компанія почала святкувати, щойно печатку зламали й результат зачитали.'::text),
(384495,42722,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El grupo empezó a celebrar ... se rompió el sello y se leyó el resultado.'::text,'en cuanto'::text,'por si'::text,'a menos que'::text,'El grupo empezó a celebrar en cuanto se rompió el sello y se leyó el resultado.'::text),
(384494,42722,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe a commencé à fêter ça ... le sceau a été brisé et le résultat lu.'::text,'dès que'::text,'au cas où'::text,'à moins que'::text,'Le groupe a commencé à fêter ça dès que le sceau a été brisé et le résultat lu.'::text),
(384497,42722,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup, mühür kırılıp sonuç ... kutlamaya başladı.'::text,'okunur okunmaz'::text,'okunursa diye'::text,'okunmadıkça'::text,'Grup, mühür kırılıp sonuç okunur okunmaz kutlamaya başladı.'::text),
(384498,42722,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapat ünnepelni kezdett, ... feltörték a pecsétet és felolvasták az eredményt.'::text,'amint'::text,'arra az esetre, ha'::text,'hacsak nem'::text,'A csapat ünnepelni kezdett, amint feltörték a pecsétet és felolvasták az eredményt.'::text),
(384501,42723,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Laut Agenda ... das Team bis 18 Uhr das Siegel der Ergebnisse gebrochen haben.'::text,'wird'::text,'wird'::text,'bricht'::text,'Laut Agenda wird das Team bis 18 Uhr das Siegel der Ergebnisse gebrochen haben.'::text),
(384505,42723,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Згідно з порядком денним, до 18:00 команда ... печатку на результатах.'::text,'зламає'::text,'зламає'::text,'ламає'::text,'Згідно з порядком денним, до 18:00 команда зламає печатку на результатах.'::text),
(384504,42723,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según la agenda, para las 18:00 el equipo ... el sello de los resultados.'::text,'habrá roto'::text,'romperá'::text,'rompe'::text,'Según la agenda, para las 18:00 el equipo habrá roto el sello de los resultados.'::text),
(384503,42723,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selon l''ordre du jour, d''ici 18 h l''équipe ... le sceau des résultats.'::text,'aura brisé'::text,'brisera'::text,'brise'::text,'Selon l''ordre du jour, d''ici 18 h l''équipe aura brisé le sceau des résultats.'::text),
(384506,42723,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gündeme göre ekip saat 18.00''e kadar sonuçların mührünü ...'::text,'kırmış olacak'::text,'kıracak'::text,'kırar'::text,'Gündeme göre ekip saat 18.00''e kadar sonuçların mührünü kırmış olacak.'::text),
(384507,42723,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A napirend szerint a csapat 18 óráig ... a pecsétet az eredményeken.'::text,'feltöri'::text,'fel fogja törni'::text,'töri'::text,'A napirend szerint a csapat 18 óráig feltöri a pecsétet az eredményeken.'::text),
(356502,39612,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit drei absolut endlosen Tagen auf diese Fracht, und endlich ist sie da!'::text,'warten'::text,'warten gerade'::text,'warten'::text,'Sie warten seit drei absolut endlosen Tagen auf diese Fracht, und endlich ist sie da!'::text),
(356506,39612,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... на цей вантаж три абсолютно нескінченні дні, і нарешті він тут!'::text,'чекають'::text,'чекають'::text,'чекають'::text,'Вони чекають на цей вантаж три абсолютно нескінченні дні, і нарешті він тут!'::text),
(356505,39612,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos ... esta carga tres días absolutamente eternos, y por fin está aquí!'::text,'llevan esperando'::text,'están esperando'::text,'esperan'::text,'¡Ellos llevan esperando esta carga tres días absolutamente eternos, y por fin está aquí!'::text),
(356504,39612,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... cette cargaison depuis trois jours absolument interminables, et elle est enfin là !'::text,'attendent'::text,'sont en train d''attendre'::text,'attendent'::text,'Ils attendent cette cargaison depuis trois jours absolument interminables, et elle est enfin là !'::text),
(356507,39612,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bitmek bilmeyen üç gündür bu yükü ... ve sonunda geldi!'::text,'bekliyorlar'::text,'bekliyorlar'::text,'beklerler'::text,'Bitmek bilmeyen üç gündür bu yükü bekliyorlar ve sonunda geldi!'::text),
(356508,39612,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már három végtelenül hosszú napja ... erre a rakományra, és végre itt van!'::text,'várnak'::text,'várnak éppen'::text,'várnak'::text,'Már három végtelenül hosszú napja várnak erre a rakományra, és végre itt van!'::text),
(356511,39613,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Truck ... mit der Fracht herein, als der Arbeiter vor purer Freude schrie!'::text,'rollte gerade'::text,'rollte'::text,'ist gerollt'::text,'Der Truck rollte gerade mit der Fracht herein, als der Arbeiter vor purer Freude schrie!'::text),
(356515,39613,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вантажівка ... з вантажем, коли робітник закричав від абсолютної радості!'::text,'заїжджала'::text,'заїхала'::text,'заїхала'::text,'Вантажівка заїжджала з вантажем, коли робітник закричав від абсолютної радості!'::text),
(356514,39613,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El camión ... con la carga cuando el trabajador gritó de pura alegría!'::text,'estaba entrando'::text,'entró'::text,'ha entrado'::text,'¡El camión estaba entrando con la carga cuando el trabajador gritó de pura alegría!'::text),
(356513,39613,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le camion ... avec la cargaison quand l''ouvrier a hurlé de joie absolue !'::text,'entrait'::text,'est entré'::text,'est entré'::text,'Le camion entrait avec la cargaison quand l''ouvrier a hurlé de joie absolue !'::text),
(356516,39613,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İşçi büyük bir sevinçle bağırdığında kamyon yükle birlikte içeri ...!'::text,'giriyordu'::text,'girdi'::text,'girdi'::text,'İşçi büyük bir sevinçle bağırdığında kamyon yükle birlikte içeri giriyordu!'::text),
(356517,39613,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kamion ... a rakománnyal, amikor a munkás felkiáltott a tiszta örömtől!'::text,'gurult be éppen'::text,'begurult'::text,'begurult'::text,'A kamion gurult be éppen a rakománnyal, amikor a munkás felkiáltott a tiszta örömtől!'::text),
(356520,39614,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stell dir vor: Er hat mir erzählt, dass er, seit er neunzehn ist, auf diesem Hof Fracht ...'::text,'abfertigt'::text,'abfertigte'::text,'gerade abfertigt'::text,'Stell dir vor: Er hat mir erzählt, dass er, seit er neunzehn ist, auf diesem Hof Fracht abfertigt.'::text),
(356524,39614,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви: він сказав мені, що ... вантажі на цьому дворі з дев''ятнадцяти років.'::text,'обробляє'::text,'обробляв'::text,'обробляє'::text,'Уяви: він сказав мені, що обробляє вантажі на цьому дворі з дев''ятнадцяти років.'::text),
(356523,39614,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Flipa: me dijo que ... carga en este patio desde los diecinueve.'::text,'lleva manejando'::text,'manejó'::text,'está manejando'::text,'Flipa: me dijo que lleva manejando carga en este patio desde los diecinueve.'::text),
(356522,39614,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute ça : il m''a dit qu''il ... du fret dans cette cour depuis ses dix-neuf ans.'::text,'gère'::text,'a géré'::text,'est en train de gérer'::text,'Écoute ça : il m''a dit qu''il gère du fret dans cette cour depuis ses dix-neuf ans.'::text),
(356525,39614,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şuna bak: bana on dokuz yaşından beri bu sahada yük ... söyledi.'::text,'taşıdığını'::text,'taşıdığını'::text,'taşımakta olduğunu'::text,'Şuna bak: bana on dokuz yaşından beri bu sahada yük taşıdığını söyledi.'::text),
(356526,39614,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj: azt mondta, hogy tizenkilenc éves kora óta ... rakományt ezen a telepen.'::text,'mozgat'::text,'mozgatott'::text,'éppen mozgat'::text,'Figyelj: azt mondta, hogy tizenkilenc éves kora óta mozgat rakományt ezen a telepen.'::text),
(356529,39615,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, es heißt, dass er, als der Truck ankam, schon die ganze Fracht auf den Pick-up ...'::text,'geladen hatte'::text,'geladen hat'::text,'lud'::text,'Hör mal, es heißt, dass er, als der Truck ankam, schon die ganze Fracht auf den Pick-up geladen hatte.'::text),
(356533,39615,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, поки приїхала вантажівка, він уже ... весь вантаж на пікап.'::text,'завантажив'::text,'завантажив'::text,'завантажив'::text,'Слухай, кажуть, поки приїхала вантажівка, він уже завантажив весь вантаж на пікап.'::text),
(356532,39615,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer, para cuando llegó el camión, él ya ... toda la carga en la camioneta.'::text,'había cargado'::text,'ha cargado'::text,'cargó'::text,'Oye, al parecer, para cuando llegó el camión, él ya había cargado toda la carga en la camioneta.'::text),
(356531,39615,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment, quand le camion est arrivé, il ... déjà toute la cargaison sur le pick-up.'::text,'avait chargé'::text,'a chargé'::text,'chargea'::text,'Écoute, apparemment, quand le camion est arrivé, il avait chargé déjà toute la cargaison sur le pick-up.'::text),
(356534,39615,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, kamyon geldiğinde o bütün yükü çoktan pikaba ... diyorlar.'::text,'yüklemişti'::text,'yükledi'::text,'yükledi'::text,'Dinle, kamyon geldiğinde o bütün yükü çoktan pikaba yüklemişti diyorlar.'::text),
(356535,39615,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag mire a kamion megérkezett, ő már az összes rakományt ... a pickupra.'::text,'felpakolta'::text,'felpakolta'::text,'felpakolta'::text,'Figyelj, állítólag mire a kamion megérkezett, ő már az összes rakományt felpakolta a pickupra.'::text),
(356538,39616,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, morgen um diese Zeit ... Fracht im Hafen, nicht auf diesem Hof, anscheinend.'::text,'lädt er gerade'::text,'wird er laden'::text,'lädt er'::text,'Bestie, morgen um diese Zeit lädt er gerade Fracht im Hafen, nicht auf diesem Hof, anscheinend.'::text),
(356542,39616,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сонечко, кажуть, завтра о цій порі він ... вантаж у порту, а не на цьому дворі.'::text,'вантажитиме'::text,'завантажить'::text,'вантажить'::text,'Сонечко, кажуть, завтра о цій порі він вантажитиме вантаж у порту, а не на цьому дворі.'::text),
(356541,39616,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer mañana a esta hora ... carga en el puerto, no en este patio.'::text,'estará cargando'::text,'cargará'::text,'carga'::text,'Amiga, al parecer mañana a esta hora estará cargando carga en el puerto, no en este patio.'::text),
(356540,39616,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment demain à la même heure il ... du fret au port, pas dans cette cour.'::text,'sera en train de charger'::text,'chargera'::text,'charge'::text,'Ma belle, apparemment demain à la même heure il sera en train de charger du fret au port, pas dans cette cour.'::text),
(356543,39616,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın bu saatlerde bu sahada değil, limanda yük ... diyorlar.'::text,'yüklüyor olacakmış'::text,'yükleyecekmiş'::text,'yüklüyormuş'::text,'Kanka, yarın bu saatlerde bu sahada değil, limanda yük yüklüyor olacakmış diyorlar.'::text),
(356544,39616,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag holnap ilyenkor a kikötőben ... rakományt, nem ezen a telepen.'::text,'fog éppen pakolni'::text,'pakol majd'::text,'pakol'::text,'Csajszi, állítólag holnap ilyenkor a kikötőben fog éppen pakolni rakományt, nem ezen a telepen.'::text),
(356547,39617,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Arbeiter sagte, dass die Fracht sicher ...'::text,'angekommen war'::text,'angekommen ist'::text,'ankommt'::text,'Der Arbeiter sagte, dass die Fracht sicher angekommen war.'::text),
(356551,39617,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Робітник сказав, що вантаж ... безпечно.'::text,'прибув'::text,'прибув'::text,'прибуває'::text,'Робітник сказав, що вантаж прибув безпечно.'::text),
(356550,39617,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El trabajador dijo que la carga ... sin problemas.'::text,'había llegado'::text,'ha llegado'::text,'llega'::text,'El trabajador dijo que la carga había llegado sin problemas.'::text),
(356549,39617,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''ouvrier a dit que la cargaison ... sans encombre.'::text,'était arrivée'::text,'est arrivée'::text,'arrive'::text,'L''ouvrier a dit que la cargaison était arrivée sans encombre.'::text),
(356552,39617,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İşçi, yükün güvenle ... söyledi.'::text,'ulaştığını'::text,'ulaştığını'::text,'ulaştığını'::text,'İşçi, yükün güvenle ulaştığını söyledi.'::text),
(356553,39617,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A munkás azt mondta, hogy a rakomány épségben ...'::text,'megérkezett'::text,'megérkezett'::text,'megérkezik'::text,'A munkás azt mondta, hogy a rakomány épségben megérkezett.'::text),
(356556,39618,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hof ... leer, bevor die Lastwagen mit der Fracht zu kommen begannen.'::text,'war früher'::text,'war früher immer'::text,'war es gewohnt'::text,'Der Hof war früher leer, bevor die Lastwagen mit der Fracht zu kommen begannen.'::text),
(356560,39618,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двір ... порожнім, поки не почали приїжджати вантажівки з вантажем.'::text,'раніше був'::text,'раніше був'::text,'звик бути'::text,'Двір раніше був порожнім, поки не почали приїжджати вантажівки з вантажем.'::text),
(356559,39618,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El patio ... vacío antes de que empezaran a llegar los camiones de carga.'::text,'solía estar'::text,'estaba'::text,'estaba acostumbrado a estar'::text,'El patio solía estar vacío antes de que empezaran a llegar los camiones de carga.'::text),
(356558,39618,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cour ... vide avant que les camions de fret commencent à arriver.'::text,'était autrefois'::text,'était'::text,'était habituée à être'::text,'La cour était autrefois vide avant que les camions de fret commencent à arriver.'::text),
(356561,39618,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yük kamyonları gelmeye başlamadan önce avlu boş ...'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Yük kamyonları gelmeye başlamadan önce avlu boş olurdu.'::text),
(356562,39618,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az udvar ... üres volt, mielőtt elkezdtek érkezni a teherszállító kamionok.'::text,'régen'::text,'régebben'::text,'hozzá volt szokva'::text,'Az udvar régen üres volt, mielőtt elkezdtek érkezni a teherszállító kamionok.'::text),
(356565,39619,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es macht ihm Spaß, Frachtlaster auf den Hof ...'::text,'zu lotsen'::text,'zu lotsen'::text,'lotsen'::text,'Es macht ihm Spaß, Frachtlaster auf den Hof zu lotsen.'::text),
(356569,39619,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому подобається ... вантажівки у двір.'::text,'направляти'::text,'направляти'::text,'направляє'::text,'Йому подобається направляти вантажівки у двір.'::text),
(356568,39619,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gusta ... los camiones de carga hacia el patio.'::text,'guiar'::text,'guiar'::text,'guía'::text,'Le gusta guiar los camiones de carga hacia el patio.'::text),
(356567,39619,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aime ... les camions de fret dans la cour.'::text,'guider'::text,'guider'::text,'guide'::text,'Il aime guider les camions de fret dans la cour.'::text),
(356570,39619,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yük kamyonlarını avluya ... seviyor.'::text,'yönlendirmeyi'::text,'yönlendirmeyi'::text,'yönlendir'::text,'Yük kamyonlarını avluya yönlendirmeyi seviyor.'::text),
(356571,39619,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szeret ... a teherautókat az udvarra.'::text,'beirányítani'::text,'beirányítani'::text,'beirányít'::text,'Szeret beirányítani a teherautókat az udvarra.'::text),
(356583,39621,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis der Sattelzug einfuhr, ... das Subjekt die palettierte Fracht zweimal abgeklopft.'::text,'hatte'::text,'hat'::text,'klopfte'::text,'Bis der Sattelzug einfuhr, hatte das Subjekt die palettierte Fracht zweimal abgeklopft.'::text),
(356587,39621,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки в''їхав тягач, суб''єкт ... палетований вантаж двічі.'::text,'поплескав'::text,'поплескав'::text,'поплескував'::text,'Поки в''їхав тягач, суб''єкт поплескав палетований вантаж двічі.'::text),
(356586,39621,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando entró el tráiler, el sujeto ... la carga paletizada dos veces.'::text,'le había dado palmadas a'::text,'le ha dado palmadas a'::text,'le estaba dando palmadas a'::text,'Para cuando entró el tráiler, el sujeto le había dado palmadas a la carga paletizada dos veces.'::text),
(356585,39621,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le semi-remorque est entré, le sujet ... deux fois la cargaison palettisée.'::text,'avait tapoté'::text,'a tapoté'::text,'tapotait'::text,'Quand le semi-remorque est entré, le sujet avait tapoté deux fois la cargaison palettisée.'::text),
(356588,39621,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tır içeri girdiğinde denek paletli yükü iki kez ...'::text,'sıvazlamıştı'::text,'sıvazladı'::text,'sıvazlıyordu'::text,'Tır içeri girdiğinde denek paletli yükü iki kez sıvazlamıştı.'::text),
(356589,39621,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a nyerges vontató begördült, az alany kétszer ... meg a raklapos rakományt.'::text,'paskolta'::text,'paskolta'::text,'paskolgatta'::text,'Mire a nyerges vontató begördült, az alany kétszer paskolta meg a raklapos rakományt.'::text),
(398649,44295,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während der Kunde nach der Waffel ..., legte er ihn rein. Makelloser Service.'::text,'griff'::text,'griff'::text,'hat gegriffen'::text,'Während der Kunde nach der Waffel griff, legte er ihn rein. Makelloser Service.'::text),
(398653,44295,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки клієнт ... по ріжок, він його розводив. Бездоганне обслуговування.'::text,'тягнувся'::text,'потягнувся'::text,'потягнувся'::text,'Поки клієнт тягнувся по ріжок, він його розводив. Бездоганне обслуговування.'::text),
(398652,44295,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el cliente ... hacia el cucurucho, él lo estaba engañando. Servicio impecable.'::text,'estiraba la mano'::text,'estiró la mano'::text,'ha estirado la mano'::text,'Mientras el cliente estiraba la mano hacia el cucurucho, él lo estaba engañando. Servicio impecable.'::text),
(398651,44295,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le client ... le cornet, il le piégeait. Service impeccable.'::text,'tendait la main vers'::text,'a tendu la main vers'::text,'a tendu la main vers'::text,'Pendant que le client tendait la main vers le cornet, il le piégeait. Service impeccable.'::text),
(398654,44295,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri külaha ..., o onu kandırıyordu. Kusursuz hizmet.'::text,'uzanırken'::text,'uzandı'::text,'uzandı'::text,'Müşteri külaha uzanırken, o onu kandırıyordu. Kusursuz hizmet.'::text),
(398655,44295,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a vevő a tölcsér után ..., ő szívatta. Hibátlan kiszolgálás.'::text,'nyúlt'::text,'nyúlt'::text,'nyúlt'::text,'Miközben a vevő a tölcsér után nyúlt, ő szívatta. Hibátlan kiszolgálás.'::text),
(398658,44296,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... diesen armen Kunden jetzt schon seit fünf Minuten. Klar, ein schneller Verkauf.'::text,'veräppelt'::text,'veräppelt gerade'::text,'veräppelt'::text,'Er veräppelt diesen armen Kunden jetzt schon seit fünf Minuten. Klar, ein schneller Verkauf.'::text),
(398662,44296,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... цього бідолашного клієнта вже п''ять хвилин. Явно швидкий продаж.'::text,'розводить'::text,'розводить'::text,'розводить'::text,'Він розводить цього бідолашного клієнта вже п''ять хвилин. Явно швидкий продаж.'::text),
(398661,44296,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... a este pobre cliente desde hace cinco minutos. Venta rápida, está claro.'::text,'lleva engañando'::text,'está engañando'::text,'engaña'::text,'Él lleva engañando a este pobre cliente desde hace cinco minutos. Venta rápida, está claro.'::text),
(398660,44296,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ça fait cinq minutes qu''il ... ce pauvre client. Clairement une vente rapide.'::text,'fait marcher'::text,'est en train de faire marcher'::text,'fait marcher'::text,'Ça fait cinq minutes qu''il fait marcher ce pauvre client. Clairement une vente rapide.'::text),
(398663,44296,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beş dakikadır bu zavallı müşteriyi ...; belli ki hızlı bir satış.'::text,'kandırıyor'::text,'kandırıyor'::text,'kandırır'::text,'Beş dakikadır bu zavallı müşteriyi kandırıyor; belli ki hızlı bir satış.'::text),
(398664,44296,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már öt perce ... ezt a szegény vevőt. Nyilván gyors eladás.'::text,'szívatja'::text,'szívatja éppen'::text,'szívatja'::text,'Már öt perce szívatja ezt a szegény vevőt. Nyilván gyors eladás.'::text),
(398667,44297,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kunde griff gerade nach der Waffel, als der Verkäufer ihn wieder ...'::text,'reinlegte'::text,'gerade reinlegte'::text,'reingelegt hat'::text,'Der Kunde griff gerade nach der Waffel, als der Verkäufer ihn wieder reinlegte.'::text),
(398671,44297,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клієнт тягнувся по ріжок, коли продавець знову ... його.'::text,'обдурив'::text,'обдурював'::text,'обдурив'::text,'Клієнт тягнувся по ріжок, коли продавець знову обдурив його.'::text),
(398670,44297,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cliente estaba intentando coger el cucurucho cuando el vendedor lo ... otra vez.'::text,'engañó'::text,'estaba engañando'::text,'ha engañado'::text,'El cliente estaba intentando coger el cucurucho cuando el vendedor lo engañó otra vez.'::text),
(398669,44297,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le client tendait la main vers le cornet quand le vendeur ... encore.'::text,'l''a piégé'::text,'le piégeait'::text,'l''a piégé'::text,'Le client tendait la main vers le cornet quand le vendeur l''a piégé encore.'::text),
(398672,44297,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri külaha uzanıyordu ki satıcı onu yine ...'::text,'kandırdı'::text,'kandırıyordu'::text,'kandırdı'::text,'Müşteri külaha uzanıyordu ki satıcı onu yine kandırdı.'::text),
(398673,44297,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vevő épp a tölcsér után nyúlt, amikor az eladó megint ...'::text,'átverte'::text,'átverte éppen'::text,'átverte'::text,'A vevő épp a tölcsér után nyúlt, amikor az eladó megint átverte.'::text),
(398676,44298,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kunde ... vom Verkäufer mit der leeren Waffel fünfmal reingelegt.'::text,'wurde'::text,'legte'::text,'legte'::text,'Der Kunde wurde vom Verkäufer mit der leeren Waffel fünfmal reingelegt.'::text),
(398680,44298,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клієнт ... продавцем із порожнім ріжком п''ять разів.'::text,'був обдурений'::text,'обдурив'::text,'обдурював'::text,'Клієнт був обдурений продавцем із порожнім ріжком п''ять разів.'::text),
(398679,44298,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cliente ... por el vendedor con el cucurucho vacío cinco veces.'::text,'fue engañado'::text,'engañó'::text,'estaba engañando'::text,'El cliente fue engañado por el vendedor con el cucurucho vacío cinco veces.'::text),
(398678,44298,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le client ... par le vendeur avec le cornet vide cinq fois.'::text,'a été piégé'::text,'a piégé'::text,'piégeait'::text,'Le client a été piégé par le vendeur avec le cornet vide cinq fois.'::text),
(398681,44298,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri, satıcı tarafından boş külahla beş kez ...'::text,'kandırıldı'::text,'kandırdı'::text,'kandırıyordu'::text,'Müşteri, satıcı tarafından boş külahla beş kez kandırıldı.'::text),
(398682,44298,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vevőt az eladó ötször ... az üres tölcsérrel.'::text,'átverte'::text,'átverték'::text,'verte át éppen'::text,'A vevőt az eladó ötször átverte az üres tölcsérrel.'::text),
(398685,44299,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kunde lacht auch, also ... der Verkäufer ihn nicht auf fiese Art reinlegen.'::text,'kann'::text,'muss'::text,'sollte'::text,'Der Kunde lacht auch, also kann der Verkäufer ihn nicht auf fiese Art reinlegen.'::text),
(398689,44299,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клієнт теж сміється, тож продавець ... розводити його по-злому.'::text,'не може'::text,'напевно, мусить'::text,'має'::text,'Клієнт теж сміється, тож продавець не може розводити його по-злому.'::text),
(398688,44299,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cliente también se ríe, así que el vendedor ... estar engañándolo con mala intención.'::text,'no puede'::text,'debe de'::text,'debería'::text,'El cliente también se ríe, así que el vendedor no puede estar engañándolo con mala intención.'::text),
(398687,44299,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le client rit aussi, donc le vendeur ... le piéger méchamment.'::text,'ne peut pas'::text,'doit'::text,'devrait'::text,'Le client rit aussi, donc le vendeur ne peut pas le piéger méchamment.'::text),
(398690,44299,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri de gülüyor, yani satıcı onu kötü niyetle kandırıyor ...'::text,'olamaz'::text,'olmalı'::text,'olmalı'::text,'Müşteri de gülüyor, yani satıcı onu kötü niyetle kandırıyor olamaz.'::text),
(398691,44299,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vevő is nevet, szóval ... az eladó rosszindulatúan szívatja.'::text,'nem lehet, hogy'::text,'biztos, hogy'::text,'kellene, hogy'::text,'A vevő is nevet, szóval nem lehet, hogy az eladó rosszindulatúan szívatja.'::text),
(398694,44300,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Verkäufer, ... mich mit dieser Waffel reingelegt hat, hat meinen ganzen Abend ruiniert!'::text,'der'::text,'was'::text,'dessen'::text,'Der Verkäufer, der mich mit dieser Waffel reingelegt hat, hat meinen ganzen Abend ruiniert!'::text),
(398698,44300,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Продавець, ... обдурив мене з тим ріжком, зіпсував мені весь вечір!'::text,'який'::text,'що'::text,'чий'::text,'Продавець, який обдурив мене з тим ріжком, зіпсував мені весь вечір!'::text),
(398697,44300,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El vendedor ... me engañó con ese cucurucho me ha arruinado toda la noche!'::text,'que'::text,'el cual'::text,'cuyo'::text,'¡El vendedor que me engañó con ese cucurucho me ha arruinado toda la noche!'::text),
(398696,44300,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vendeur ... m''a piégé avec ce cornet a gâché toute ma soirée !'::text,'qui'::text,'lequel'::text,'dont'::text,'Le vendeur qui m''a piégé avec ce cornet a gâché toute ma soirée !'::text),
(398699,44300,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beni o külahla kandıran ... satıcı bütün akşamımı mahvetti!'::text,''::text,NULL::text,NULL::text,'Beni o külahla kandıran satıcı bütün akşamımı mahvetti!'::text),
(398700,44300,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az eladó, ... átvert azzal a tölcsérrel, tönkretette az egész estémet!'::text,'aki'::text,'ami'::text,'akinek'::text,'Az eladó, aki átvert azzal a tölcsérrel, tönkretette az egész estémet!'::text),
(398703,44301,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, der Kunde hat mir erzählt, dass der Verkäufer ihn vor der Waffel fünfmal ...'::text,'reingelegt hatte'::text,'reingelegt hat'::text,'reinlegt'::text,'Mädel, der Kunde hat mir erzählt, dass der Verkäufer ihn vor der Waffel fünfmal reingelegt hatte.'::text),
(398707,44301,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, клієнт сказав мені, що продавець ... його п''ять разів, перш ніж дав ріжок.'::text,'обдурив'::text,'обдурив'::text,'обдурює'::text,'Подруго, клієнт сказав мені, що продавець обдурив його п''ять разів, перш ніж дав ріжок.'::text),
(398706,44301,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, el cliente me dijo que el vendedor lo ... cinco veces antes del cucurucho.'::text,'había engañado'::text,'ha engañado'::text,'engaña'::text,'Tía, el cliente me dijo que el vendedor lo había engañado cinco veces antes del cucurucho.'::text),
(398705,44301,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, le client m''a dit que le vendeur ... cinq fois avant le cornet.'::text,'l''avait piégé'::text,'l''a piégé'::text,'le piège'::text,'Meuf, le client m''a dit que le vendeur l''avait piégé cinq fois avant le cornet.'::text),
(398708,44301,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, müşteri bana satıcının külahtan önce onu beş kez ... anlattı.'::text,'kandırdığını'::text,'kandırdığını'::text,'kandırdığını'::text,'Kızım, müşteri bana satıcının külahtan önce onu beş kez kandırdığını anlattı.'::text),
(398709,44301,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a vevő azt mondta, hogy az eladó ötször ... a tölcsér előtt.'::text,'átverte'::text,'átverte'::text,'átveri'::text,'Csajszi, a vevő azt mondta, hogy az eladó ötször átverte a tölcsér előtt.'::text),
(398712,44302,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, letzten Sommer ... jeden einzelnen Kunden so, anscheinend.'::text,'veräppelte er immer'::text,'veräppelte er früher'::text,'war er es gewohnt zu veräppeln'::text,'Hör mal, letzten Sommer veräppelte er immer jeden einzelnen Kunden so, anscheinend.'::text),
(398716,44302,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, минулого літа він ... так кожного клієнта.'::text,'розводив'::text,'розводив'::text,'звик розводити'::text,'Слухай, кажуть, минулого літа він розводив так кожного клієнта.'::text),
(398715,44302,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer el verano pasado ... así a cada cliente.'::text,'engañaba'::text,'solía engañar'::text,'estaba acostumbrado a engañar'::text,'Oye, al parecer el verano pasado engañaba así a cada cliente.'::text),
(398714,44302,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment l''été dernier il ... chaque client comme ça.'::text,'piégeait'::text,'piégeait'::text,'était habitué à piéger'::text,'Écoute, apparemment l''été dernier il piégeait chaque client comme ça.'::text),
(398717,44302,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, geçen yaz her bir müşteriyi böyle ... diyorlar.'::text,'kandırırmış'::text,'kandırırmış'::text,'kandırmaya alışkınmış'::text,'Dinle, geçen yaz her bir müşteriyi böyle kandırırmış diyorlar.'::text),
(398718,44302,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag tavaly nyáron minden egyes vevőt így ...'::text,'átvert'::text,'átverte mindig'::text,'hozzá volt szokva, hogy átverje'::text,'Figyelj, állítólag tavaly nyáron minden egyes vevőt így átvert.'::text),
(398739,44305,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dreimal ..., bevor du ihm endlich die Waffel gegeben hast. Lässig.'::text,'hattest du ihn reingelegt'::text,'hast du ihn reingelegt'::text,'legtest du ihn gerade rein'::text,'Dreimal hattest du ihn reingelegt, bevor du ihm endlich die Waffel gegeben hast. Lässig.'::text),
(398743,44305,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... його тричі, перш ніж нарешті віддав ріжок. Спритно.'::text,'обдурив'::text,'обдурив'::text,'обдурював'::text,'Ти обдурив його тричі, перш ніж нарешті віддав ріжок. Спритно.'::text),
(398742,44305,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tres veces antes de darle por fin el cucurucho. Qué arte.'::text,'Lo habías engañado'::text,'Lo has engañado'::text,'Lo estabas engañando'::text,'Lo habías engañado tres veces antes de darle por fin el cucurucho. Qué arte.'::text),
(398741,44305,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... trois fois avant de lui tendre enfin le cornet. Trop fort.'::text,'l''avais piégé'::text,'l''as piégé'::text,'le piégeais'::text,'Tu l''avais piégé trois fois avant de lui tendre enfin le cornet. Trop fort.'::text),
(398744,44305,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Külahı sonunda vermeden önce onu üç kez ..., ustaca.'::text,'kandırmıştın'::text,'kandırdın'::text,'kandırıyordun'::text,'Külahı sonunda vermeden önce onu üç kez kandırmıştın, ustaca.'::text),
(398745,44305,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Háromszor ..., mielőtt végre odaadtad a tölcsért. Profi.'::text,'átverted'::text,'átverted'::text,'verted át éppen'::text,'Háromszor átverted, mielőtt végre odaadtad a tölcsért. Profi.'::text),
(399144,44350,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, zwei Schalter ..., und der ganze Garten leuchtet, kein Witz.'::text,'hat er schon angeknipst'::text,'knipst er seit einer Weile an'::text,'knipste er an'::text,'Bro, zwei Schalter hat er schon angeknipst, und der ganze Garten leuchtet, kein Witz.'::text),
(399148,44350,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро вже ... два вимикачі, і весь сад світиться, без жартів.'::text,'увімкнув'::text,'вмикає'::text,'увімкнув'::text,'Бро вже увімкнув два вимикачі, і весь сад світиться, без жартів.'::text),
(399147,44350,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tío ya ... dos interruptores y todo el jardín está iluminado, te lo juro.'::text,'ha encendido'::text,'ha estado encendiendo'::text,'encendió'::text,'El tío ya ha encendido dos interruptores y todo el jardín está iluminado, te lo juro.'::text),
(399146,44350,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le frérot ... déjà deux interrupteurs, et tout le jardin est illuminé, sans mentir.'::text,'a allumé'::text,'est en train d''allumer'::text,'a allumé'::text,'Le frérot a allumé déjà deux interrupteurs, et tout le jardin est illuminé, sans mentir.'::text),
(399149,44350,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka iki şalteri çoktan ... ve bütün bahçe ışıl ışıl, yemin ederim.'::text,'açtı'::text,'açıp duruyor'::text,'açtı'::text,'Kanka iki şalteri çoktan açtı ve bütün bahçe ışıl ışıl, yemin ederim.'::text),
(399150,44350,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tesó már két kapcsolót ..., és az egész kert világít, nem viccelek.'::text,'felkapcsolt'::text,'kapcsolgat'::text,'felkapcsolt'::text,'A tesó már két kapcsolót felkapcsolt, és az egész kert világít, nem viccelek.'::text),
(399153,44351,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Licht auf der Veranda ..., als er den Garten erreichte.'::text,'hatte er schon angemacht'::text,'hat er schon angemacht'::text,'macht er an'::text,'Das Licht auf der Veranda hatte er schon angemacht, als er den Garten erreichte.'::text),
(399157,44351,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він дійшов до саду, він уже ... світло на веранді.'::text,'увімкнув'::text,'увімкнув'::text,'вмикає'::text,'Поки він дійшов до саду, він уже увімкнув світло на веранді.'::text),
(399156,44351,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegó al jardín, ya ... la luz de la veranda.'::text,'había encendido'::text,'ha encendido'::text,'enciende'::text,'Para cuando llegó al jardín, ya había encendido la luz de la veranda.'::text),
(399155,44351,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il est arrivé au jardin, il ... déjà la lumière de la véranda.'::text,'avait allumé'::text,'a allumé'::text,'allume'::text,'Quand il est arrivé au jardin, il avait allumé déjà la lumière de la véranda.'::text),
(399158,44351,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçeye vardığında verandanın ışığını çoktan ...'::text,'açmıştı'::text,'açtı'::text,'açıyor'::text,'Bahçeye vardığında verandanın ışığını çoktan açmıştı.'::text),
(399159,44351,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kertbe ért, már ... a verandán a lámpát.'::text,'felkapcsolta'::text,'felkapcsolta'::text,'felkapcsolja'::text,'Mire a kertbe ért, már felkapcsolta a verandán a lámpát.'::text),
(399162,44352,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen Abend um diese Zeit ... er gerade wieder die Lichterketten einschalten.'::text,'wird'::text,'wird'::text,'schaltet'::text,'Morgen Abend um diese Zeit wird er gerade wieder die Lichterketten einschalten.'::text),
(399166,44352,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра ввечері о цій порі він знову ... гірлянди.'::text,'вмикатиме'::text,'увімкне'::text,'вмикає'::text,'Завтра ввечері о цій порі він знову вмикатиме гірлянди.'::text),
(399165,44352,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora de la tarde, ... otra vez las guirnaldas de luces.'::text,'estará encendiendo'::text,'encenderá'::text,'enciende'::text,'Mañana a esta hora de la tarde, estará encendiendo otra vez las guirnaldas de luces.'::text),
(399164,44352,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain soir à la même heure, il ... à nouveau les guirlandes lumineuses.'::text,'sera en train d''allumer'::text,'allumera'::text,'allume'::text,'Demain soir à la même heure, il sera en train d''allumer à nouveau les guirlandes lumineuses.'::text),
(399167,44352,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın akşam bu saatlerde yine ışık zincirlerini ...'::text,'açıyor olacak'::text,'açacak'::text,'açıyor'::text,'Yarın akşam bu saatlerde yine ışık zincirlerini açıyor olacak.'::text),
(399168,44352,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap este ilyenkor ... megint a fényfüzéreket.'::text,'épp felkapcsolja majd'::text,'fel fogja kapcsolni'::text,'felkapcsolja'::text,'Holnap este ilyenkor épp felkapcsolja majd megint a fényfüzéreket.'::text),
(399171,44353,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er verspricht, dass er heute Abend für die Party die Lichterketten ...'::text,'anmachen wird'::text,'gerade anmachen wird'::text,'angemacht hat'::text,'Er verspricht, dass er heute Abend für die Party die Lichterketten anmachen wird.'::text),
(399175,44353,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він обіцяє, що ... гірлянди для вечірки сьогодні ввечері.'::text,'увімкне'::text,'вмикатиме'::text,'увімкнув'::text,'Він обіцяє, що увімкне гірлянди для вечірки сьогодні ввечері.'::text),
(399174,44353,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Promete que ... las guirnaldas de luces para la fiesta de esta noche.'::text,'encenderá'::text,'estará encendiendo'::text,'encendió'::text,'Promete que encenderá las guirnaldas de luces para la fiesta de esta noche.'::text),
(399173,44353,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il promet qu''il ... les guirlandes lumineuses pour la soirée de ce soir.'::text,'allumera'::text,'sera en train d''allumer'::text,'a allumé'::text,'Il promet qu''il allumera les guirlandes lumineuses pour la soirée de ce soir.'::text),
(399176,44353,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşamki parti için ışık zincirlerini ... söz veriyor.'::text,'açacağına'::text,'açıyor olacağına'::text,'açtığına'::text,'Bu akşamki parti için ışık zincirlerini açacağına söz veriyor.'::text),
(399177,44353,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígéri, hogy ma estére a buli miatt ... a fényfüzéreket.'::text,'felkapcsolja'::text,'épp felkapcsolja majd'::text,'felkapcsolta'::text,'Megígéri, hogy ma estére a buli miatt felkapcsolja a fényfüzéreket.'::text),
(399180,44354,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er die Lichter ..., wird der Garten hell. Wahrhaft bahnbrechende Wissenschaft.'::text,'anmacht'::text,'anmachen wird'::text,'angemacht hat'::text,'Wenn er die Lichter anmacht, wird der Garten hell. Wahrhaft bahnbrechende Wissenschaft.'::text),
(399184,44354,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він ... світло, сад стає яскравим. Справді проривна наука.'::text,'вмикає'::text,'увімкне'::text,'увімкнув'::text,'Якщо він вмикає світло, сад стає яскравим. Справді проривна наука.'::text),
(399183,44354,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ... las luces, el jardín se ilumina. Ciencia realmente revolucionaria.'::text,'enciende'::text,'encenderá'::text,'encendió'::text,'Si enciende las luces, el jardín se ilumina. Ciencia realmente revolucionaria.'::text),
(399182,44354,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ... les lumières, le jardin devient lumineux. Une science vraiment révolutionnaire.'::text,'allume'::text,'allumera'::text,'allumait'::text,'S''il allume les lumières, le jardin devient lumineux. Une science vraiment révolutionnaire.'::text),
(399185,44354,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Işıkları ..., bahçe aydınlanır. Gerçekten çığır açan bir bilim.'::text,'açarsa'::text,'açacaksa'::text,'açtıysa'::text,'Işıkları açarsa, bahçe aydınlanır. Gerçekten çığır açan bir bilim.'::text),
(399186,44354,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ... a lámpákat, a kert kivilágosodik. Igazán úttörő tudomány.'::text,'felkapcsolja'::text,'fel fogja kapcsolni'::text,'felkapcsolta'::text,'Ha felkapcsolja a lámpákat, a kert kivilágosodik. Igazán úttörő tudomány.'::text),
(399189,44355,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er den Gartenschalter umlegt, ... die Lichter überall in den Palmen angehen. Pure Magie, offensichtlich.'::text,'werden'::text,'würden'::text,'gingen'::text,'Wenn er den Gartenschalter umlegt, werden die Lichter überall in den Palmen angehen. Pure Magie, offensichtlich.'::text),
(399193,44355,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він клацне садовим вимикачем, вогні ... по всіх пальмах. Чиста магія, очевидно.'::text,'засвітяться'::text,'засвітилися б'::text,'засвітилися'::text,'Якщо він клацне садовим вимикачем, вогні засвітяться по всіх пальмах. Чиста магія, очевидно.'::text),
(399192,44355,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le da al interruptor del jardín, las luces ... por todas las palmeras. Pura magia, obviamente.'::text,'se encenderán'::text,'se encenderían'::text,'se encendieron'::text,'Si le da al interruptor del jardín, las luces se encenderán por todas las palmeras. Pura magia, obviamente.'::text),
(399191,44355,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il actionne l''interrupteur du jardin, les lumières ... sur tous les palmiers. De la pure magie, évidemment.'::text,'s''allumeront'::text,'s''allumeraient'::text,'se sont allumées'::text,'S''il actionne l''interrupteur du jardin, les lumières s''allumeront sur tous les palmiers. De la pure magie, évidemment.'::text),
(399194,44355,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçe şalterini çevirirse, ışıklar palmiyelerin üzerinde ..., saf büyü tabii ki.'::text,'yanacak'::text,'yanardı'::text,'yandı'::text,'Bahçe şalterini çevirirse, ışıklar palmiyelerin üzerinde yanacak, saf büyü tabii ki.'::text),
(399195,44355,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha felkattintja a kerti kapcsolót, a fények ... a pálmákon. Tiszta varázslat, nyilván.'::text,'felgyulladnak'::text,'felgyulladnának'::text,'felgyulladtak'::text,'Ha felkattintja a kerti kapcsolót, a fények felgyulladnak a pálmákon. Tiszta varázslat, nyilván.'::text),
(399198,44356,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er jedes Licht in der Stadt ..., wären die Nachbarn begeistert. Offensichtlich.'::text,'einschaltete'::text,'einschaltet'::text,'einschalten würde'::text,'Wenn er jedes Licht in der Stadt einschaltete, wären die Nachbarn begeistert. Offensichtlich.'::text),
(399202,44356,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він ... кожне світло в місті, сусіди були б у захваті. Очевидно.'::text,'увімкнув'::text,'вмикає'::text,'увімкнув би'::text,'Якби він увімкнув кожне світло в місті, сусіди були б у захваті. Очевидно.'::text),
(399201,44356,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ... todas las luces de la ciudad, los vecinos estarían encantados. Obviamente.'::text,'encendiera'::text,'enciende'::text,'encendería'::text,'Si encendiera todas las luces de la ciudad, los vecinos estarían encantados. Obviamente.'::text),
(399200,44356,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ... toutes les lumières de la ville, les voisins seraient ravis. Évidemment.'::text,'allumait'::text,'allume'::text,'allumerait'::text,'S''il allumait toutes les lumières de la ville, les voisins seraient ravis. Évidemment.'::text),
(399203,44356,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şehirdeki bütün ışıkları ..., komşular bayılırdı. Tabii ki.'::text,'açsa'::text,'açarsa'::text,'açardı'::text,'Şehirdeki bütün ışıkları açsa, komşular bayılırdı. Tabii ki.'::text),
(399204,44356,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ... a város összes lámpáját, a szomszédok el lennének ragadtatva. Nyilván.'::text,'felkapcsolná'::text,'felkapcsolja'::text,'felkapcsolná'::text,'Ha felkapcsolná a város összes lámpáját, a szomszédok el lennének ragadtatva. Nyilván.'::text),
(399216,44358,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den letzten Schalter, und die dunkle Nacht war für immer zerstört!'::text,'betätigte'::text,'wurde betätigt'::text,'betätigend'::text,'Er betätigte den letzten Schalter, und die dunkle Nacht war für immer zerstört!'::text),
(399220,44358,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... останній вимикач, і темну ніч знищено назавжди!'::text,'клацнув'::text,'був клацнутий'::text,'клацаючи'::text,'Він клацнув останній вимикач, і темну ніч знищено назавжди!'::text),
(399219,44358,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... el último interruptor y la oscura noche quedó destruida para siempre!'::text,'Accionó'::text,'Fue accionado'::text,'Accionando'::text,'¡Accionó el último interruptor y la oscura noche quedó destruida para siempre!'::text),
(399218,44358,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le dernier interrupteur, et la nuit noire fut détruite pour toujours !'::text,'a actionné'::text,'a été actionné'::text,'actionnant'::text,'Il a actionné le dernier interrupteur, et la nuit noire fut détruite pour toujours !'::text),
(399221,44358,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son şalteri ... ve karanlık gece sonsuza dek yok oldu!'::text,'çevirdi'::text,'çevrildi'::text,'çevirerek'::text,'Son şalteri çevirdi ve karanlık gece sonsuza dek yok oldu!'::text),
(399222,44358,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... az utolsó kapcsolót, és a sötét éjszaka örökre megsemmisült!'::text,'Felkapcsolta'::text,'Fel lett kapcsolva'::text,'Felkapcsolva'::text,'Felkapcsolta az utolsó kapcsolót, és a sötét éjszaka örökre megsemmisült!'::text),
(399225,44359,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, er hat jedes einzelne Licht angemacht, also ... er anscheinend die Dunkelheit hassen.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Hör mal, er hat jedes einzelne Licht angemacht, also muss er anscheinend die Dunkelheit hassen.'::text),
(399229,44359,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він увімкнув кожне світло, тож, кажуть, він ... ненавидіти темряву.'::text,'мусить'::text,'не може'::text,'має'::text,'Слухай, він увімкнув кожне світло, тож, кажуть, він мусить ненавидіти темряву.'::text),
(399228,44359,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, encendió todas las luces, así que al parecer ... odiar la oscuridad.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Oye, encendió todas las luces, así que al parecer debe de odiar la oscuridad.'::text),
(399227,44359,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il a allumé toutes les lumières, donc apparemment il ... détester le noir.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Écoute, il a allumé toutes les lumières, donc apparemment il doit détester le noir.'::text),
(399230,44359,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, her bir ışığı açtı, yani anlaşılan karanlıktan nefret ediyor ...'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Dinle, her bir ışığı açtı, yani anlaşılan karanlıktan nefret ediyor olmalı.'::text),
(399231,44359,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, minden egyes lámpát felkapcsolt, szóval állítólag ... utálja a sötétet.'::text,'biztosan'::text,'nem lehet, hogy'::text,'kellene, hogy'::text,'Figyelj, minden egyes lámpát felkapcsolt, szóval állítólag biztosan utálja a sötétet.'::text),
(399234,44360,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, der Typ, ... all diese Lichterketten angemacht hat, wohnt anscheinend nebenan.'::text,'der'::text,'was'::text,'dessen'::text,'Mädel, der Typ, der all diese Lichterketten angemacht hat, wohnt anscheinend nebenan.'::text),
(399238,44360,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, хлопець, ... увімкнув усі ці гірлянди, кажуть, живе по сусідству.'::text,'який'::text,'що'::text,'чий'::text,'Подруго, хлопець, який увімкнув усі ці гірлянди, кажуть, живе по сусідству.'::text),
(399237,44360,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, el chico ... encendió todas esas guirnaldas de luces vive al lado, al parecer.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Tía, el chico que encendió todas esas guirnaldas de luces vive al lado, al parecer.'::text),
(399236,44360,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, le mec ... a allumé toutes ces guirlandes habite à côté, apparemment.'::text,'qui'::text,'lequel'::text,'dont'::text,'Meuf, le mec qui a allumé toutes ces guirlandes habite à côté, apparemment.'::text),
(399239,44360,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bütün o ışık zincirlerini açan ... çocuk yan tarafta oturuyormuş.'::text,''::text,NULL::text,NULL::text,'Kızım, bütün o ışık zincirlerini açan çocuk yan tarafta oturuyormuş.'::text),
(399240,44360,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a srác, ... felkapcsolta azokat a fényfüzéreket, állítólag a szomszédban lakik.'::text,'aki'::text,'ami'::text,'akinek'::text,'Csajszi, a srác, aki felkapcsolta azokat a fényfüzéreket, állítólag a szomszédban lakik.'::text),
(349914,38880,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaum ... den Stecker eingesteckt, als der Strom die Lichterketten zum Leuchten brachte.'::text,'hatte sie'::text,'sie hatte'::text,'war sie'::text,'Kaum hatte sie den Stecker eingesteckt, als der Strom die Lichterketten zum Leuchten brachte.'::text),
(349918,38880,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щойно вона ... вилку в розетку, як електрика засвітила гірлянди.'::text,'вставила'::text,'вставила'::text,'вставляла'::text,'Щойно вона вставила вилку в розетку, як електрика засвітила гірлянди.'::text),
(349917,38880,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Apenas ... el enchufe cuando la electricidad encendió las guirnaldas de luces.'::text,'había metido ella'::text,'ella había metido'::text,'estaba ella metiendo'::text,'Apenas había metido ella el enchufe cuando la electricidad encendió las guirnaldas de luces.'::text),
(349916,38880,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À peine ... la prise que l''électricité a allumé les guirlandes lumineuses.'::text,'avait-elle branché'::text,'elle avait branché'::text,'était-elle en train de brancher'::text,'À peine avait-elle branché la prise que l''électricité a allumé les guirlandes lumineuses.'::text),
(349919,38880,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fişi ... elektrik ışık zincirlerini yaktı.'::text,'takar takmaz'::text,'taktığı gibi'::text,'takarken'::text,'Fişi takar takmaz elektrik ışık zincirlerini yaktı.'::text),
(349920,38880,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alighogy ... a dugót, az áram máris felgyújtotta a fényfüzéreket.'::text,'bedugta'::text,'bedugta'::text,'dugta be éppen'::text,'Alighogy bedugta a dugót, az áram máris felgyújtotta a fényfüzéreket.'::text),
(349923,38881,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Letzten Monat ließ sie einen Elektriker mehr Steckdosen ..., für all den Strom, den sie verbraucht.'::text,'einbauen'::text,'einbauen'::text,'eingebaut'::text,'Letzten Monat ließ sie einen Elektriker mehr Steckdosen einbauen, für all den Strom, den sie verbraucht.'::text),
(349927,38881,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулого місяця вона попросила електрика ... більше розеток для всієї електрики, яку вона використовує.'::text,'встановити'::text,'встановити'::text,'встановлено'::text,'Минулого місяця вона попросила електрика встановити більше розеток для всієї електрики, яку вона використовує.'::text),
(349926,38881,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mes pasado hizo que un electricista ... más enchufes para toda la electricidad que usa.'::text,'instalara'::text,'instalara'::text,'instalado'::text,'El mes pasado hizo que un electricista instalara más enchufes para toda la electricidad que usa.'::text),
(349925,38881,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mois dernier, elle a fait ... plus de prises par un électricien pour toute l''électricité qu''elle utilise.'::text,'installer'::text,'installer'::text,'installé'::text,'Le mois dernier, elle a fait installer plus de prises par un électricien pour toute l''électricité qu''elle utilise.'::text),
(349928,38881,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçen ay kullandığı onca elektrik için bir elektrikçiye daha fazla priz ...'::text,'taktırdı'::text,'taktırdı'::text,'taktırdı'::text,'Geçen ay kullandığı onca elektrik için bir elektrikçiye daha fazla priz taktırdı.'::text),
(349929,38881,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Múlt hónapban ... egy villanyszerelővel több konnektort az összes áramhoz, amit használ.'::text,'beszereltetett'::text,'beszereltetett'::text,'beszereltetett'::text,'Múlt hónapban beszereltetett egy villanyszerelővel több konnektort az összes áramhoz, amit használ.'::text),
(349932,38882,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünscht sich, der Strom ... kostenlos. Ein sehr billiger Abend mit allen Lichtern an, ganz klar.'::text,'wäre'::text,'ist'::text,'wird sein'::text,'Sie wünscht sich, der Strom wäre kostenlos. Ein sehr billiger Abend mit allen Lichtern an, ganz klar.'::text),
(349936,38882,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона хоче, щоб електрика ... безкоштовною. Дуже дешевий вечір з усім увімкненим світлом, звісно.'::text,'була'::text,'є'::text,'буде'::text,'Вона хоче, щоб електрика була безкоштовною. Дуже дешевий вечір з усім увімкненим світлом, звісно.'::text),
(349935,38882,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desearía que la electricidad ... gratis. Una noche muy barata con todas las luces encendidas, está claro.'::text,'fuera'::text,'es'::text,'será'::text,'Desearía que la electricidad fuera gratis. Una noche muy barata con todas las luces encendidas, está claro.'::text),
(349934,38882,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait que l''électricité ... gratuite. Une soirée très bon marché avec toutes les lumières allumées, clairement.'::text,'soit'::text,'est'::text,'sera'::text,'Elle aimerait que l''électricité soit gratuite. Une soirée très bon marché avec toutes les lumières allumées, clairement.'::text),
(349937,38882,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke elektrik bedava ..., diye düşünüyor. Her ışık açıkken çok ucuz bir akşam, belli ki.'::text,'olsa'::text,NULL::text,'olacak'::text,'Keşke elektrik bedava olsa, diye düşünüyor. Her ışık açıkken çok ucuz bir akşam, belli ki.'::text),
(349938,38882,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak ingyenes ... az áram. Nagyon olcsó este minden égő lámpával, nyilván.'::text,'lenne'::text,NULL::text,'lesz'::text,'Azt kívánja, bárcsak ingyenes lenne az áram. Nagyon olcsó este minden égő lámpával, nyilván.'::text),
(349941,38883,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Saugroboter, ... mit Strom läuft, ist offensichtlich der fleißigste Arbeiter hier.'::text,'der'::text,'wer'::text,'dessen'::text,'Der Saugroboter, der mit Strom läuft, ist offensichtlich der fleißigste Arbeiter hier.'::text),
(349945,38883,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Робот-пилосос, ... працює на електриці, очевидно, найсумлінніший працівник тут.'::text,'який'::text,'хто'::text,'чий'::text,'Робот-пилосос, який працює на електриці, очевидно, найсумлінніший працівник тут.'::text),
(349944,38883,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El robot aspirador, ... funciona con electricidad, es obviamente el que más trabaja aquí.'::text,'que'::text,'quien'::text,'cuyo'::text,'El robot aspirador, que funciona con electricidad, es obviamente el que más trabaja aquí.'::text),
(349943,38883,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''aspirateur robot, ... fonctionne à l''électricité, est évidemment le plus gros bosseur ici.'::text,'qui'::text,'qui'::text,'dont'::text,'L''aspirateur robot, qui fonctionne à l''électricité, est évidemment le plus gros bosseur ici.'::text),
(349946,38883,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elektrikle çalışan ... robot süpürge, belli ki buradaki en çalışkan işçi.'::text,''::text,NULL::text,NULL::text,'Elektrikle çalışan robot süpürge, belli ki buradaki en çalışkan işçi.'::text),
(349947,38883,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A robotporszívó, ... árammal működik, nyilván a legszorgalmasabb dolgozó itt.'::text,'amely'::text,'aki'::text,'amelynek'::text,'A robotporszívó, amely árammal működik, nyilván a legszorgalmasabb dolgozó itt.'::text),
(349950,38884,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie braucht ..., um jedes Gerät zu betreiben, sonst ist der ganze Abend ruiniert!'::text,'Strom'::text,'einen Strom'::text,'Ströme'::text,'Sie braucht Strom, um jedes Gerät zu betreiben, sonst ist der ganze Abend ruiniert!'::text),
(349954,38884,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй потрібна ..., щоб працював кожен пристрій, інакше весь вечір зіпсовано!'::text,'електрика'::text,'електрика'::text,'електрики'::text,'Їй потрібна електрика, щоб працював кожен пристрій, інакше весь вечір зіпсовано!'::text),
(349953,38884,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Necesita ... para que funcione cada aparato, o toda la noche se arruina!'::text,'electricidad'::text,'una electricidad'::text,'electricidades'::text,'¡Necesita electricidad para que funcione cada aparato, o toda la noche se arruina!'::text),
(349952,38884,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a besoin ... pour faire marcher chaque appareil, sinon toute la soirée est fichue !'::text,'d''électricité'::text,'d''une électricité'::text,'d''électricités'::text,'Elle a besoin d''électricité pour faire marcher chaque appareil, sinon toute la soirée est fichue !'::text),
(349955,38884,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her cihazı çalıştırmak için ... ihtiyacı var, yoksa bütün akşam mahvolur!'::text,'elektriğe'::text,'bir elektriğe'::text,'elektriklere'::text,'Her cihazı çalıştırmak için elektriğe ihtiyacı var, yoksa bütün akşam mahvolur!'::text),
(349956,38884,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szüksége van ..., hogy minden eszköz működjön, különben az egész este tönkremegy!'::text,'áramra'::text,'egy áramra'::text,'áramokra'::text,'Szüksége van áramra, hogy minden eszköz működjön, különben az egész este tönkremegy!'::text),
(349959,38885,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Strom würde die ganze Wohnung im Chaos versinken!'::text,'Ohne'::text,'Trotz'::text,'Dank'::text,'Ohne Strom würde die ganze Wohnung im Chaos versinken!'::text),
(349963,38885,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... електрики вся квартира поринула б у хаос!'::text,'Без'::text,'Попри'::text,'Завдяки'::text,'Без електрики вся квартира поринула б у хаос!'::text),
(349962,38885,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... electricidad, todo el piso se hundiría en el caos!'::text,'Sin'::text,'A pesar de'::text,'Debido a'::text,'¡Sin electricidad, todo el piso se hundiría en el caos!'::text),
(349961,38885,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... électricité, tout l''appartement sombrerait dans le chaos !'::text,'Sans'::text,'Malgré'::text,'Grâce à'::text,'Sans électricité, tout l''appartement sombrerait dans le chaos !'::text),
(349964,38885,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elektrik ... bütün daire kaosa sürüklenirdi!'::text,'olmasaydı'::text,'rağmen'::text,'sayesinde'::text,'Elektrik olmasaydı bütün daire kaosa sürüklenirdi!'::text),
(349965,38885,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Áram ... az egész lakás káoszba zuhanna!'::text,'nélkül'::text,'ellenére'::text,'miatt'::text,'Áram nélkül az egész lakás káoszba zuhanna!'::text),
(349968,38886,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also anscheinend wusste sie, dass der Strom alle Lichter auf einmal ...'::text,'versorgen würde'::text,'versorgen wird'::text,'versorgt'::text,'Okay, also anscheinend wusste sie, dass der Strom alle Lichter auf einmal versorgen würde.'::text),
(349972,38886,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Короче, кажуть, вона знала, що електрика ... всі лампи одразу.'::text,'живитиме'::text,'живитиме'::text,'живить'::text,'Короче, кажуть, вона знала, що електрика живитиме всі лампи одразу.'::text),
(349971,38886,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, al parecer ella sabía que la electricidad ... todas las luces a la vez.'::text,'alimentaría'::text,'alimentará'::text,'alimenta'::text,'Vale, al parecer ella sabía que la electricidad alimentaría todas las luces a la vez.'::text),
(349970,38886,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment elle savait que l''électricité ... toutes les lumières d''un coup.'::text,'alimenterait'::text,'alimentera'::text,'alimente'::text,'Bon alors, apparemment elle savait que l''électricité alimenterait toutes les lumières d''un coup.'::text),
(349973,38886,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, anlaşılan elektriğin bütün ışıkları aynı anda ... biliyormuş.'::text,'çalıştıracağını'::text,'çalıştıracağını'::text,'çalıştırdığını'::text,'Tamam, anlaşılan elektriğin bütün ışıkları aynı anda çalıştıracağını biliyormuş.'::text),
(349974,38886,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag tudta, hogy az áram egyszerre ... az összes lámpát.'::text,'működteti majd'::text,'működtetni fogja'::text,'működteti'::text,'Szóval állítólag tudta, hogy az áram egyszerre működteti majd az összes lámpát.'::text),
(349977,38887,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, sie schwört, dass sie jeden einzelnen Tag für jede Kleinigkeit Strom ...'::text,'verbraucht'::text,'gerade verbraucht'::text,'verbraucht hat'::text,'Hör mal, sie schwört, dass sie jeden einzelnen Tag für jede Kleinigkeit Strom verbraucht.'::text),
(349981,38887,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона клянеться, що ... електрику на кожну дрібницю щодня.'::text,'використовує'::text,'використовує'::text,'використала'::text,'Слухай, вона клянеться, що використовує електрику на кожну дрібницю щодня.'::text),
(349980,38887,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, jura que ... electricidad para cada cosita todos los días.'::text,'usa'::text,'está usando'::text,'ha usado'::text,'Oye, jura que usa electricidad para cada cosita todos los días.'::text),
(349979,38887,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle jure qu''elle ... de l''électricité pour la moindre chose chaque jour.'::text,'utilise'::text,'est en train d''utiliser'::text,'a utilisé'::text,'Écoute, elle jure qu''elle utilise de l''électricité pour la moindre chose chaque jour.'::text),
(349982,38887,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, her gün her ufak şey için elektrik ... yemin ediyor.'::text,'kullandığına'::text,'kullanmakta olduğuna'::text,'kullanmış olduğuna'::text,'Dinle, her gün her ufak şey için elektrik kullandığına yemin ediyor.'::text),
(349983,38887,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, esküszik, hogy minden áldott nap minden apróságra ... áramot.'::text,'használ'::text,'éppen használ'::text,'használt'::text,'Figyelj, esküszik, hogy minden áldott nap minden apróságra használ áramot.'::text),
(349995,38889,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, bis Mitternacht ... diese Wohnung Unmengen an Strom verbraucht haben, kein Witz.'::text,'wird'::text,'wird'::text,'verbraucht'::text,'Yo, bis Mitternacht wird diese Wohnung Unmengen an Strom verbraucht haben, kein Witz.'::text),
(349999,38889,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, до опівночі ця квартира ... купу електрики, без жартів.'::text,'спожиє'::text,'спожиє'::text,'споживає'::text,'Йо, до опівночі ця квартира спожиє купу електрики, без жартів.'::text),
(349998,38889,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, para medianoche este piso ... un montón de electricidad, te lo juro.'::text,'habrá gastado'::text,'gastará'::text,'gasta'::text,'Ey, para medianoche este piso habrá gastado un montón de electricidad, te lo juro.'::text),
(349997,38889,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, d''ici minuit cet appart ... une tonne d''électricité, sans mentir.'::text,'aura consommé'::text,'consommera'::text,'consomme'::text,'Yo, d''ici minuit cet appart aura consommé une tonne d''électricité, sans mentir.'::text),
(350000,38889,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, gece yarısına kadar bu daire tonla elektrik ..., yemin ederim.'::text,'harcamış olacak'::text,'harcayacak'::text,'harcıyor'::text,'Yo, gece yarısına kadar bu daire tonla elektrik harcamış olacak, yemin ederim.'::text),
(350001,38889,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, éjfélig ez a lakás ... egy csomó áramot, nem viccelek.'::text,'elhasznál'::text,'el fog használni'::text,'használ'::text,'Figyu, éjfélig ez a lakás elhasznál egy csomó áramot, nem viccelek.'::text),
(329817,36647,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die beiden Freundinnen ... sich seit Jahren gleich, deshalb verwechseln die Leute sie oft.'::text,'kleiden'::text,'kleiden gerade'::text,'kleiden'::text,'Die beiden Freundinnen kleiden sich seit Jahren gleich, deshalb verwechseln die Leute sie oft.'::text),
(329821,36647,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дві подруги ... однаково вже багато років, тож люди часто їх плутають.'::text,'вдягаються'::text,'вдягаються'::text,'вдягаються'::text,'Дві подруги вдягаються однаково вже багато років, тож люди часто їх плутають.'::text),
(329820,36647,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las dos amigas ... igual desde hace años, así que la gente las confunde a menudo.'::text,'se visten'::text,'se están vistiendo'::text,'se visten'::text,'Las dos amigas se visten igual desde hace años, así que la gente las confunde a menudo.'::text),
(329819,36647,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux amies ... pareil depuis des années, donc les gens les confondent souvent.'::text,'s''habillent'::text,'sont en train de s''habiller'::text,'s''habillent'::text,'Les deux amies s''habillent pareil depuis des années, donc les gens les confondent souvent.'::text),
(329822,36647,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki arkadaş yıllardır aynı ..., o yüzden insanlar onları sık sık karıştırıyor.'::text,'giyiniyor'::text,'giyiniyor'::text,'giyinir'::text,'İki arkadaş yıllardır aynı giyiniyor, o yüzden insanlar onları sık sık karıştırıyor.'::text),
(329823,36647,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két barátnő évek óta egyformán ..., ezért az emberek gyakran összekeverik őket.'::text,'öltözködik'::text,'öltözködik éppen'::text,'öltözködik'::text,'A két barátnő évek óta egyformán öltözködik, ezért az emberek gyakran összekeverik őket.'::text),
(329826,36648,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... im Partnerlook den Weg entlang, als sie stehen blieben, um die Chips zu teilen.'::text,'liefen gerade'::text,'liefen'::text,'sind gelaufen'::text,'Sie liefen gerade im Partnerlook den Weg entlang, als sie stehen blieben, um die Chips zu teilen.'::text),
(329830,36648,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... стежкою, схожі одна на одну, коли зупинилися поділитися чипсами.'::text,'йшли'::text,'пройшли'::text,'пройшли'::text,'Вони йшли стежкою, схожі одна на одну, коли зупинилися поділитися чипсами.'::text),
(329829,36648,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... por el camino con el mismo look cuando se pararon a compartir las patatas fritas.'::text,'Iban caminando'::text,'Caminaron'::text,'Han caminado'::text,'Iban caminando por el camino con el mismo look cuando se pararon a compartir las patatas fritas.'::text),
(329828,36648,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles ... le long du chemin, habillées pareil, quand elles se sont arrêtées pour partager les chips.'::text,'marchaient'::text,'ont marché'::text,'ont marché'::text,'Elles marchaient le long du chemin, habillées pareil, quand elles se sont arrêtées pour partager les chips.'::text),
(329831,36648,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cipsleri paylaşmak için durduklarında yolda birbirlerine benzer şekilde ...'::text,'yürüyorlardı'::text,'yürüdüler'::text,'yürüdüler'::text,'Cipsleri paylaşmak için durduklarında yolda birbirlerine benzer şekilde yürüyorlardı.'::text),
(329832,36648,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyformán kinézve ... az ösvényen, amikor megálltak, hogy megosszák a chipset.'::text,'sétáltak'::text,'végigsétáltak'::text,'végigsétáltak'::text,'Egyformán kinézve sétáltak az ösvényen, amikor megálltak, hogy megosszák a chipset.'::text),
