(399405,44379,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Krass, anscheinend haben die sechs zusammen einen riesigen Teigstrang gedreht, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Krass, anscheinend haben die sechs zusammen einen riesigen Teigstrang gedreht, oder?'::text),
(399409,44379,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ну, кажуть, вони вшістьох скрутили один гігантський джгут із тіста, ...?'::text,'так'::text,'так'::text,'так'::text,'Та ну, кажуть, вони вшістьох скрутили один гігантський джгут із тіста, так?'::text),
(399408,44379,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No puede ser, al parecer los seis retorcieron una cuerda gigante de masa, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'No puede ser, al parecer los seis retorcieron una cuerda gigante de masa, ¿verdad?'::text),
(399407,44379,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pas possible, apparemment ils ont torsadé à six une corde de pâte géante, ... ?'::text,'non'::text,'non'::text,'non'::text,'Pas possible, apparemment ils ont torsadé à six une corde de pâte géante, non ?'::text),
(399410,44379,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olamaz, anlaşılan altısı birlikte dev bir hamur ipini bükmüş, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Olamaz, anlaşılan altısı birlikte dev bir hamur ipini bükmüş, değil mi?'::text),
(399411,44379,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne már, állítólag hatan csavartak meg egy óriási tésztakötelet, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Ne már, állítólag hatan csavartak meg egy óriási tésztakötelet, ugye?'::text),
(399414,44380,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, der erste Teenager hat den Teig gedreht, und anscheinend die anderen fünf ...'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Bestie, der erste Teenager hat den Teig gedreht, und anscheinend die anderen fünf auch.'::text),
(399418,44380,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сонечко, перший підліток скрутив тісто, і, кажуть, інші п''ятеро ...'::text,'теж'::text,'теж'::text,'теж ні'::text,'Сонечко, перший підліток скрутив тісто, і, кажуть, інші п''ятеро теж.'::text),
(399417,44380,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, el primer chaval retorció la masa y, al parecer, los otros cinco ...'::text,'también'::text,'también'::text,'tampoco'::text,'Amiga, el primer chaval retorció la masa y, al parecer, los otros cinco también.'::text),
(399416,44380,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, le premier ado a torsadé la pâte, et apparemment les cinq autres ...'::text,'aussi'::text,'aussi'::text,'non plus'::text,'Ma belle, le premier ado a torsadé la pâte, et apparemment les cinq autres aussi.'::text),
(399419,44380,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ilk genç hamuru büktü, anlaşılan diğer beşi de ...'::text,'öyle yaptı'::text,'öyle yaptı'::text,'yapmadı'::text,'Kanka, ilk genç hamuru büktü, anlaşılan diğer beşi de öyle yaptı.'::text),
(399420,44380,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, az első tini megcsavarta a tésztát, és állítólag a másik öt ...'::text,'is'::text,'is'::text,'sem'::text,'Csajszi, az első tini megcsavarta a tésztát, és állítólag a másik öt is.'::text),
(399432,44382,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Abendessen ... sie jedes Stück Teig zu einem Zopf gedreht haben. Klar, ein schneller Job.'::text,'werden'::text,'werden'::text,'werden'::text,'Bis zum Abendessen werden sie jedes Stück Teig zu einem Zopf gedreht haben. Klar, ein schneller Job.'::text),
(399436,44382,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечері вони ... кожен шматок тіста в косу. Явно швидка робота.'::text,'заплетуть'::text,'заплетуть'::text,'заплітатимуть'::text,'До вечері вони заплетуть кожен шматок тіста в косу. Явно швидка робота.'::text),
(399435,44382,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la cena, ... cada trozo de masa en una trenza. Un trabajo rápido, está claro.'::text,'habrán trenzado'::text,'trenzarán'::text,'estarán trenzando'::text,'Para la cena, habrán trenzado cada trozo de masa en una trenza. Un trabajo rápido, está claro.'::text),
(399434,44382,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le dîner, ils ... chaque morceau de pâte en tresse. Clairement un travail rapide.'::text,'auront tressé'::text,'tresseront'::text,'seront en train de tresser'::text,'D''ici le dîner, ils auront tressé chaque morceau de pâte en tresse. Clairement un travail rapide.'::text),
(399437,44382,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akşam yemeğine kadar her hamur parçasını örgü şeklinde ..., belli ki hızlı bir iş.'::text,'örmüş olacaklar'::text,'örecekler'::text,'örüyor olacaklar'::text,'Akşam yemeğine kadar her hamur parçasını örgü şeklinde örmüş olacaklar, belli ki hızlı bir iş.'::text),
(399438,44382,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vacsoráig ... minden tésztadarabot fonatba. Nyilván gyors meló.'::text,'befonják'::text,'befonják'::text,'fonni fogják'::text,'Vacsoráig befonják minden tésztadarabot fonatba. Nyilván gyors meló.'::text),
(399441,44383,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... sie diesen Teig schon eine Stunde lang gedreht haben, Bro, das ist echt irre.'::text,'werden'::text,'werden'::text,'werden'::text,'Bis Mittag werden sie diesen Teig schon eine Stunde lang gedreht haben, Bro, das ist echt irre.'::text),
(399445,44383,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня вони ... це тісто вже годину, бро, це якось дико.'::text,'скручуватимуть'::text,'скручуватимуть'::text,'скрутять'::text,'До полудня вони скручуватимуть це тісто вже годину, бро, це якось дико.'::text),
(399444,44383,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía ... esta masa durante una hora, tío, es un poco de locos.'::text,'habrán estado retorciendo'::text,'estarán retorciendo'::text,'retorcerán'::text,'Para el mediodía habrán estado retorciendo esta masa durante una hora, tío, es un poco de locos.'::text),
(399443,44383,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, ils ... cette pâte depuis une heure, frérot, c''est un peu n''importe quoi.'::text,'auront torsadé'::text,'seront en train de torsader'::text,'torsaderont'::text,'D''ici midi, ils auront torsadé cette pâte depuis une heure, frérot, c''est un peu n''importe quoi.'::text),
(399446,44383,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar bu hamuru bir saattir ..., kanka, biraz kafayı yemişler.'::text,'büküyor olacaklar'::text,'büküyor olacaklar'::text,'bükecekler'::text,'Öğlene kadar bu hamuru bir saattir büküyor olacaklar, kanka, biraz kafayı yemişler.'::text),
(399447,44383,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre már egy órája ... ezt a tésztát, tesó, ez kicsit elborult.'::text,'csavarják majd'::text,'csavarják majd'::text,'megcsavarják'::text,'Délre már egy órája csavarják majd ezt a tésztát, tesó, ez kicsit elborult.'::text),
(399450,44384,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, wenn sie das Tuch nicht ausgewrungen hätte, ... der Boden klatschnass gewesen.'::text,'wäre'::text,'wird'::text,'war'::text,'Nee Bro, wenn sie das Tuch nicht ausgewrungen hätte, wäre der Boden klatschnass gewesen.'::text),
(399454,44384,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, якби вона не викрутила ту ганчірку, підлога ... мокрою наскрізь.'::text,'була б'::text,'буде'::text,'була'::text,'Не, бро, якби вона не викрутила ту ганчірку, підлога була б мокрою наскрізь.'::text),
(399453,44384,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, si no hubiera escurrido ese trapo, el suelo ... empapado.'::text,'habría estado'::text,'estará'::text,'estaba'::text,'Qué va, tío, si no hubiera escurrido ese trapo, el suelo habría estado empapado.'::text),
(399452,44384,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, si elle n''avait pas essoré ce chiffon, le sol ... trempé.'::text,'aurait été'::text,'sera'::text,'était'::text,'Nan frérot, si elle n''avait pas essoré ce chiffon, le sol aurait été trempé.'::text),
(399455,44384,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, o bezi sıkmasaydı yer sırılsıklam ...'::text,'olurdu'::text,'olacak'::text,'idi'::text,'Yok kanka, o bezi sıkmasaydı yer sırılsıklam olurdu.'::text),
(399456,44384,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, ha nem csavarta volna ki azt a rongyot, a padló csuromvizes ...'::text,'lett volna'::text,'lesz'::text,'volt'::text,'Nem, tesó, ha nem csavarta volna ki azt a rongyot, a padló csuromvizes lett volna.'::text),
(399459,44385,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie das Tuch nicht ausgewrungen hätte, ... es jetzt immer noch tropfen.'::text,'würde'::text,'hätte'::text,'wird'::text,'Wenn sie das Tuch nicht ausgewrungen hätte, würde es jetzt immer noch tropfen.'::text),
(399463,44385,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не викрутила ганчірку, з неї й досі ... вода.'::text,'капала б'::text,'капала б'::text,'капатиме'::text,'Якби вона не викрутила ганчірку, з неї й досі капала б вода.'::text),
(399462,44385,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera escurrido el trapo, ahora todavía ... goteando.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si no hubiera escurrido el trapo, ahora todavía estaría goteando.'::text),
(399461,44385,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas essoré le chiffon, il ... encore en train de goutter maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si elle n''avait pas essoré le chiffon, il serait encore en train de goutter maintenant.'::text),
(399464,44385,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bezi sıkmasaydı, şimdi hâlâ damlıyor ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Bezi sıkmasaydı, şimdi hâlâ damlıyor olurdu.'::text),
(399465,44385,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem csavarta volna ki a rongyot, most is még ...'::text,'csöpögne'::text,'csöpögött volna'::text,'csöpögni fog'::text,'Ha nem csavarta volna ki a rongyot, most is még csöpögne.'::text),
(399468,44386,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man glaubt, dass der riesige Teigstrang von allen sechs Teenagern gleichzeitig ...'::text,'gedreht wurde'::text,'drehen'::text,'drehend'::text,'Man glaubt, dass der riesige Teigstrang von allen sechs Teenagern gleichzeitig gedreht wurde.'::text),
(399472,44386,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що гігантський джгут із тіста ... всі шестеро підлітків одночасно.'::text,'скрутили'::text,'скручувати'::text,'скручування'::text,'Вважається, що гігантський джгут із тіста скрутили всі шестеро підлітків одночасно.'::text),
(399471,44386,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que la cuerda gigante de masa ... por los seis adolescentes a la vez.'::text,'fue retorcida'::text,'retorcer'::text,'retorciendo'::text,'Se cree que la cuerda gigante de masa fue retorcida por los seis adolescentes a la vez.'::text),
(399470,44386,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que la corde de pâte géante ... par les six ados en même temps.'::text,'a été torsadée'::text,'torsader'::text,'torsadant'::text,'On pense que la corde de pâte géante a été torsadée par les six ados en même temps.'::text),
(399473,44386,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev hamur ipinin altı genç tarafından aynı anda ... düşünülüyor.'::text,'büküldüğü'::text,'bükmek'::text,'bükerek'::text,'Dev hamur ipinin altı genç tarafından aynı anda büküldüğü düşünülüyor.'::text),
(399474,44386,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy az óriási tésztakötelet mind a hat tini egyszerre ...'::text,'csavarta meg'::text,'megcsavarni'::text,'csavarva'::text,'Úgy tartják, hogy az óriási tésztakötelet mind a hat tini egyszerre csavarta meg.'::text),
(343713,38191,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, morgen um diese Zeit ... wieder Brot in diesem Innenhof wie eine Legende.'::text,'stemmst du gerade'::text,'wirst du stemmen'::text,'stemmst du'::text,'Ehrlich, morgen um diese Zeit stemmst du gerade wieder Brot in diesem Innenhof wie eine Legende.'::text),
(343717,38191,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, завтра о цій порі ти знову ... хліб на тому подвір''ї, як легенда.'::text,'підніматимеш'::text,'піднімеш'::text,'піднімаєш'::text,'Чесно, завтра о цій порі ти знову підніматимеш хліб на тому подвір''ї, як легенда.'::text),
(343716,38191,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, mañana a esta hora ... pan otra vez en ese patio como una leyenda.'::text,'estarás levantando'::text,'levantarás'::text,'levantas'::text,'Sinceramente, mañana a esta hora estarás levantando pan otra vez en ese patio como una leyenda.'::text),
(343715,38191,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, demain à la même heure tu ... du pain dans cette cour comme une légende.'::text,'seras en train de brandir'::text,'brandiras'::text,'brandis'::text,'Franchement, demain à la même heure tu seras en train de brandir du pain dans cette cour comme une légende.'::text),
(343718,38191,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, yarın bu saatlerde o avluda yine bir efsane gibi ekmek ...'::text,'kaldırıyor olacaksın'::text,'kaldıracaksın'::text,'kaldırıyorsun'::text,'Açıkçası, yarın bu saatlerde o avluda yine bir efsane gibi ekmek kaldırıyor olacaksın.'::text),
(343719,38191,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, holnap ilyenkor megint ... a kenyeret abban az udvarban, mint egy legenda.'::text,'épp emelgetni fogod'::text,'felemeled'::text,'emeled'::text,'Őszintén, holnap ilyenkor megint épp emelgetni fogod a kenyeret abban az udvarban, mint egy legenda.'::text),
(343731,38193,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn in diesem Innenhof jemand ein Brot hochhält, ... die Gäste und klatschen, offensichtlich.'::text,'jubeln'::text,'jubelten'::text,'werden jubeln'::text,'Wenn in diesem Innenhof jemand ein Brot hochhält, jubeln die Gäste und klatschen, offensichtlich.'::text),
(343735,38193,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На цьому подвір''ї, якщо хтось піднімає буханець, гості ... й плескають, очевидно.'::text,'вигукують'::text,'вигукували'::text,'вигукуватимуть'::text,'На цьому подвір''ї, якщо хтось піднімає буханець, гості вигукують й плескають, очевидно.'::text),
(343734,38193,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este patio, si alguien levanta una hogaza, los invitados ... y aplauden, obviamente.'::text,'vitorean'::text,'vitorearon'::text,'vitorearán'::text,'En este patio, si alguien levanta una hogaza, los invitados vitorean y aplauden, obviamente.'::text),
(343733,38193,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans cette cour, si quelqu''un lève une miche, les invités ... et applaudissent, évidemment.'::text,'acclament'::text,'ont acclamé'::text,'acclameront'::text,'Dans cette cour, si quelqu''un lève une miche, les invités acclament et applaudissent, évidemment.'::text),
(343736,38193,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu avluda biri somun kaldırırsa, misafirler ... ve alkışlar, tabii ki.'::text,'tezahürat yapar'::text,'tezahürat yaptı'::text,'tezahürat yapacak'::text,'Bu avluda biri somun kaldırırsa, misafirler tezahürat yapar ve alkışlar, tabii ki.'::text),
(343737,38193,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben az udvarban, ha valaki felemel egy cipót, a vendégek ... és tapsolnak, nyilván.'::text,'ujjonganak'::text,'ujjongtak'::text,'ujjongani fognak'::text,'Ebben az udvarban, ha valaki felemel egy cipót, a vendégek ujjonganak és tapsolnak, nyilván.'::text),
(343740,38194,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, früher ... ihre Oma für jede Party in diesem Innenhof Brote, echt.'::text,'backte'::text,'backte immer'::text,'war es gewohnt zu backen'::text,'Bro, früher backte ihre Oma für jede Party in diesem Innenhof Brote, echt.'::text),
(343744,38194,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, колись її бабуся ... хліб на кожну вечірку на цьому подвір''ї, реально.'::text,'пекла'::text,'пекла'::text,'звикла пекти'::text,'Бро, колись її бабуся пекла хліб на кожну вечірку на цьому подвір''ї, реально.'::text),
(343743,38194,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, antes su abuela ... hogazas para cada fiesta en este patio, en serio.'::text,'horneaba'::text,'solía hornear'::text,'estaba acostumbrada a hornear'::text,'Tío, antes su abuela horneaba hogazas para cada fiesta en este patio, en serio.'::text),
(343742,38194,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, à l''époque sa grand-mère ... des miches pour chaque fête dans cette cour, sérieux.'::text,'faisait'::text,'faisait'::text,'avait l''habitude de faire'::text,'Frérot, à l''époque sa grand-mère faisait des miches pour chaque fête dans cette cour, sérieux.'::text),
(343745,38194,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eskiden babaannesi bu avludaki her parti için somun ..., cidden.'::text,'pişirirdi'::text,'pişirirdi'::text,'pişirmeye alışkındı'::text,'Kanka, eskiden babaannesi bu avludaki her parti için somun pişirirdi, cidden.'::text),
(343746,38194,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, annak idején a nagyija minden bulira ebben az udvarban ... a cipókat, komolyan.'::text,'sütötte'::text,'sütötte'::text,'hozzá volt szokva, hogy süsse'::text,'Tesó, annak idején a nagyija minden bulira ebben az udvarban sütötte a cipókat, komolyan.'::text),
(343749,38195,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie ... diesen Laib ständig über den Kopf im Innenhof, ziemlich ikonisch.'::text,'stemmt'::text,'zu stemmen'::text,'stemmen'::text,'Yo, sie stemmt diesen Laib ständig über den Kopf im Innenhof, ziemlich ikonisch.'::text),
(343753,38195,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вона постійно ... той буханець над головою на подвір''ї, досить культово.'::text,'піднімає'::text,'піднімати'::text,'піднімай'::text,'Йо, вона постійно піднімає той буханець над головою на подвір''ї, досить культово.'::text),
(343752,38195,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, no para de ... esa hogaza por encima de la cabeza en el patio, bastante icónico.'::text,'levantar'::text,'levantar'::text,'levanta'::text,'Ey, no para de levantar esa hogaza por encima de la cabeza en el patio, bastante icónico.'::text),
(343751,38195,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, elle n''arrête pas de ... cette miche au-dessus de sa tête dans la cour, un peu iconique.'::text,'brandir'::text,'brandir'::text,'brandit'::text,'Yo, elle n''arrête pas de brandir cette miche au-dessus de sa tête dans la cour, un peu iconique.'::text),
(343754,38195,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, avluda o somunu başının üstüne ... duruyor, baya ikonik.'::text,'kaldırıp'::text,'kaldırmak'::text,'kaldır'::text,'Yo, avluda o somunu başının üstüne kaldırıp duruyor, baya ikonik.'::text),
(343755,38195,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, folyton ... azt a cipót a feje fölé az udvarban, elég ikonikus.'::text,'emeli'::text,'emelni'::text,'emel'::text,'Figyu, folyton emeli azt a cipót a feje fölé az udvarban, elég ikonikus.'::text),
(343758,38196,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gäste essen im Innenhof, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Die Gäste essen im Innenhof, oder?'::text),
(343762,38196,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гості їдять на подвір''ї, ...?'::text,'так'::text,'так'::text,'так'::text,'Гості їдять на подвір''ї, так?'::text),
(343761,38196,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los invitados están comiendo en el patio, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Los invitados están comiendo en el patio, ¿verdad?'::text),
(343760,38196,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les invités mangent dans la cour, ... ?'::text,'non'::text,'non'::text,'non'::text,'Les invités mangent dans la cour, non ?'::text),
(343763,38196,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Misafirler avluda yemek yiyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Misafirler avluda yemek yiyor, değil mi?'::text),
(343764,38196,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendégek az udvaron esznek, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A vendégek az udvaron esznek, ugye?'::text),
(343767,38197,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Innenhof hat auf jeder Seite Mauern, und das Herrenhaus ..., weil er Teil des Herrenhauses ist.'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Der Innenhof hat auf jeder Seite Mauern, und das Herrenhaus auch, weil er Teil des Herrenhauses ist.'::text),
(343771,38197,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подвір''я має стіни з усіх боків, і маєток ..., бо воно є частиною маєтку.'::text,'теж'::text,'теж'::text,'теж ні'::text,'Подвір''я має стіни з усіх боків, і маєток теж, бо воно є частиною маєтку.'::text),
(343770,38197,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El patio tiene muros por todos lados, y la mansión ..., porque forma parte de la mansión.'::text,'también'::text,'también'::text,'tampoco'::text,'El patio tiene muros por todos lados, y la mansión también, porque forma parte de la mansión.'::text),
(343769,38197,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cour a des murs de tous les côtés, et le manoir ..., parce qu''elle fait partie du manoir.'::text,'aussi'::text,'aussi'::text,'non plus'::text,'La cour a des murs de tous les côtés, et le manoir aussi, parce qu''elle fait partie du manoir.'::text),
(343772,38197,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avlunun her tarafında duvar var, konağın da ..., çünkü avlu konağın bir parçası.'::text,'öyle'::text,'öyle'::text,'öyle değil'::text,'Avlunun her tarafında duvar var, konağın da öyle, çünkü avlu konağın bir parçası.'::text),
(343773,38197,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az udvarnak minden oldalán fal van, és a kúriának ..., mert az udvar a kúria része.'::text,'is'::text,'is'::text,'sem'::text,'Az udvarnak minden oldalán fal van, és a kúriának is, mert az udvar a kúria része.'::text),
(343776,38198,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mitternacht ... die Gäste im Innenhof etwa zwanzig Brote gegessen haben.'::text,'werden'::text,'werden'::text,'essen'::text,'Bis Mitternacht werden die Gäste im Innenhof etwa zwanzig Brote gegessen haben.'::text),
(343780,38198,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До опівночі гості ... на подвір''ї приблизно двадцять буханців.'::text,'з''їдять'::text,'з''їдять'::text,'їдять'::text,'До опівночі гості з''їдять на подвір''ї приблизно двадцять буханців.'::text),
(343779,38198,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para medianoche, los invitados ... aproximadamente veinte hogazas en el patio.'::text,'habrán comido'::text,'comerán'::text,'comen'::text,'Para medianoche, los invitados habrán comido aproximadamente veinte hogazas en el patio.'::text),
(343778,38198,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici minuit, les invités ... environ vingt miches dans la cour.'::text,'auront mangé'::text,'mangeront'::text,'mangent'::text,'D''ici minuit, les invités auront mangé environ vingt miches dans la cour.'::text),
(343781,38198,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısına kadar misafirler avluda yaklaşık yirmi somun ...'::text,'yemiş olacak'::text,'yiyecek'::text,'yer'::text,'Gece yarısına kadar misafirler avluda yaklaşık yirmi somun yemiş olacak.'::text),
(343782,38198,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélig a vendégek körülbelül húsz cipót ... az udvarban.'::text,'megesznek'::text,'meg fognak enni'::text,'esznek'::text,'Éjfélig a vendégek körülbelül húsz cipót megesznek az udvarban.'::text),
(343794,38200,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gäste ... gerade im Innenhof, während sie das Brot hochhebt.'::text,'klatschen'::text,'klatschen'::text,'haben geklatscht'::text,'Die Gäste klatschen gerade im Innenhof, während sie das Brot hochhebt.'::text),
(343798,38200,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гості прямо зараз ... на подвір''ї, поки вона піднімає буханець.'::text,'плескають'::text,'плескають'::text,'поплескали'::text,'Гості прямо зараз плескають на подвір''ї, поки вона піднімає буханець.'::text),
(343797,38200,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los invitados ... en el patio ahora mismo mientras ella levanta la hogaza.'::text,'están aplaudiendo'::text,'aplauden'::text,'han aplaudido'::text,'Los invitados están aplaudiendo en el patio ahora mismo mientras ella levanta la hogaza.'::text),
(343796,38200,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les invités ... dans la cour en ce moment pendant qu''elle lève la miche.'::text,'applaudissent'::text,'applaudissent'::text,'ont applaudi'::text,'Les invités applaudissent dans la cour en ce moment pendant qu''elle lève la miche.'::text),
(343799,38200,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O somunu kaldırırken misafirler şu anda avluda ...'::text,'alkışlıyor'::text,'alkışlar'::text,'alkışladı'::text,'O somunu kaldırırken misafirler şu anda avluda alkışlıyor.'::text),
(343800,38200,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendégek éppen most ... az udvarban, miközben ő felemeli a cipót.'::text,'tapsolnak'::text,'tapsolnak'::text,'tapsoltak'::text,'A vendégek éppen most tapsolnak az udvarban, miközben ő felemeli a cipót.'::text),
(343803,38201,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Über einen Platz voller Tauben ..., bevor sie den Innenhof erreichte.'::text,'war sie gelaufen'::text,'ist sie gelaufen'::text,'läuft sie'::text,'Über einen Platz voller Tauben war sie gelaufen, bevor sie den Innenhof erreichte.'::text),
(343807,38201,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж дійти до подвір''я, вона ... через площу, повну голубів.'::text,'пройшла'::text,'пройшла'::text,'проходить'::text,'Перш ніж дійти до подвір''я, вона пройшла через площу, повну голубів.'::text),
(343806,38201,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de llegar al patio, ... por una plaza llena de palomas.'::text,'había caminado'::text,'ha caminado'::text,'camina'::text,'Antes de llegar al patio, había caminado por una plaza llena de palomas.'::text),
(343805,38201,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant d''arriver dans la cour, elle ... une place pleine de pigeons.'::text,'avait traversé'::text,'a traversé'::text,'traverse'::text,'Avant d''arriver dans la cour, elle avait traversé une place pleine de pigeons.'::text),
(343808,38201,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avluya varmadan önce güvercinlerle dolu bir meydandan ...'::text,'geçmişti'::text,'geçti'::text,'geçiyor'::text,'Avluya varmadan önce güvercinlerle dolu bir meydandan geçmişti.'::text),
(343809,38201,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt az udvarba ért, ... egy galambokkal teli téren.'::text,'átsétált'::text,'átsétált'::text,'átsétál'::text,'Mielőtt az udvarba ért, átsétált egy galambokkal teli téren.'::text),
(353001,39223,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit zwei Stunden Füllung in Teigkreise. Klar, ein schneller Snack.'::text,'löffelt'::text,'löffelt gerade'::text,'löffelt'::text,'Sie löffelt seit zwei Stunden Füllung in Teigkreise. Klar, ein schneller Snack.'::text),
(353005,39223,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже дві години ... начинку в кружечки тіста. Явно швидкий перекус.'::text,'накладає ложкою'::text,'накладає ложкою'::text,'накладає ложкою'::text,'Вона вже дві години накладає ложкою начинку в кружечки тіста. Явно швидкий перекус.'::text),
(353004,39223,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... relleno con la cuchara en círculos de masa desde hace dos horas. Un tentempié rápido, está claro.'::text,'lleva poniendo'::text,'está poniendo'::text,'pone'::text,'Ella lleva poniendo relleno con la cuchara en círculos de masa desde hace dos horas. Un tentempié rápido, está claro.'::text),
(353003,39223,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ça fait deux heures qu''elle ... de la garniture dans des cercles de pâte. Clairement un petit en-cas rapide.'::text,'met à la cuillère'::text,'est en train de mettre'::text,'met'::text,'Ça fait deux heures qu''elle met à la cuillère de la garniture dans des cercles de pâte. Clairement un petit en-cas rapide.'::text),
(353006,39223,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki saattir hamur yuvarlaklarına kaşıkla dolgu ..., belli ki hızlı bir atıştırmalık.'::text,'koyuyor'::text,'koyuyor'::text,'koyar'::text,'İki saattir hamur yuvarlaklarına kaşıkla dolgu koyuyor, belli ki hızlı bir atıştırmalık.'::text),
(353007,39223,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már két órája ... kanállal a tölteléket a tésztakorongokba. Nyilván egy gyors nasi.'::text,'rakja'::text,'rakja éppen'::text,'rakja'::text,'Már két órája rakja kanállal a tölteléket a tésztakorongokba. Nyilván egy gyors nasi.'::text),
(353010,39224,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die letzte Teigtasche, als die Füllung ausging. Tolle Planung, offensichtlich.'::text,'verschloss gerade'::text,'verschloss'::text,'hat verschlossen'::text,'Sie verschloss gerade die letzte Teigtasche, als die Füllung ausging. Tolle Planung, offensichtlich.'::text),
(353014,39224,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... останній вареник, коли закінчилася начинка. Чудове планування, очевидно.'::text,'ліпила'::text,'зліпила'::text,'зліпила'::text,'Вона ліпила останній вареник, коли закінчилася начинка. Чудове планування, очевидно.'::text),
(353013,39224,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la última empanadilla cuando se acabó el relleno. Gran planificación, obviamente.'::text,'estaba cerrando'::text,'cerró'::text,'ha cerrado'::text,'Ella estaba cerrando la última empanadilla cuando se acabó el relleno. Gran planificación, obviamente.'::text),
(353012,39224,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le dernier ravioli quand la garniture a manqué. Super organisation, évidemment.'::text,'fermait'::text,'a fermé'::text,'a fermé'::text,'Elle fermait le dernier ravioli quand la garniture a manqué. Super organisation, évidemment.'::text),
(353015,39224,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dolgu bittiğinde son mantıyı ..., harika planlama tabii.'::text,'kapatıyordu'::text,'kapattı'::text,'kapattı'::text,'Dolgu bittiğinde son mantıyı kapatıyordu, harika planlama tabii.'::text),
(353016,39224,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utolsó gombócot ..., amikor elfogyott a töltelék. Remek tervezés, nyilván.'::text,'zárta le épp'::text,'lezárta'::text,'lezárta'::text,'Az utolsó gombócot zárta le épp, amikor elfogyott a töltelék. Remek tervezés, nyilván.'::text),
(353019,39225,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Kleine hat zugegeben, die rote Füllung direkt aus der Schüssel ..., kein Witz.'::text,'gegessen zu haben'::text,'zu essen'::text,'gegessen'::text,'Bro, der Kleine hat zugegeben, die rote Füllung direkt aus der Schüssel gegessen zu haben, kein Witz.'::text),
(353023,39225,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, малий зізнався, що ... червону начинку прямо з миски, без жартів.'::text,'їв'::text,'їсти'::text,'з''їдено'::text,'Бро, малий зізнався, що їв червону начинку прямо з миски, без жартів.'::text),
(353022,39225,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el crío admitió ... el relleno rojo directamente del bol, te lo juro.'::text,'haberse comido'::text,'comer'::text,'comido'::text,'Tío, el crío admitió haberse comido el relleno rojo directamente del bol, te lo juro.'::text),
(353021,39225,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le petit a avoué ... la garniture rouge direct dans le bol, sans mentir.'::text,'avoir mangé'::text,'manger'::text,'mangé'::text,'Frérot, le petit a avoué avoir mangé la garniture rouge direct dans le bol, sans mentir.'::text),
(353024,39225,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ufaklık kırmızı dolguyu doğrudan kaseden ... itiraf etti, yemin ederim.'::text,'yediğini'::text,'yemeyi'::text,'yenmiş'::text,'Kanka, ufaklık kırmızı dolguyu doğrudan kaseden yediğini itiraf etti, yemin ederim.'::text),
(353025,39225,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a kölyök bevallotta, hogy ... a piros tölteléket egyenesen a tálból, nem viccelek.'::text,'megette'::text,'megenni'::text,'megevett'::text,'Tesó, a kölyök bevallotta, hogy megette a piros tölteléket egyenesen a tálból, nem viccelek.'::text),
(353028,39226,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, mehr Füllung ..., weil die Schüssel schon ziemlich leer ist.'::text,'hätte sie machen sollen'::text,'muss sie gemacht haben'::text,'kann sie nicht gemacht haben'::text,'Bro, mehr Füllung hätte sie machen sollen, weil die Schüssel schon ziemlich leer ist.'::text),
(353032,39226,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... більше начинки, бо та миска вже майже порожня.'::text,'мала б зробити'::text,'мабуть, зробила'::text,'не могла зробити'::text,'Бро, вона мала б зробити більше начинки, бо та миска вже майже порожня.'::text),
(353031,39226,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... más relleno, porque ese bol ya está casi vacío.'::text,'debería haber hecho'::text,'debe de haber hecho'::text,'no puede haber hecho'::text,'Tío, debería haber hecho más relleno, porque ese bol ya está casi vacío.'::text),
(353030,39226,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... plus de garniture, parce que ce bol est déjà presque vide.'::text,'aurait dû faire'::text,'a dû faire'::text,'n''a pas pu faire'::text,'Frérot, elle aurait dû faire plus de garniture, parce que ce bol est déjà presque vide.'::text),
(353033,39226,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, daha fazla dolgu ..., çünkü o kase şimdiden baya boş.'::text,'yapmalıydı'::text,'yapmış olmalı'::text,'yapmış olamaz'::text,'Kanka, daha fazla dolgu yapmalıydı, çünkü o kase şimdiden baya boş.'::text),
(353034,39226,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, több tölteléket ..., mert az a tál már eléggé üres.'::text,'kellett volna csinálnia'::text,'biztosan csinált'::text,'nem csinálhatott'::text,'Tesó, több tölteléket kellett volna csinálnia, mert az a tál már eléggé üres.'::text),
(353037,39227,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Rahmen des Audits ließ sie den Jungen 1 Löffel der Füllung ...'::text,'probieren'::text,'probieren'::text,'probiert'::text,'Im Rahmen des Audits ließ sie den Jungen 1 Löffel der Füllung probieren.'::text),
(353041,39227,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У межах аудиту вона попросила хлопчика ... 1 ложку начинки.'::text,'скуштувати'::text,'скуштувати'::text,'скуштовано'::text,'У межах аудиту вона попросила хлопчика скуштувати 1 ложку начинки.'::text),
(353040,39227,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Como parte de la auditoría, hizo que el niño ... 1 cucharada del relleno.'::text,'probara'::text,'probara'::text,'probado'::text,'Como parte de la auditoría, hizo que el niño probara 1 cucharada del relleno.'::text),
(353039,39227,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans le cadre de l''audit, elle a fait ... 1 cuillère de garniture au garçon.'::text,'goûter'::text,'goûter'::text,'goûté'::text,'Dans le cadre de l''audit, elle a fait goûter 1 cuillère de garniture au garçon.'::text),
(353042,39227,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denetim kapsamında çocuğa dolgudan 1 kaşık ...'::text,'tattırdı'::text,'tattırdı'::text,'tattırdı'::text,'Denetim kapsamında çocuğa dolgudan 1 kaşık tattırdı.'::text),
(353043,39227,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az audit részeként ... a fiúval 1 kanál tölteléket.'::text,'megkóstoltatott'::text,'megkóstoltatott'::text,'megkóstoltatott'::text,'Az audit részeként megkóstoltatott a fiúval 1 kanál tölteléket.'::text),
(353046,39228,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünscht sich, dass sie mehr Füllung ..., weil die Schüssel fast leer ist.'::text,'gemacht hätte'::text,'machte'::text,'machen wird'::text,'Sie wünscht sich, dass sie mehr Füllung gemacht hätte, weil die Schüssel fast leer ist.'::text),
(353050,39228,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона шкодує, що не ... більше начинки, бо миска майже порожня.'::text,'зробила'::text,'зробила'::text,'зробить'::text,'Вона шкодує, що не зробила більше начинки, бо миска майже порожня.'::text),
(353049,39228,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desearía ... más relleno, porque el bol está casi vacío.'::text,'haber hecho'::text,'hacer'::text,'hará'::text,'Desearía haber hecho más relleno, porque el bol está casi vacío.'::text),
(353048,39228,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aurait aimé ... plus de garniture, parce que le bol est presque vide.'::text,'avoir fait'::text,'faire'::text,'fera'::text,'Elle aurait aimé avoir fait plus de garniture, parce que le bol est presque vide.'::text),
(353051,39228,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke daha fazla dolgu ... diye düşünüyor, çünkü kase neredeyse boş.'::text,'yapsaydı'::text,'yapsa'::text,'yapacak'::text,'Keşke daha fazla dolgu yapsaydı diye düşünüyor, çünkü kase neredeyse boş.'::text),
(353052,39228,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak több tölteléket ..., mert a tál majdnem üres.'::text,'csinált volna'::text,'csinálna'::text,'csinál majd'::text,'Bárcsak több tölteléket csinált volna, mert a tál majdnem üres.'::text),
(353055,39229,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Füllung, ... aus dunkelroten Früchten gemacht ist, kommt in jede Teigtasche.'::text,'die'::text,'wer'::text,'deren'::text,'Die Füllung, die aus dunkelroten Früchten gemacht ist, kommt in jede Teigtasche.'::text),
(353059,39229,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Начинка, ... зроблена з темно-червоних ягід, іде в кожен вареник.'::text,'яка'::text,'хто'::text,'чия'::text,'Начинка, яка зроблена з темно-червоних ягід, іде в кожен вареник.'::text),
(353058,39229,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El relleno, ... está hecho de fruta roja oscura, va dentro de cada empanadilla.'::text,'que'::text,'quien'::text,'cuyo'::text,'El relleno, que está hecho de fruta roja oscura, va dentro de cada empanadilla.'::text),
(353057,39229,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La garniture, ... est faite de fruits rouge foncé, va dans chaque ravioli.'::text,'qui'::text,'qui'::text,'dont'::text,'La garniture, qui est faite de fruits rouge foncé, va dans chaque ravioli.'::text),
(353060,39229,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koyu kırmızı meyveden yapılan ... dolgu, her mantının içine konuyor.'::text,''::text,NULL::text,NULL::text,'Koyu kırmızı meyveden yapılan dolgu, her mantının içine konuyor.'::text),
(353061,39229,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A töltelék, ... sötétvörös gyümölcsből készül, minden gombócba bekerül.'::text,'amely'::text,'aki'::text,'amelynek'::text,'A töltelék, amely sötétvörös gyümölcsből készül, minden gombócba bekerül.'::text),
(353064,39230,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... in der weißen Schüssel ist aus dunkelroten Früchten gemacht.'::text,'Die Füllung'::text,'Eine Füllung'::text,'Füllung'::text,'Die Füllung in der weißen Schüssel ist aus dunkelroten Früchten gemacht.'::text),
(353068,39230,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... у білій мисці зроблена з темно-червоних ягід.'::text,'Начинка'::text,'Начинка'::text,'Начинка'::text,'Начинка у білій мисці зроблена з темно-червоних ягід.'::text),
(353067,39230,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... del bol blanco está hecho de fruta roja oscura.'::text,'El relleno'::text,'Un relleno'::text,'Relleno'::text,'El relleno del bol blanco está hecho de fruta roja oscura.'::text),
(353066,39230,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dans le bol blanc est faite de fruits rouge foncé.'::text,'La garniture'::text,'Une garniture'::text,'Garniture'::text,'La garniture dans le bol blanc est faite de fruits rouge foncé.'::text),
(353069,39230,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyaz kasedeki ... koyu kırmızı meyveden yapılmış.'::text,'dolgu'::text,'bir dolgu'::text,'dolgu'::text,'Beyaz kasedeki dolgu koyu kırmızı meyveden yapılmış.'::text),
(353070,39230,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a fehér tálban sötétvörös gyümölcsből készült.'::text,'A töltelék'::text,'Egy töltelék'::text,'Töltelék'::text,'A töltelék a fehér tálban sötétvörös gyümölcsből készült.'::text),
(353082,39232,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, es heißt, dass der Junge bis zum Abendessen jeden Löffel der übrigen Füllung ...'::text,'gegessen haben wird'::text,'essen wird'::text,'isst'::text,'Hör mal, es heißt, dass der Junge bis zum Abendessen jeden Löffel der übrigen Füllung gegessen haben wird.'::text),
(353086,39232,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, до вечері хлопчик ... кожну ложку залишків начинки.'::text,'з''їсть'::text,'з''їсть'::text,'їсть'::text,'Слухай, кажуть, до вечері хлопчик з''їсть кожну ложку залишків начинки.'::text),
(353085,39232,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer para la cena el niño ... cada cucharada del relleno sobrante.'::text,'se habrá comido'::text,'se comerá'::text,'se come'::text,'Oye, al parecer para la cena el niño se habrá comido cada cucharada del relleno sobrante.'::text),
(353084,39232,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment d''ici le dîner le garçon ... chaque cuillerée de la garniture restante.'::text,'aura mangé'::text,'mangera'::text,'mange'::text,'Écoute, apparemment d''ici le dîner le garçon aura mangé chaque cuillerée de la garniture restante.'::text),
(353087,39232,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan akşam yemeğine kadar çocuk artan dolgunun her kaşığını ...'::text,'yemiş olacak'::text,'yiyecek'::text,'yiyor'::text,'Dinle, anlaşılan akşam yemeğine kadar çocuk artan dolgunun her kaşığını yemiş olacak.'::text),
(353088,39232,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag vacsoráig a fiú a maradék töltelék minden kanalát ...'::text,'megeszi'::text,'meg fogja enni'::text,'eszi'::text,'Figyelj, állítólag vacsoráig a fiú a maradék töltelék minden kanalát megeszi.'::text),
(387939,43105,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich lüg nicht, du hast zugegeben, fünf Schichten ..., und bist trotzdem schnell aus jedem Ärmel rausgekommen.'::text,'getragen zu haben'::text,'zu tragen'::text,'trugst'::text,'Ich lüg nicht, du hast zugegeben, fünf Schichten getragen zu haben, und bist trotzdem schnell aus jedem Ärmel rausgekommen.'::text),
(387943,43105,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, ти зізнався, що ... п''ять шарів, і все одно швидко вибрався з кожного рукава.'::text,'носиш'::text,'носити'::text,'носив'::text,'Не брехатиму, ти зізнався, що носиш п''ять шарів, і все одно швидко вибрався з кожного рукава.'::text),
(387942,43105,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, admitiste ... cinco capas y aun así te escapaste rápido de cada manga.'::text,'llevar'::text,'llevar'::text,'llevaste'::text,'No te voy a mentir, admitiste llevar cinco capas y aun así te escapaste rápido de cada manga.'::text),
(387941,43105,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu as avoué ... cinq couches, et tu t''es quand même vite libéré de chaque manche.'::text,'porter'::text,'porter'::text,'portais'::text,'Je vais pas mentir, tu as avoué porter cinq couches, et tu t''es quand même vite libéré de chaque manche.'::text),
(387944,43105,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, beş kat ... itiraf ettin, yine de her kolluktan hızlıca kurtuldun.'::text,'giydiğini'::text,'giymeyi'::text,'giydin'::text,'Yalan yok, beş kat giydiğini itiraf ettin, yine de her kolluktan hızlıca kurtuldun.'::text),
(387945,43105,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, bevallottad, hogy öt réteget ..., és mégis gyorsan kibújtál minden ujjból.'::text,'viselsz'::text,'viselni'::text,'viseltél'::text,'Nem hazudok, bevallottad, hogy öt réteget viselsz, és mégis gyorsan kibújtál minden ujjból.'::text),
(387948,43106,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'So viele Schichten mit Ärmeln ..., klar, ein makelloser Plan.'::text,'hätte er nicht anziehen sollen'::text,'darf er nicht angezogen haben'::text,'konnte er nicht anziehen'::text,'So viele Schichten mit Ärmeln hätte er nicht anziehen sollen, klar, ein makelloser Plan.'::text),
(387952,43106,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому ... на себе стільки шарів із рукавами. Явно бездоганний план.'::text,'не варто було вдягати'::text,'не можна було вдягати'::text,'не вдалося вдягнути'::text,'Йому не варто було вдягати на себе стільки шарів із рукавами. Явно бездоганний план.'::text),
(387951,43106,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... tantas capas con mangas. Un plan impecable, está claro.'::text,'no debería haberse puesto'::text,'no debe de haberse puesto'::text,'no pudo ponerse'::text,'Él no debería haberse puesto tantas capas con mangas. Un plan impecable, está claro.'::text),
(387950,43106,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... autant de couches à manches. Clairement un plan parfait.'::text,'n''aurait pas dû mettre'::text,'ne devait pas avoir mis'::text,'n''a pas pu mettre'::text,'Il n''aurait pas dû mettre autant de couches à manches. Clairement un plan parfait.'::text),
(387953,43106,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kollu bu kadar çok katman ..., belli ki kusursuz bir plan.'::text,'giymemeliydi'::text,'giymemiş olmalı'::text,'giyemedi'::text,'Kollu bu kadar çok katman giymemeliydi, belli ki kusursuz bir plan.'::text),
(387954,43106,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... magára ennyi ujjas réteget. Nyilván hibátlan terv.'::text,'Nem kellett volna felvennie'::text,'Nem vehette fel'::text,'Nem tudta felvenni'::text,'Nem kellett volna felvennie magára ennyi ujjas réteget. Nyilván hibátlan terv.'::text),
(387957,43107,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht nur ... aus den Parka-Ärmeln, sondern er kämpfte auch mit dem Fleece. Wahrhaft anmutig.'::text,'entkam er'::text,'er entkam'::text,'er entkam wirklich'::text,'Nicht nur entkam er aus den Parka-Ärmeln, sondern er kämpfte auch mit dem Fleece. Wahrhaft anmutig.'::text),
(387961,43107,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не лише ... з рукавів парки, а й поборовся з фліскою. Справді граційно.'::text,'вибрався'::text,'вибрався'::text,'вибрався'::text,'Він не лише вибрався з рукавів парки, а й поборовся з фліскою. Справді граційно.'::text),
(387960,43107,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No solo ... de las mangas de la parka, sino que también luchó con el forro polar. Realmente elegante.'::text,'se escapó'::text,'se escapó'::text,'sí se escapó'::text,'No solo se escapó de las mangas de la parka, sino que también luchó con el forro polar. Realmente elegante.'::text),
(387959,43107,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non seulement ... des manches de la parka, mais il s''est aussi battu avec la polaire. Vraiment gracieux.'::text,'s''est-il échappé'::text,'il s''est échappé'::text,'il s''est bien échappé'::text,'Non seulement s''est-il échappé des manches de la parka, mais il s''est aussi battu avec la polaire. Vraiment gracieux.'::text),
(387962,43107,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parkanın kollarından ... kalmadı, polarla da boğuştu. Gerçekten zarif.'::text,'kurtulmakla'::text,'kurtulmakla'::text,'kurtulmakla'::text,'Parkanın kollarından kurtulmakla kalmadı, polarla da boğuştu. Gerçekten zarif.'::text),
(387963,43107,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nemcsak ... a parka ujjaiból, hanem a polárral is megküzdött. Igazán elegáns.'::text,'szabadult ki'::text,'kiszabadult'::text,'tényleg kiszabadult'::text,'Nemcsak szabadult ki a parka ujjaiból, hanem a polárral is megküzdött. Igazán elegáns.'::text),
(387975,43109,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, die Fleece-Ärmel ... weiter, damit er die Arme schneller rausziehen könnte.'::text,'wären'::text,'sind'::text,'werden sein'::text,'Er wünscht sich, die Fleece-Ärmel wären weiter, damit er die Arme schneller rausziehen könnte.'::text),
(387979,43109,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хоче, щоб рукави фліски ... ширшими, щоб швидше витягти руки.'::text,'були'::text,'є'::text,'будуть'::text,'Він хоче, щоб рукави фліски були ширшими, щоб швидше витягти руки.'::text),
(387978,43109,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gustaría que las mangas del forro polar ... más anchas, para poder sacar los brazos más rápido.'::text,'fueran'::text,'son'::text,'serán'::text,'Le gustaría que las mangas del forro polar fueran más anchas, para poder sacar los brazos más rápido.'::text),
(387977,43109,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait que les manches de la polaire ... plus larges, pour pouvoir sortir ses bras plus vite.'::text,'soient'::text,'sont'::text,'seront'::text,'Il aimerait que les manches de la polaire soient plus larges, pour pouvoir sortir ses bras plus vite.'::text),
(387980,43109,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke polar kolları daha geniş ..., kollarını daha hızlı çıkarabilirdi.'::text,'olsa'::text,NULL::text,'olacak'::text,'Keşke polar kolları daha geniş olsa, kollarını daha hızlı çıkarabilirdi.'::text),
(387981,43109,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak szélesebbek ... a polár ujjai, hogy gyorsabban kihúzhassa a karját.'::text,'lennének'::text,NULL::text,'lesznek'::text,'Azt kívánja, bárcsak szélesebbek lennének a polár ujjai, hogy gyorsabban kihúzhassa a karját.'::text),
(387984,43110,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der schwarze Parka, aus ... Ärmeln er sich zuerst herauswand, fiel auf den Boden.'::text,'dessen'::text,'welchem'::text,'dem'::text,'Der schwarze Parka, aus dessen Ärmeln er sich zuerst herauswand, fiel auf den Boden.'::text),
(387988,43110,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чорна парка, з ... рукавів він вибрався першим, упала на підлогу.'::text,'чиїх'::text,'якої'::text,'що'::text,'Чорна парка, з чиїх рукавів він вибрався першим, упала на підлогу.'::text),
(387987,43110,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La parka negra, de ... mangas se quitó primero, cayó al suelo.'::text,'cuyas'::text,'la cual'::text,'que'::text,'La parka negra, de cuyas mangas se quitó primero, cayó al suelo.'::text),
(387986,43110,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La parka noire, ... il avait d''abord retiré les manches, est tombée par terre.'::text,'dont'::text,'laquelle'::text,'que'::text,'La parka noire, dont il avait d''abord retiré les manches, est tombée par terre.'::text),
(387989,43110,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İlk önce kollarından ... sıyrıldığı siyah parka yere düştü.'::text,''::text,NULL::text,NULL::text,'İlk önce kollarından sıyrıldığı siyah parka yere düştü.'::text),
(387990,43110,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fekete parka, ... ujjaiból először bújt ki, a padlóra esett.'::text,'amelynek az'::text,'amely'::text,'ami'::text,'A fekete parka, amelynek az ujjaiból először bújt ki, a padlóra esett.'::text),
(387993,43111,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'To-do 1: beide Arme aus ... des Parkas ziehen.'::text,'den Ärmeln'::text,'Ärmeln'::text,'einem Ärmel'::text,'To-do 1: beide Arme aus den Ärmeln des Parkas ziehen.'::text),
(387997,43111,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завдання 1: витягти обидві руки з ... парки.'::text,'рукавів'::text,'рукавів'::text,'рукавів'::text,'Завдання 1: витягти обидві руки з рукавів парки.'::text),
(387996,43111,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tarea 1: sacar ambos brazos de ... de la parka.'::text,'las mangas'::text,'mangas'::text,'una manga'::text,'Tarea 1: sacar ambos brazos de las mangas de la parka.'::text),
(387995,43111,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Action n° 1 : retirer les deux bras ... de la parka.'::text,'des manches'::text,'de manches'::text,'d''une manche'::text,'Action n° 1 : retirer les deux bras des manches de la parka.'::text),
(387998,43111,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aksiyon maddesi 1: iki kolu da parkanın ... çıkar.'::text,'kollarından'::text,'kollarından'::text,'bir kolundan'::text,'Aksiyon maddesi 1: iki kolu da parkanın kollarından çıkar.'::text),
(387999,43111,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'1. teendő: mindkét kart kihúzni a parka ...'::text,'ujjaiból'::text,'ujjaiból'::text,'egy ujjából'::text,'1. teendő: mindkét kart kihúzni a parka ujjaiból.'::text),
(388002,43112,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er zog die Arme aus den Parka-Ärmeln, ... er in der warmen Hütte war.'::text,'jetzt, wo'::text,'selbst wenn'::text,'falls'::text,'Er zog die Arme aus den Parka-Ärmeln, jetzt, wo er in der warmen Hütte war.'::text),
(388006,43112,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він витягнув руки з рукавів парки, ... був у теплій хатинці.'::text,'тепер, коли'::text,'навіть якщо'::text,'на випадок, якщо'::text,'Він витягнув руки з рукавів парки, тепер, коли був у теплій хатинці.'::text),
(388005,43112,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sacó los brazos de las mangas de la parka ... estaba dentro de la cálida cabaña.'::text,'ahora que'::text,'aunque'::text,'por si'::text,'Sacó los brazos de las mangas de la parka ahora que estaba dentro de la cálida cabaña.'::text),
(388004,43112,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a sorti ses bras des manches de la parka ... dans la cabane chaude.'::text,'maintenant qu''il était'::text,'même s''il était'::text,'au cas où il était'::text,'Il a sorti ses bras des manches de la parka maintenant qu''il était dans la cabane chaude.'::text),
(388007,43112,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıcak kulübenin içinde ... parkanın kollarından kollarını çıkardı.'::text,'olduğuna göre'::text,'olsa bile'::text,'olur diye'::text,'Sıcak kulübenin içinde olduğuna göre parkanın kollarından kollarını çıkardı.'::text),
(388008,43112,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kihúzta a karját a parka ujjaiból, ... a meleg faházban volt.'::text,'most, hogy'::text,'még ha'::text,'arra az esetre, ha'::text,'Kihúzta a karját a parka ujjaiból, most, hogy a meleg faházban volt.'::text),
(388011,43113,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Subjekt wusste, die Fleece-Ärmel ... das Letzte, was ausgezogen wird.'::text,'wären'::text,'werden sein'::text,'sind'::text,'Das Subjekt wusste, die Fleece-Ärmel wären das Letzte, was ausgezogen wird.'::text),
(388015,43113,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єкт знав, що рукави фліски ... останньою частиною, яку зніматимуть.'::text,'будуть'::text,'будуть'::text,'є'::text,'Суб''єкт знав, що рукави фліски будуть останньою частиною, яку зніматимуть.'::text),
(388014,43113,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto sabía que las mangas del forro polar ... la última parte en quitarse.'::text,'serían'::text,'serán'::text,'son'::text,'El sujeto sabía que las mangas del forro polar serían la última parte en quitarse.'::text),
(388013,43113,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet savait que les manches de la polaire ... la dernière partie à enlever.'::text,'seraient'::text,'seront'::text,'sont'::text,'Le sujet savait que les manches de la polaire seraient la dernière partie à enlever.'::text),
(388016,43113,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek polar kollarının çıkarılacak son parça ... biliyordu.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Denek polar kollarının çıkarılacak son parça olacağını biliyordu.'::text),
(388017,43113,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany tudta, hogy a polár ujjai ... az utolsó rész, ami lekerül.'::text,'lesznek'::text,'lesznek'::text,NULL::text,'Az alany tudta, hogy a polár ujjai lesznek az utolsó rész, ami lekerül.'::text),
(388020,43114,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwie ikonisch, wie du gerade deine Arme aus diesen Ärmeln ...'::text,'ziehst'::text,'ziehst'::text,'gezogen hast'::text,'Irgendwie ikonisch, wie du gerade deine Arme aus diesen Ärmeln ziehst.'::text),
(388024,43114,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи культово, як ти прямо зараз ... руки з тих рукавів.'::text,'висуваєш'::text,'висуваєш'::text,'висунув'::text,'Трохи культово, як ти прямо зараз висуваєш руки з тих рукавів.'::text),
(388023,43114,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un poco icónico cómo ... los brazos de esas mangas ahora mismo.'::text,'estás sacando'::text,'sacas'::text,'has sacado'::text,'Un poco icónico cómo estás sacando los brazos de esas mangas ahora mismo.'::text),
(388022,43114,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un peu iconique, la façon dont tu ... tes bras de ces manches en ce moment.'::text,'sors'::text,'sors'::text,'as sorti'::text,'Un peu iconique, la façon dont tu sors tes bras de ces manches en ce moment.'::text),
(388025,43114,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu an kollarını o kollardan nasıl ... baya ikonik.'::text,'çıkardığın'::text,'çıkardığın'::text,'çıkarmış olduğun'::text,'Şu an kollarını o kollardan nasıl çıkardığın baya ikonik.'::text),
(388026,43114,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elég ikonikus, ahogy most ... a karodat azokból az ujjakból.'::text,'húzod ki'::text,'kihúzod'::text,'kihúztad'::text,'Elég ikonikus, ahogy most húzod ki a karodat azokból az ujjakból.'::text),
(388029,43115,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aus diesen Parka-Ärmeln ..., bevor du überhaupt den Schal angefasst hast. Respekt.'::text,'warst du geschlüpft'::text,'bist du geschlüpft'::text,'schlüpftest du gerade'::text,'Aus diesen Parka-Ärmeln warst du geschlüpft, bevor du überhaupt den Schal angefasst hast. Respekt.'::text),
(388033,43115,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... з тих рукавів парки ще до того, як узагалі торкнувся шарфа. Респект.'::text,'вислизнув'::text,'вислизнув'::text,'вислизав'::text,'Ти вислизнув з тих рукавів парки ще до того, як узагалі торкнувся шарфа. Респект.'::text),
(388032,43115,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de esas mangas de la parka antes de tocar siquiera la bufanda. Respeto.'::text,'Te habías escurrido'::text,'Te has escurrido'::text,'Te estabas escurriendo'::text,'Te habías escurrido de esas mangas de la parka antes de tocar siquiera la bufanda. Respeto.'::text),
(388031,43115,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... de ces manches de parka avant même de toucher l''écharpe. Respect.'::text,'t''étais glissé'::text,'t''es glissé'::text,'te glissais'::text,'Tu t''étais glissé de ces manches de parka avant même de toucher l''écharpe. Respect.'::text),
(388034,43115,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Atkıya dokunmadan önce o parka kollarından ..., saygılar.'::text,'sıyrılmıştın'::text,'sıyrıldın'::text,'sıyrılıyordun'::text,'Atkıya dokunmadan önce o parka kollarından sıyrılmıştın, saygılar.'::text),
(388035,43115,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már ... azokból a parkaujjakból, mielőtt egyáltalán hozzáértél a sálhoz. Respekt.'::text,'kibújtál'::text,'kibújtál'::text,'bújtál ki éppen'::text,'Már kibújtál azokból a parkaujjakból, mielőtt egyáltalán hozzáértél a sálhoz. Respekt.'::text),
(342579,38065,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich lüg nicht, du ... den ganzen Vormittag mit völlig Fremden bei diesem Puzzle. Respekt.'::text,'kooperierst'::text,'hast kooperiert'::text,'kooperiertest'::text,'Ich lüg nicht, du kooperierst den ganzen Vormittag mit völlig Fremden bei diesem Puzzle. Respekt.'::text),
(342583,38065,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, ти весь ранок ... з абсолютно незнайомими людьми над цим пазлом. Респект.'::text,'співпрацюєш'::text,'співпрацював'::text,'співпрацював'::text,'Не брехатиму, ти весь ранок співпрацюєш з абсолютно незнайомими людьми над цим пазлом. Респект.'::text),
(342582,38065,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, ... con completos desconocidos en este puzle toda la mañana. Respeto.'::text,'llevas colaborando'::text,'has colaborado'::text,'colaboraste'::text,'No te voy a mentir, llevas colaborando con completos desconocidos en este puzle toda la mañana. Respeto.'::text),
(342581,38065,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... avec de parfaits inconnus sur ce puzzle toute la matinée. Respect.'::text,'coopères'::text,'as coopéré'::text,'as coopéré'::text,'Je vais pas mentir, tu coopères avec de parfaits inconnus sur ce puzzle toute la matinée. Respect.'::text),
(342584,38065,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bütün sabah bu yapbozda tamamen yabancılarla ..., saygılar.'::text,'iş birliği yapıyorsun'::text,'iş birliği yaptın'::text,'iş birliği yaptın'::text,'Yalan yok, bütün sabah bu yapbozda tamamen yabancılarla iş birliği yapıyorsun, saygılar.'::text),
(342585,38065,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, egész délelőtt teljesen idegenekkel ... ezen a kirakón. Respekt.'::text,'dolgozol együtt'::text,'dolgoztál együtt'::text,'dolgoztál együtt'::text,'Nem hazudok, egész délelőtt teljesen idegenekkel dolgozol együtt ezen a kirakón. Respekt.'::text),
(342588,38066,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis die Schaulustigen ankamen, ... die Gruppe schon an der Hälfte der Karte zusammengearbeitet.'::text,'hatte'::text,'hat'::text,'arbeitet'::text,'Bis die Schaulustigen ankamen, hatte die Gruppe schon an der Hälfte der Karte zusammengearbeitet.'::text),
(342592,38066,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки прийшли глядачі, група вже ... над половиною мапи.'::text,'попрацювала разом'::text,'попрацювала разом'::text,'працює разом'::text,'Поки прийшли глядачі, група вже попрацювала разом над половиною мапи.'::text),
(342591,38066,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegaron los curiosos, el grupo ya ... en la mitad del mapa.'::text,'había colaborado'::text,'ha colaborado'::text,'colabora'::text,'Para cuando llegaron los curiosos, el grupo ya había colaborado en la mitad del mapa.'::text),
(342590,38066,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand les curieux sont arrivés, le groupe ... déjà sur la moitié de la carte.'::text,'avait coopéré'::text,'a coopéré'::text,'coopère'::text,'Quand les curieux sont arrivés, le groupe avait coopéré déjà sur la moitié de la carte.'::text),
(342593,38066,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İzleyiciler geldiğinde grup haritanın yarısında çoktan iş birliği ...'::text,'yapmıştı'::text,'yaptı'::text,'yapıyor'::text,'İzleyiciler geldiğinde grup haritanın yarısında çoktan iş birliği yapmıştı.'::text),
(342594,38066,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a nézelődők megérkeztek, a csoport már ... a térkép felén.'::text,'együtt dolgozott'::text,'együtt dolgozott'::text,'együtt dolgozik'::text,'Mire a nézelődők megérkeztek, a csoport már együtt dolgozott a térkép felén.'::text),
(342597,38067,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie zusammenarbeiten, ... sie die Weltkarte vor dem Mittagessen.'::text,'schaffen'::text,'würden schaffen'::text,'schafften'::text,'Wenn sie zusammenarbeiten, schaffen sie die Weltkarte vor dem Mittagessen.'::text),
(342601,38067,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вони співпрацюватимуть, то ... мапу світу до обіду.'::text,'закінчать'::text,'закінчили б'::text,'закінчили'::text,'Якщо вони співпрацюватимуть, то закінчать мапу світу до обіду.'::text),
(342600,38067,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si cooperan, ... el mapa del mundo antes de comer.'::text,'terminarán'::text,'terminarían'::text,'terminaron'::text,'Si cooperan, terminarán el mapa del mundo antes de comer.'::text),
(342599,38067,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils coopèrent, ils ... la carte du monde avant le déjeuner.'::text,'finiront'::text,'finiraient'::text,'ont fini'::text,'S''ils coopèrent, ils finiront la carte du monde avant le déjeuner.'::text),
(342602,38067,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İş birliği yaparlarsa dünya haritasını öğle yemeğinden önce ...'::text,'bitirecekler'::text,'bitirirlerdi'::text,'bitirdiler'::text,'İş birliği yaparlarsa dünya haritasını öğle yemeğinden önce bitirecekler.'::text),
(342603,38067,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha együttműködnek, ebéd előtt ... a világtérképet.'::text,'befejezik'::text,'befejeznék'::text,'befejezték'::text,'Ha együttműködnek, ebéd előtt befejezik a világtérképet.'::text),
(342606,38068,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Gruppe nicht zusammenarbeiten würde, ... die Teile an die falschen Stellen.'::text,'kämen'::text,'werden kommen'::text,'kamen'::text,'Wenn die Gruppe nicht zusammenarbeiten würde, kämen die Teile an die falschen Stellen.'::text),
(342610,38068,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби група не співпрацювала, деталі ... не на своїх місцях.'::text,'опинилися б'::text,'опиняться'::text,'опинилися'::text,'Якби група не співпрацювала, деталі опинилися б не на своїх місцях.'::text),
(342609,38068,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el grupo no cooperara, las piezas ... en los sitios equivocados.'::text,'acabarían'::text,'acabarán'::text,'acabaron'::text,'Si el grupo no cooperara, las piezas acabarían en los sitios equivocados.'::text),
(342608,38068,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le groupe ne coopérait pas, les pièces ... aux mauvais endroits.'::text,'finiraient'::text,'finiront'::text,'ont fini'::text,'Si le groupe ne coopérait pas, les pièces finiraient aux mauvais endroits.'::text),
(342611,38068,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup iş birliği yapmasaydı, parçalar yanlış yerlere ...'::text,'giderdi'::text,'gidecek'::text,'gitti'::text,'Grup iş birliği yapmasaydı, parçalar yanlış yerlere giderdi.'::text),
(342612,38068,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a csoport nem működne együtt, a darabok rossz helyre ...'::text,'kerülnének'::text,'kerülnek majd'::text,'kerültek'::text,'Ha a csoport nem működne együtt, a darabok rossz helyre kerülnének.'::text),
(342615,38069,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Karte wird typischerweise schneller fertig, wenn die Teile von mehreren kooperierenden Personen ...'::text,'getragen werden'::text,'tragen'::text,'trugen'::text,'Die Karte wird typischerweise schneller fertig, wenn die Teile von mehreren kooperierenden Personen getragen werden.'::text),
(342619,38069,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мапу зазвичай завершують швидше, коли деталі ... кілька людей, які співпрацюють.'::text,'несуть'::text,'несуть'::text,'несли'::text,'Мапу зазвичай завершують швидше, коли деталі несуть кілька людей, які співпрацюють.'::text),
(342618,38069,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente el mapa se completa más rápido cuando las piezas ... por varias personas que cooperan.'::text,'son llevadas'::text,'llevan'::text,'llevaron'::text,'Normalmente el mapa se completa más rápido cuando las piezas son llevadas por varias personas que cooperan.'::text),
(342617,38069,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La carte est généralement terminée plus vite quand les pièces ... par plusieurs personnes qui coopèrent.'::text,'sont portées'::text,'portent'::text,'portaient'::text,'La carte est généralement terminée plus vite quand les pièces sont portées par plusieurs personnes qui coopèrent.'::text),
(342620,38069,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parçalar iş birliği yapan birkaç kişi tarafından ... harita genellikle daha hızlı tamamlanır.'::text,'taşındığında'::text,'taşıdığında'::text,'taşıdığında'::text,'Parçalar iş birliği yapan birkaç kişi tarafından taşındığında harita genellikle daha hızlı tamamlanır.'::text),
(342621,38069,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A térkép jellemzően gyorsabban elkészül, ha a darabokat több együttműködő ember ...'::text,'viszi'::text,'viszi'::text,'vitte'::text,'A térkép jellemzően gyorsabban elkészül, ha a darabokat több együttműködő ember viszi.'::text),
(342624,38070,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein falsches Teil ... die Karte fast, aber alle arbeiteten zusammen und retteten sie!'::text,'zerstörte'::text,'wurde zerstört'::text,'zerstörend'::text,'Ein falsches Teil zerstörte die Karte fast, aber alle arbeiteten zusammen und retteten sie!'::text),
(342628,38070,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одна неправильна деталь мало не ... мапу, але всі об''єдналися й урятували її!'::text,'зруйнувала'::text,'була зруйнована'::text,'руйнуючи'::text,'Одна неправильна деталь мало не зруйнувала мапу, але всі об''єдналися й урятували її!'::text),
(342627,38070,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Una pieza equivocada casi ... el mapa, pero todos cooperaron y lo salvaron!'::text,'destruyó'::text,'fue destruido'::text,'destruyendo'::text,'¡Una pieza equivocada casi destruyó el mapa, pero todos cooperaron y lo salvaron!'::text),
(342626,38070,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une mauvaise pièce a failli ... la carte, mais tout le monde a coopéré et l''a sauvée !'::text,'détruire'::text,'être détruite'::text,'détruisant'::text,'Une mauvaise pièce a failli détruire la carte, mais tout le monde a coopéré et l''a sauvée !'::text),
(342629,38070,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yanlış bir parça haritayı neredeyse ..., ama herkes iş birliği yapıp onu kurtardı!'::text,'mahvediyordu'::text,'mahvedildi'::text,'mahvederek'::text,'Yanlış bir parça haritayı neredeyse mahvediyordu, ama herkes iş birliği yapıp onu kurtardı!'::text),
(342630,38070,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy rossz darab majdnem ... a térképet, de mindenki összefogott és megmentette!'::text,'tönkretette'::text,'tönkre lett téve'::text,'tönkretéve'::text,'Egy rossz darab majdnem tönkretette a térképet, de mindenki összefogott és megmentette!'::text),
(342633,38071,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie arbeiten zusammen wie Champions, also ... sie absolut unaufhaltsam sein!'::text,'müssen'::text,'können nicht'::text,'sollten'::text,'Sie arbeiten zusammen wie Champions, also müssen sie absolut unaufhaltsam sein!'::text),
(342637,38071,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони співпрацюють як чемпіони, тож ... бути абсолютно нестримними!'::text,'мусять'::text,'не можуть'::text,'мають'::text,'Вони співпрацюють як чемпіони, тож мусять бути абсолютно нестримними!'::text),
(342636,38071,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cooperan como campeones, así que ... ser absolutamente imparables!'::text,'deben de'::text,'no pueden'::text,'deberían'::text,'¡Cooperan como campeones, así que deben de ser absolutamente imparables!'::text),
(342635,38071,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils coopèrent comme des champions, donc ils ... être absolument inarrêtables !'::text,'doivent'::text,'ne peuvent pas'::text,'devraient'::text,'Ils coopèrent comme des champions, donc ils doivent être absolument inarrêtables !'::text),
(342638,38071,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şampiyonlar gibi iş birliği yapıyorlar, yani kesinlikle durdurulamaz ...!'::text,'olmalılar'::text,'olamazlar'::text,'olmalılar'::text,'Şampiyonlar gibi iş birliği yapıyorlar, yani kesinlikle durdurulamaz olmalılar!'::text),
(342639,38071,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy dolgoznak együtt, mint a bajnokok, szóval ... teljesen megállíthatatlanok!'::text,'biztosan'::text,'nem lehetnek'::text,'kellene, hogy legyenek'::text,'Úgy dolgoznak együtt, mint a bajnokok, szóval biztosan teljesen megállíthatatlanok!'::text),
(342642,38072,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... Kopftuch rot ist, arbeitete bis zum allerletzten, schicksalhaften Teil mit!'::text,'deren'::text,'die'::text,'was'::text,'Die Frau, deren Kopftuch rot ist, arbeitete bis zum allerletzten, schicksalhaften Teil mit!'::text),
(342646,38072,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... хустка червона, співпрацювала до останньої, фатальної деталі!'::text,'чия'::text,'яка'::text,'що'::text,'Жінка, чия хустка червона, співпрацювала до останньої, фатальної деталі!'::text),
(342645,38072,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La mujer ... pañuelo es rojo cooperó hasta la última y fatídica pieza!'::text,'cuyo'::text,'que'::text,'la cual'::text,'¡La mujer cuyo pañuelo es rojo cooperó hasta la última y fatídica pieza!'::text),
(342644,38072,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... le foulard est rouge a coopéré jusqu''à la toute dernière pièce, fatale !'::text,'dont'::text,'qui'::text,'laquelle'::text,'La femme dont le foulard est rouge a coopéré jusqu''à la toute dernière pièce, fatale !'::text),
(342647,38072,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başörtüsü kırmızı olan ... kadın, kader belirleyen son parçaya kadar iş birliği yaptı!'::text,''::text,NULL::text,NULL::text,'Başörtüsü kırmızı olan kadın, kader belirleyen son parçaya kadar iş birliği yaptı!'::text),
(342648,38072,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... kendője piros, az utolsó, végzetes darabig együttműködött!'::text,'akinek a'::text,'aki'::text,'ami'::text,'A nő, akinek a kendője piros, az utolsó, végzetes darabig együttműködött!'::text),
(342660,38074,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ... sie in der Schule total schlecht im Zusammenarbeiten.'::text,'waren früher'::text,'waren immer'::text,'waren es gewohnt'::text,'Bestie, anscheinend waren früher sie in der Schule total schlecht im Zusammenarbeiten.'::text),
(342664,38074,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сонечко, кажуть, у школі вони ... жахливими в командній роботі.'::text,'раніше були'::text,'були б'::text,'звикли бути'::text,'Сонечко, кажуть, у школі вони раніше були жахливими в командній роботі.'::text),
(342663,38074,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer en el colegio ... fatal trabajando en equipo.'::text,'solían ser'::text,'eran'::text,'estaban acostumbrados a ser'::text,'Amiga, al parecer en el colegio solían ser fatal trabajando en equipo.'::text),
(342662,38074,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment à l''école ils ... nuls pour coopérer.'::text,'étaient'::text,'étaient'::text,'avaient l''habitude d''être'::text,'Ma belle, apparemment à l''école ils étaient nuls pour coopérer.'::text),
(342665,38074,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, anlaşılan okulda iş birliği konusunda berbat ...'::text,'olurlarmış'::text,'olurlarmış'::text,'olmaya alışkınmış'::text,'Kanka, anlaşılan okulda iş birliği konusunda berbat olurlarmış.'::text),
(342666,38074,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a suliban ... rettentő rosszak az együttműködésben.'::text,'régen voltak'::text,'voltak'::text,'hozzá voltak szokva, hogy legyenek'::text,'Csajszi, állítólag a suliban régen voltak rettentő rosszak az együttműködésben.'::text),
(342669,38075,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Krass, der Typ in Grün hat sich zuerst geweigert, ..., dann hat er die halbe Karte getragen, hab ich gehört.'::text,'mitzumachen'::text,'mitmachend'::text,'mitmachen'::text,'Krass, der Typ in Grün hat sich zuerst geweigert, mitzumachen, dann hat er die halbe Karte getragen, hab ich gehört.'::text),
(342673,38075,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ну, хлопець у зеленому спочатку відмовився ..., а потім поніс пів мапи, я чула.'::text,'співпрацювати'::text,'співпраця'::text,'співпрацюй'::text,'Та ну, хлопець у зеленому спочатку відмовився співпрацювати, а потім поніс пів мапи, я чула.'::text),
(342672,38075,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No puede ser, el chico de verde al principio se negó a ..., luego cargó con medio mapa, me han dicho.'::text,'colaborar'::text,'colaborando'::text,'colabora'::text,'No puede ser, el chico de verde al principio se negó a colaborar, luego cargó con medio mapa, me han dicho.'::text),
(342671,38075,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pas possible, le mec en vert a d''abord refusé de ..., puis il a porté la moitié de la carte, à ce qu''on m''a dit.'::text,'coopérer'::text,'coopérant'::text,'coopère'::text,'Pas possible, le mec en vert a d''abord refusé de coopérer, puis il a porté la moitié de la carte, à ce qu''on m''a dit.'::text),
(342674,38075,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olamaz, yeşilli çocuk önce ... reddetmiş, sonra haritanın yarısını taşımış, öyle duydum.'::text,'iş birliği yapmayı'::text,'iş birliği yaparak'::text,'iş birliği yap'::text,'Olamaz, yeşilli çocuk önce iş birliği yapmayı reddetmiş, sonra haritanın yarısını taşımış, öyle duydum.'::text),
(342675,38075,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne már, a zöld ruhás srác először nem volt hajlandó ..., aztán a fél térképet ő vitte, azt hallottam.'::text,'együttműködni'::text,'együttműködve'::text,'együttműködik'::text,'Ne már, a zöld ruhás srác először nem volt hajlandó együttműködni, aztán a fél térképet ő vitte, azt hallottam.'::text),
(369228,41026,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich bin sicher, dass die Hügel morgen früh wieder neblig ...'::text,'sein werden'::text,'sein werden'::text,'sind'::text,'Ich bin sicher, dass die Hügel morgen früh wieder neblig sein werden.'::text),
(369232,41026,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я впевнений, що завтра вранці пагорби знову ... туманними.'::text,'будуть'::text,'будуть'::text,'є'::text,'Я впевнений, що завтра вранці пагорби знову будуть туманними.'::text),
(369231,41026,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estoy seguro de que las colinas ... brumosas otra vez mañana por la mañana.'::text,'estarán'::text,'estarán'::text,'están'::text,'Estoy seguro de que las colinas estarán brumosas otra vez mañana por la mañana.'::text),
(369230,41026,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je suis sûr que les collines ... brumeuses à nouveau demain matin.'::text,'seront'::text,'seront'::text,'sont'::text,'Je suis sûr que les collines seront brumeuses à nouveau demain matin.'::text),
(369233,41026,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eminim, tepeler yarın sabah yine sisli ...'::text,'olacak'::text,'olacak'::text,NULL::text,'Eminim, tepeler yarın sabah yine sisli olacak.'::text),
(369234,41026,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biztos vagyok benne, hogy holnap reggel megint ködösek ... a dombok.'::text,'lesznek'::text,'lesznek'::text,NULL::text,'Biztos vagyok benne, hogy holnap reggel megint ködösek lesznek a dombok.'::text),
(369237,41027,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn tiefe Wolken die Hügel ..., sieht das Tal neblig aus.'::text,'bedecken'::text,'bedecken werden'::text,'bedeckten'::text,'Wenn tiefe Wolken die Hügel bedecken, sieht das Tal neblig aus.'::text),
(369241,41027,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли низькі хмари ... пагорби, долина виглядає туманною.'::text,'вкривають'::text,'вкриють'::text,'вкрили'::text,'Коли низькі хмари вкривають пагорби, долина виглядає туманною.'::text),
(369240,41027,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando las nubes bajas ... las colinas, el valle parece brumoso.'::text,'cubren'::text,'cubrirán'::text,'cubrieron'::text,'Cuando las nubes bajas cubren las colinas, el valle parece brumoso.'::text),
(369239,41027,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand les nuages bas ... les collines, la vallée paraît brumeuse.'::text,'couvrent'::text,'couvriront'::text,'couvraient'::text,'Quand les nuages bas couvrent les collines, la vallée paraît brumeuse.'::text),
(369242,41027,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alçak bulutlar tepeleri ..., vadi sisli görünür.'::text,'kapladığında'::text,'kaplayacağında'::text,'kapladığında'::text,'Alçak bulutlar tepeleri kapladığında, vadi sisli görünür.'::text),
(369243,41027,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor alacsony felhők ... a dombokat, a völgy ködösnek tűnik.'::text,'takarják'::text,'takarják majd'::text,'takarták'::text,'Amikor alacsony felhők takarják a dombokat, a völgy ködösnek tűnik.'::text),
(369246,41028,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn ich dein Selbstbewusstsein hätte, ... ich auch im Regen über diesen nebligen Grat.'::text,'ginge'::text,'werde gehen'::text,'gehe'::text,'Ehrlich, wenn ich dein Selbstbewusstsein hätte, ginge ich auch im Regen über diesen nebligen Grat.'::text),
(369250,41028,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби я мав твою впевненість, я теж ... тим туманним хребтом під дощем.'::text,'пішов би'::text,'піду'::text,'іду'::text,'Чесно, якби я мав твою впевненість, я теж пішов би тим туманним хребтом під дощем.'::text),
(369249,41028,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si tuviera tu seguridad, yo también ... por esa cresta brumosa bajo la lluvia.'::text,'caminaría'::text,'caminaré'::text,'camino'::text,'Sinceramente, si tuviera tu seguridad, yo también caminaría por esa cresta brumosa bajo la lluvia.'::text),
(369248,41028,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si j''avais ta confiance, moi aussi je ... sur cette crête brumeuse sous la pluie.'::text,'marcherais'::text,'marcherai'::text,'marche'::text,'Franchement, si j''avais ta confiance, moi aussi je marcherais sur cette crête brumeuse sous la pluie.'::text),
(369251,41028,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, senin özgüvenin bende olsa, ben de yağmurda o sisli sırtta ...'::text,'yürürdüm'::text,'yürüyeceğim'::text,'yürürüm'::text,'Açıkçası, senin özgüvenin bende olsa, ben de yağmurda o sisli sırtta yürürdüm.'::text),
(369252,41028,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha nekem is ilyen önbizalmam lenne, én is ... azon a ködös gerincen az esőben.'::text,'végigmennék'::text,'végigmegyek majd'::text,'végigmegyek'::text,'Őszintén, ha nekem is ilyen önbizalmam lenne, én is végigmennék azon a ködös gerincen az esőben.'::text),
(369255,41029,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... das neblige Tal von tief hängenden grauen Wolken bedeckt.'::text,'war'::text,'bedeckte'::text,'ist'::text,'Gestern war das neblige Tal von tief hängenden grauen Wolken bedeckt.'::text),
(369259,41029,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора туманна долина ... низькими сірими хмарами.'::text,'була вкрита'::text,'вкрила'::text,'вкрита'::text,'Учора туманна долина була вкрита низькими сірими хмарами.'::text),
(369258,41029,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer el valle brumoso ... por nubes grises y bajas.'::text,'estaba cubierto'::text,'cubrió'::text,'está cubierto'::text,'Ayer el valle brumoso estaba cubierto por nubes grises y bajas.'::text),
(369257,41029,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, la vallée brumeuse ... par des nuages gris et bas.'::text,'était couverte'::text,'a couvert'::text,'est couverte'::text,'Hier, la vallée brumeuse était couverte par des nuages gris et bas.'::text),
(369260,41029,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün sisli vadi alçak gri bulutlarla ...'::text,'kaplandı'::text,'kapladı'::text,'kaplı'::text,'Dün sisli vadi alçak gri bulutlarla kaplandı.'::text),
(369261,41029,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a ködös völgyet alacsony szürke felhők ...'::text,'borították'::text,'borította'::text,'borítják'::text,'Tegnap a ködös völgyet alacsony szürke felhők borították.'::text),
(369264,41030,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perfekte Aussicht, offensichtlich: Die neblige Wolke ... den ganzen See.'::text,'verbarg'::text,'wurde verborgen'::text,'verbergend'::text,'Perfekte Aussicht, offensichtlich: Die neblige Wolke verbarg den ganzen See.'::text),
(369268,41030,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ідеальні краєвиди, звісно: туманна хмара ... все озеро.'::text,'сховала'::text,'була схована'::text,'ховаючи'::text,'Ідеальні краєвиди, звісно: туманна хмара сховала все озеро.'::text),
(369267,41030,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vistas perfectas, obviamente: la nube brumosa ... todo el lago.'::text,'ocultó'::text,'fue ocultada'::text,'ocultando'::text,'Vistas perfectas, obviamente: la nube brumosa ocultó todo el lago.'::text),
(369266,41030,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une vue parfaite, évidemment : le nuage brumeux ... tout le lac.'::text,'a caché'::text,'a été caché'::text,'cachant'::text,'Une vue parfaite, évidemment : le nuage brumeux a caché tout le lac.'::text),
(369269,41030,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mükemmel manzara tabii: sisli bulut bütün gölü ...'::text,'sakladı'::text,'saklandı'::text,'saklayarak'::text,'Mükemmel manzara tabii: sisli bulut bütün gölü sakladı.'::text),
(369270,41030,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tökéletes kilátás, nyilván: a ködös felhő ... az egész tavat.'::text,'eltakarta'::text,'el lett takarva'::text,'eltakarva'::text,'Tökéletes kilátás, nyilván: a ködös felhő eltakarta az egész tavat.'::text),
(369273,41031,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da oben ... es leicht neblig sein; sie sieht nicht, wo die Hügel enden.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Da oben muss es leicht neblig sein; sie sieht nicht, wo die Hügel enden.'::text),
(369277,41031,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Там нагорі ... бути трохи туманно; вона не бачить, де закінчуються пагорби.'::text,'мусить'::text,'може'::text,'не може'::text,'Там нагорі мусить бути трохи туманно; вона не бачить, де закінчуються пагорби.'::text),
(369276,41031,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahí arriba ... estar un pelín brumoso; no ve dónde terminan las colinas.'::text,'debe de'::text,'podría'::text,'no puede'::text,'Ahí arriba debe de estar un pelín brumoso; no ve dónde terminan las colinas.'::text),
(369275,41031,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Là-haut, il ... faire légèrement brumeux ; elle ne voit pas où finissent les collines.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Là-haut, il doit faire légèrement brumeux ; elle ne voit pas où finissent les collines.'::text),
(369278,41031,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yukarısı biraz sisli ...; tepelerin nerede bittiğini göremiyor.'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'Yukarısı biraz sisli olmalı; tepelerin nerede bittiğini göremiyor.'::text),
(369279,41031,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Odafent ... egy kicsit ködös az idő; nem látja, hol érnek véget a dombok.'::text,'biztosan'::text,'talán'::text,'nem lehet, hogy'::text,'Odafent biztosan egy kicsit ködös az idő; nem látja, hol érnek véget a dombok.'::text),
(369282,41032,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der neblige Hügel, ... sie ausgewählt hat, war eindeutig der beste Aussichtspunkt im Land.'::text,'den'::text,'wer'::text,'dessen'::text,'Der neblige Hügel, den sie ausgewählt hat, war eindeutig der beste Aussichtspunkt im Land.'::text),
(369286,41032,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Туманний пагорб, ... вона обрала, був явно найкращою оглядовою точкою в країні.'::text,'який'::text,'хто'::text,'чий'::text,'Туманний пагорб, який вона обрала, був явно найкращою оглядовою точкою в країні.'::text),
(369285,41032,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La colina brumosa ... eligió era claramente el mejor mirador del país.'::text,'que'::text,'quien'::text,'cuya'::text,'La colina brumosa que eligió era claramente el mejor mirador del país.'::text),
(369284,41032,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La colline brumeuse ... a choisie était clairement le meilleur point de vue du pays.'::text,'qu''elle'::text,'qui'::text,'dont elle'::text,'La colline brumeuse qu''elle a choisie était clairement le meilleur point de vue du pays.'::text),
(369287,41032,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seçtiği ... sisli tepe, belli ki ülkenin en iyi manzara noktasıydı.'::text,''::text,NULL::text,NULL::text,'Seçtiği sisli tepe, belli ki ülkenin en iyi manzara noktasıydı.'::text),
(369288,41032,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ködös domb, ... kiválasztott, nyilvánvalóan az ország legjobb kilátópontja volt.'::text,'amelyet'::text,'aki'::text,'amelynek'::text,'A ködös domb, amelyet kiválasztott, nyilvánvalóan az ország legjobb kilátópontja volt.'::text),
(369291,41033,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schrie, dass die nebligen Hügel ihre ganze Aussicht für immer ...!'::text,'ruiniert hätten'::text,'ruiniert haben'::text,'ruinieren'::text,'Sie schrie, dass die nebligen Hügel ihre ganze Aussicht für immer ruiniert hätten!'::text),
(369295,41033,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона кричала, що туманні пагорби ... їй увесь краєвид назавжди!'::text,'зіпсували'::text,'зіпсували'::text,'псують'::text,'Вона кричала, що туманні пагорби зіпсували їй увесь краєвид назавжди!'::text),
(369294,41033,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Gritó que las colinas brumosas le ... toda la vista para siempre!'::text,'habían arruinado'::text,'han arruinado'::text,'arruinan'::text,'¡Gritó que las colinas brumosas le habían arruinado toda la vista para siempre!'::text),
(369293,41033,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a hurlé que les collines brumeuses ... toute sa vue pour toujours !'::text,'avaient gâché'::text,'ont gâché'::text,'gâchent'::text,'Elle a hurlé que les collines brumeuses avaient gâché toute sa vue pour toujours !'::text),
(369296,41033,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sisli tepeler bütün manzarasını sonsuza dek ... diye bağırdı!'::text,'mahvetmiş'::text,'mahvetti'::text,'mahvediyor'::text,'Sisli tepeler bütün manzarasını sonsuza dek mahvetmiş diye bağırdı!'::text),
(369297,41033,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kiabálta, hogy a ködös dombok örökre ... az egész kilátását!'::text,'tönkretették'::text,'tönkretették'::text,'tönkreteszik'::text,'Azt kiabálta, hogy a ködös dombok örökre tönkretették az egész kilátását!'::text),
(369309,41035,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, sie hat mir erzählt, dass ihr das ... über diesen nebligen Grat im Regen richtig gefallen hat.'::text,'Laufen'::text,'zu laufen'::text,'laufe'::text,'Mädel, sie hat mir erzählt, dass ihr das Laufen über diesen nebligen Grat im Regen richtig gefallen hat.'::text),
(369313,41035,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що їй дуже сподобалося ... тим туманним хребтом під дощем.'::text,'гуляти'::text,'гуляти'::text,'гуляє'::text,'Подруго, вона сказала мені, що їй дуже сподобалося гуляти тим туманним хребтом під дощем.'::text),
(369312,41035,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que disfrutó mucho ... por esa cresta brumosa bajo la lluvia.'::text,'caminando'::text,'caminar'::text,'camina'::text,'Tía, me dijo que disfrutó mucho caminando por esa cresta brumosa bajo la lluvia.'::text),
(369311,41035,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle m''a dit qu''elle avait vraiment adoré ... sur cette crête brumeuse sous la pluie.'::text,'marcher'::text,'marcher'::text,'marche'::text,'Meuf, elle m''a dit qu''elle avait vraiment adoré marcher sur cette crête brumeuse sous la pluie.'::text),
(369314,41035,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana o sisli sırtta yağmurda ... çok keyif aldığını söyledi.'::text,'yürümekten'::text,'yürümekten'::text,'yürü'::text,'Kızım, bana o sisli sırtta yağmurda yürümekten çok keyif aldığını söyledi.'::text),
(369315,41035,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy nagyon élvezte ... azon a ködös gerincen az esőben.'::text,'a sétát'::text,'sétálni'::text,'sétál'::text,'Csajszi, azt mondta, hogy nagyon élvezte a sétát azon a ködös gerincen az esőben.'::text),
(369318,41036,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hügel sind heute sehr neblig, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Die Hügel sind heute sehr neblig, oder?'::text),
(369322,41036,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пагорби сьогодні дуже туманні, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Пагорби сьогодні дуже туманні, правда?'::text),
(369321,41036,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las colinas están muy brumosas hoy, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Las colinas están muy brumosas hoy, ¿verdad?'::text),
(369320,41036,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les collines sont très brumeuses aujourd''hui, ... ?'::text,'hein'::text,'hein'::text,'hein'::text,'Les collines sont très brumeuses aujourd''hui, hein ?'::text),
(369323,41036,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tepeler bugün çok sisli, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Tepeler bugün çok sisli, değil mi?'::text),
(369324,41036,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon ködösek ma a dombok, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Nagyon ködösek ma a dombok, ugye?'::text),
(334515,37169,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... unter den riesigen Werbetafeln, als sein Handy ausging. Perfektes Timing, offensichtlich.'::text,'drehte sich gerade'::text,'drehte sich'::text,'hat sich gedreht'::text,'Er drehte sich gerade unter den riesigen Werbetafeln, als sein Handy ausging. Perfektes Timing, offensichtlich.'::text),
(334519,37169,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... під велетенськими білбордами, коли в нього сів телефон. Ідеальний таймінг, очевидно.'::text,'крутився'::text,'крутнувся'::text,'крутнувся'::text,'Він крутився під велетенськими білбордами, коли в нього сів телефон. Ідеальний таймінг, очевидно.'::text),
(334518,37169,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... bajo las vallas publicitarias gigantes cuando se le murió el móvil. Momento perfecto, obviamente.'::text,'Estaba girando'::text,'Giró'::text,'Ha girado'::text,'Estaba girando bajo las vallas publicitarias gigantes cuando se le murió el móvil. Momento perfecto, obviamente.'::text),
(334517,37169,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sous les panneaux publicitaires géants quand son téléphone s''est éteint. Timing parfait, évidemment.'::text,'tournoyait'::text,'a tournoyé'::text,'a tournoyé'::text,'Il tournoyait sous les panneaux publicitaires géants quand son téléphone s''est éteint. Timing parfait, évidemment.'::text),
(334520,37169,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Telefonu kapandığında dev reklam panolarının altında ..., mükemmel zamanlama tabii.'::text,'dönüyordu'::text,'döndü'::text,'döndü'::text,'Telefonu kapandığında dev reklam panolarının altında dönüyordu, mükemmel zamanlama tabii.'::text),
(334521,37169,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... az óriásplakátok alatt, amikor lemerült a telefonja. Tökéletes időzítés, nyilván.'::text,'Épp pörgött'::text,'Megpördült'::text,'Megpördült'::text,'Épp pörgött az óriásplakátok alatt, amikor lemerült a telefonja. Tökéletes időzítés, nyilván.'::text),
(334524,37170,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit zehn Minuten auf dieselbe Werbetafel. Eindeutig ein viel beschäftigter Mann.'::text,'starrt'::text,'starrt gerade'::text,'starrt'::text,'Er starrt seit zehn Minuten auf dieselbe Werbetafel. Eindeutig ein viel beschäftigter Mann.'::text),
(334528,37170,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже десять хвилин ... на той самий білборд. Явно зайнята людина.'::text,'витріщається'::text,'витріщається'::text,'витріщається'::text,'Він уже десять хвилин витріщається на той самий білборд. Явно зайнята людина.'::text),
(334527,37170,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la misma valla publicitaria desde hace diez minutos. Un hombre muy ocupado, está claro.'::text,'Lleva mirando'::text,'Está mirando'::text,'Mira'::text,'Lleva mirando la misma valla publicitaria desde hace diez minutos. Un hombre muy ocupado, está claro.'::text),
(334526,37170,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ça fait dix minutes qu''il ... le même panneau. Clairement un homme occupé.'::text,'fixe'::text,'est en train de fixer'::text,'fixe'::text,'Ça fait dix minutes qu''il fixe le même panneau. Clairement un homme occupé.'::text),
(334529,37170,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dakikadır aynı reklam panosuna ..., belli ki çok meşgul bir adam.'::text,'bakıyor'::text,'bakıyor'::text,'bakar'::text,'On dakikadır aynı reklam panosuna bakıyor, belli ki çok meşgul bir adam.'::text),
(334530,37170,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már tíz perce ... ugyanazt az óriásplakátot. Nyilván nagyon elfoglalt ember.'::text,'bámulja'::text,'bámulja éppen'::text,'bámulja'::text,'Már tíz perce bámulja ugyanazt az óriásplakátot. Nyilván nagyon elfoglalt ember.'::text),
(334533,37171,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Werbetafeln ..., als er stehen blieb, um nach oben zu schauen. Sehr dezent, offensichtlich.'::text,'blinkten'::text,'blinkten auf'::text,'haben geblinkt'::text,'Die Werbetafeln blinkten, als er stehen blieb, um nach oben zu schauen. Sehr dezent, offensichtlich.'::text),
(334537,37171,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Білборди ..., коли він зупинився подивитися вгору. Дуже ненав''язливо, очевидно.'::text,'блимали'::text,'блимнули'::text,'блимнули'::text,'Білборди блимали, коли він зупинився подивитися вгору. Дуже ненав''язливо, очевидно.'::text),
(334536,37171,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las vallas publicitarias ... cuando se paró a mirar hacia arriba. Muy discreto, obviamente.'::text,'estaban parpadeando'::text,'parpadearon'::text,'han parpadeado'::text,'Las vallas publicitarias estaban parpadeando cuando se paró a mirar hacia arriba. Muy discreto, obviamente.'::text),
(334535,37171,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les panneaux publicitaires ... quand il s''est arrêté pour lever les yeux. Très discret, évidemment.'::text,'clignotaient'::text,'ont clignoté'::text,'ont clignoté'::text,'Les panneaux publicitaires clignotaient quand il s''est arrêté pour lever les yeux. Très discret, évidemment.'::text),
(334538,37171,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yukarı bakmak için durduğunda reklam panoları ..., çok belli etmeden tabii.'::text,'yanıp sönüyordu'::text,'yanıp söndü'::text,'yanıp söndü'::text,'Yukarı bakmak için durduğunda reklam panoları yanıp sönüyordu, çok belli etmeden tabii.'::text),
(334539,37171,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az óriásplakátok ..., amikor megállt, hogy felnézzen. Nagyon visszafogott, nyilván.'::text,'villogtak'::text,'felvillantak'::text,'felvillantak'::text,'Az óriásplakátok villogtak, amikor megállt, hogy felnézzen. Nagyon visszafogott, nyilván.'::text),
(334542,37172,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'200 Werbetafeln ..., und sein Handy ist komplett voll!'::text,'hat er schon fotografiert'::text,'fotografiert er seit einer Weile'::text,'fotografierte er'::text,'200 Werbetafeln hat er schon fotografiert, und sein Handy ist komplett voll!'::text),
(334546,37172,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже ... 200 білбордів, і його телефон повністю забитий!'::text,'сфотографував'::text,'фотографує'::text,'сфотографував'::text,'Він уже сфотографував 200 білбордів, і його телефон повністю забитий!'::text),
(334545,37172,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ya ... 200 vallas publicitarias y tiene el móvil completamente lleno!'::text,'ha fotografiado'::text,'ha estado fotografiando'::text,'fotografió'::text,'¡Ya ha fotografiado 200 vallas publicitarias y tiene el móvil completamente lleno!'::text),
(334544,37172,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... déjà 200 panneaux publicitaires, et son téléphone est complètement plein !'::text,'a photographié'::text,'est en train de photographier'::text,'photographia'::text,'Il a photographié déjà 200 panneaux publicitaires, et son téléphone est complètement plein !'::text),
(334547,37172,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiden 200 reklam panosunun fotoğrafını ... ve telefonu tamamen doldu!'::text,'çekti'::text,'çekip duruyor'::text,'çekti'::text,'Şimdiden 200 reklam panosunun fotoğrafını çekti ve telefonu tamamen doldu!'::text),
(334548,37172,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már 200 óriásplakátot ..., és teljesen megtelt a telefonja!'::text,'lefotózott'::text,'fotózgat'::text,'lefotózott'::text,'Már 200 óriásplakátot lefotózott, és teljesen megtelt a telefonja!'::text),
(334560,37174,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, man sagt, morgen um diese Zeit ... allen Fotos von dieser Werbetafel.'::text,'schickt er gerade'::text,'wird er schicken'::text,'schickt er'::text,'Bestie, man sagt, morgen um diese Zeit schickt er gerade allen Fotos von dieser Werbetafel.'::text),
(334564,37174,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сонечко, кажуть, завтра о цій порі він ... фото того білборда всім.'::text,'розсилатиме'::text,'надішле'::text,'надсилає'::text,'Сонечко, кажуть, завтра о цій порі він розсилатиме фото того білборда всім.'::text),
(334563,37174,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, dicen que mañana a esta hora ... fotos de esa valla a todo el mundo.'::text,'estará enviando'::text,'enviará'::text,'envía'::text,'Amiga, dicen que mañana a esta hora estará enviando fotos de esa valla a todo el mundo.'::text),
(334562,37174,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît que demain à la même heure il ... des photos de ce panneau à tout le monde.'::text,'sera en train d''envoyer'::text,'enverra'::text,'envoie'::text,'Ma belle, il paraît que demain à la même heure il sera en train d''envoyer des photos de ce panneau à tout le monde.'::text),
(334565,37174,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dediklerine göre yarın bu saatlerde o reklam panosunun fotoğraflarını herkese ...'::text,'gönderiyor olacakmış'::text,'gönderecekmiş'::text,'gönderiyormuş'::text,'Kanka, dediklerine göre yarın bu saatlerde o reklam panosunun fotoğraflarını herkese gönderiyor olacakmış.'::text),
(334566,37174,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt beszélik, hogy holnap ilyenkor ... mindenkinek a fotókat arról az óriásplakátról.'::text,'épp küldözgeti majd'::text,'elküldi'::text,'küldi'::text,'Csajszi, azt beszélik, hogy holnap ilyenkor épp küldözgeti majd mindenkinek a fotókat arról az óriásplakátról.'::text),
(334569,37175,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, er schwört, dass er sich eines Tages eine eigene Werbetafel ...'::text,'kaufen wird'::text,'gerade kaufen wird'::text,'kauft'::text,'Hör mal, er schwört, dass er sich eines Tages eine eigene Werbetafel kaufen wird.'::text),
(334573,37175,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він клянеться, що колись ... собі власний білборд.'::text,'купить'::text,'купуватиме'::text,'купує'::text,'Слухай, він клянеться, що колись купить собі власний білборд.'::text),
(334572,37175,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, jura que algún día ... su propia valla publicitaria.'::text,'comprará'::text,'estará comprando'::text,'está comprando'::text,'Oye, jura que algún día comprará su propia valla publicitaria.'::text),
(334571,37175,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il jure qu''un jour il ... son propre panneau publicitaire.'::text,'achètera'::text,'sera en train d''acheter'::text,'achète'::text,'Écoute, il jure qu''un jour il achètera son propre panneau publicitaire.'::text),
(334574,37175,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bir gün kendi reklam panosunu ... yemin ediyor.'::text,'alacağına'::text,'alıyor olacağına'::text,'aldığına'::text,'Dinle, bir gün kendi reklam panosunu alacağına yemin ediyor.'::text),
(334575,37175,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, esküszik, hogy egyszer ... egy saját óriásplakátot.'::text,'vesz'::text,'fog venni'::text,'éppen vesz'::text,'Figyelj, esküszik, hogy egyszer vesz egy saját óriásplakátot.'::text),
(334578,37176,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn du nachts unter diesen Werbetafeln stehst, ... dein Gesicht pink, echt.'::text,'wird'::text,'wurde'::text,'wird werden'::text,'Bro, wenn du nachts unter diesen Werbetafeln stehst, wird dein Gesicht pink, echt.'::text),
(334582,37176,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо стоїш уночі під тими білбордами, твоє обличчя ... рожевим, реально.'::text,'стає'::text,'стало'::text,'стане'::text,'Бро, якщо стоїш уночі під тими білбордами, твоє обличчя стає рожевим, реально.'::text),
(334581,37176,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si te pones debajo de esas vallas por la noche, la cara se te ... rosa, en serio.'::text,'pone'::text,'puso'::text,'pondrá'::text,'Tío, si te pones debajo de esas vallas por la noche, la cara se te pone rosa, en serio.'::text),
(334580,37176,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si tu te mets sous ces panneaux la nuit, ton visage ... rose, sérieux.'::text,'devient'::text,'est devenu'::text,'deviendra'::text,'Frérot, si tu te mets sous ces panneaux la nuit, ton visage devient rose, sérieux.'::text),
(334583,37176,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, gece o reklam panolarının altında durursan yüzün pembe ..., cidden.'::text,'olur'::text,'oldu'::text,'olacak'::text,'Kanka, gece o reklam panolarının altında durursan yüzün pembe olur, cidden.'::text),
(334584,37176,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha éjjel azok alatt az óriásplakátok alatt állsz, rózsaszín ... az arcod, komolyan.'::text,'lesz'::text,'lett'::text,'lesz majd'::text,'Tesó, ha éjjel azok alatt az óriásplakátok alatt állsz, rózsaszín lesz az arcod, komolyan.'::text),
(334587,37177,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er sich die Werbetafeln noch länger ansieht, ... er die Fähre.'::text,'verpasst'::text,'würde verpassen'::text,'verpasste'::text,'Wenn er sich die Werbetafeln noch länger ansieht, verpasst er die Fähre.'::text),
(334591,37177,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він ще довше дивитиметься на білборди, то ... пором.'::text,'пропустить'::text,'пропустив би'::text,'пропустив'::text,'Якщо він ще довше дивитиметься на білборди, то пропустить пором.'::text),
(334590,37177,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sigue mirando las vallas publicitarias, ... el ferri.'::text,'perderá'::text,'perdería'::text,'perdió'::text,'Si sigue mirando las vallas publicitarias, perderá el ferri.'::text),
(334589,37177,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il regarde les panneaux publicitaires plus longtemps, il ... le ferry.'::text,'ratera'::text,'raterait'::text,'a raté'::text,'S''il regarde les panneaux publicitaires plus longtemps, il ratera le ferry.'::text),
(334592,37177,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reklam panolarına daha fazla bakarsa feribotu ...'::text,'kaçıracak'::text,'kaçırırdı'::text,'kaçırdı'::text,'Reklam panolarına daha fazla bakarsa feribotu kaçıracak.'::text),
(334593,37177,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még tovább bámulja az óriásplakátokat, ... a kompot.'::text,'lekési'::text,'lekésné'::text,'lekéste'::text,'Ha még tovább bámulja az óriásplakátokat, lekési a kompot.'::text),
(334596,37178,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In diesem Moment ... er sich mit ausgebreiteten Armen unter den Werbetafeln im Kreis.'::text,'dreht'::text,'dreht'::text,'hat gedreht'::text,'In diesem Moment dreht er sich mit ausgebreiteten Armen unter den Werbetafeln im Kreis.'::text),
(334600,37178,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз він ... колами під білбордами з розкинутими руками.'::text,'крутиться'::text,'крутиться'::text,'покрутився'::text,'Саме зараз він крутиться колами під білбордами з розкинутими руками.'::text),
(334599,37178,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento ... en círculos bajo las vallas publicitarias con los brazos abiertos.'::text,'está girando'::text,'gira'::text,'ha girado'::text,'En este momento está girando en círculos bajo las vallas publicitarias con los brazos abiertos.'::text),
(334598,37178,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, il ... sous les panneaux publicitaires, les bras écartés.'::text,'tourne sur lui-même'::text,'tourne sur lui-même'::text,'a tourné sur lui-même'::text,'En ce moment, il tourne sur lui-même sous les panneaux publicitaires, les bras écartés.'::text),
(334601,37178,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda reklam panolarının altında kollarını açmış, kendi etrafında ...'::text,'dönüyor'::text,'döner'::text,'döndü'::text,'Şu anda reklam panolarının altında kollarını açmış, kendi etrafında dönüyor.'::text),
(334602,37178,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a pillanatban ... körbe az óriásplakátok alatt, kitárt karokkal.'::text,'forog'::text,'forog'::text,'forgott'::text,'Ebben a pillanatban forog körbe az óriásplakátok alatt, kitárt karokkal.'::text),
(348591,38733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Tür noch schwerer wäre, ... durch den Eingang. Klar, ein schneller Auftritt.'::text,'käme sie nie'::text,'wird sie nie kommen'::text,'kam sie nie'::text,'Wenn die Tür noch schwerer wäre, käme sie nie durch den Eingang. Klar, ein schneller Auftritt.'::text),
(348595,38733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби двері були ще важчими, вона ... через прохід. Явно стрімка поява.'::text,'ніколи б не пройшла'::text,'ніколи не пройде'::text,'ніколи не пройшла'::text,'Якби двері були ще важчими, вона ніколи б не пройшла через прохід. Явно стрімка поява.'::text),
(348594,38733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la puerta pesara un poco más, ... por la entrada. Una entrada rápida, está claro.'::text,'nunca pasaría'::text,'nunca pasará'::text,'nunca pasó'::text,'Si la puerta pesara un poco más, nunca pasaría por la entrada. Una entrada rápida, está claro.'::text),
(348593,38733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la porte était encore plus lourde, elle ... l''embrasure. Clairement une entrée rapide.'::text,'ne franchirait jamais'::text,'ne franchira jamais'::text,'n''a jamais franchi'::text,'Si la porte était encore plus lourde, elle ne franchirait jamais l''embrasure. Clairement une entrée rapide.'::text),
(348596,38733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapı biraz daha ağır olsaydı, kapı aralığından asla ..., belli ki hızlı bir giriş.'::text,'geçemezdi'::text,'geçemeyecek'::text,'geçemedi'::text,'Kapı biraz daha ağır olsaydı, kapı aralığından asla geçemezdi, belli ki hızlı bir giriş.'::text),
