(348600,38734,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Eingang ... von einem Eisenriegel und einem Vorhängeschloss blockiert. Ein totaler Albtraum!'::text,'war'::text,'blockierte'::text,'blockiert'::text,'Der Eingang war von einem Eisenriegel und einem Vorhängeschloss blockiert. Ein totaler Albtraum!'::text),
(348604,38734,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прохід ... залізним засувом і навісним замком. Суцільне жахіття!'::text,'був заблокований'::text,'заблокував'::text,'блокує'::text,'Прохід був заблокований залізним засувом і навісним замком. Суцільне жахіття!'::text),
