(348605,38734,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapı aralığı demir bir sürgü ve asma kilitle ..., tam bir kâbus!'::text,'kapatılmıştı'::text,'kapattı'::text,'kapatıyor'::text,'Kapı aralığı demir bir sürgü ve asma kilitle kapatılmıştı, tam bir kâbus!'::text),
