(348613,38735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... залізний засув, і жахіття з проходом нарешті скінчилося!'::text,'зняла'::text,'була знята'::text,'знімаючи'::text,'Вона зняла залізний засув, і жахіття з проходом нарешті скінчилося!'::text),
