(348622,38736,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, той прохід ... вести до таємного саду, але ніхто точно не знає.'::text,'може'::text,'мусить'::text,'не може'::text,'Подруго, кажуть, той прохід може вести до таємного саду, але ніхто точно не знає.'::text),
